  ui_story_5080_50800100_78_dialog_content = "하지만 방어를 선택해 놓고도... 창병, 당신은 왜 계속 저격수 보호에 정신이 팔렸던 거지?\n저격수는 당신보다 민첩해. 그러니까 당신은 뒤에 있는 대상부터 지켰어야지.",
