  ui_story_5080_50800100_85_dialog_content = "놀랄 거 없어. 그 정도는 첫눈에 바로 알아낼 수 있는 정보들이니까.",
  ui_story_5080_50800100_86_dialog_content = "그리고 너, 아이테르... 원래 일루미나의 임무에 외부인을 데려갈 순 없지만,\n이건 군단장님 뜻이니까 난 불만 없어.",
  ui_story_5080_50800100_87_dialog_content = "고맙다고 해야 하는 건가...",
  ui_story_5080_50800100_88_dialog_content = "난 레이첼이야. 이번 임무에선 너희의 직속상관이고.",
  ui_story_5080_50800100_89_dialog_content = "어... 반가워, 난...",
  ui_story_5080_50800100_90_dialog_content = "임무를 수행하는 동안 우린 한 팀이고, 임무가 끝나면 즉시 해산할 거야.\n그리고 지휘의 편의를 위해 너희가 사용할 작전 코드명을 준비했어.",
