  ui_story_5080_50800100_93_dialog_content = "......",
  ui_story_5080_50800100_94_dialog_content = "그리고 백야성의 공주, 당신은 완전히 정원 외 인원이지만,\n두 사람과 함께 온 이상 임무 협정에 동의한다는 뜻이겠지.",
  ui_story_5080_50800100_95_dialog_content = "그러니 이제부턴 당신을 「화이트 랜서」라고 부르겠어.",
  ui_story_5080_50800100_96_dialog_content = "역시나라고 할까... 참 일루미나의 군인답네...",
