  ui_story_5080_50800100_98_dialog_content = "특수 작전 소대는 원래 이런 스타일인걸... 카렌, 대장한테 악의는 없을 거야.",
  ui_story_5080_50800100_99_dialog_content = "너희도 날 「호크헌터 0호」, 아니면 「대장」이라고 불러도 좋아.",
  ui_story_5080_50800100_100_dialog_content = "...알겠어, 일루... 호크헌터 0호.",
  ui_story_5080_50800100_101_dialog_content = "(아까까지만 해도 신경 써 주는 것 같았는데, 지금은 오히려... 일부러 차갑게 대하는 것 같잖아.)",
  ui_story_5080_50800100_102_dialog_content = "레... 대장님! 대장님은 절 모르실 수도 있지만, 전 대장님 후배예요!\n전공도 다르지만, 전 계속 대장님 소식에 관심이 있었어요.",
  ui_story_5080_50800100_103_dialog_content = "내... 소식...?",
  ui_story_5080_50800100_104_dialog_content = "네! 제가 사관학교 생도였을 때부터 대장님이 호크아이 소대를 이끌고\n큰 활약을 펼치신 걸 들었거든요!",
  ui_story_5080_50800100_105_dialog_content = "나중엔 대장님이 영웅 훈장을 받으실 때마다, 히이로 군단장님도 저희한테\n소식을 전해 주시면서 잘 보고 배우라고 하셨어요.",
  ui_story_5080_50800100_106_dialog_content = "그 뒤엔 많은 일이 있었고, 제가 PlayerName하고 동료가 돼서 함께 다니면서부턴 일루미나에 자주 돌아가지 못했지만, 그래도 대장님은 제 동경의 대상이었어요!",
  ui_story_5080_50800100_107_dialog_content = "한동안 대장님 소식을 통 알 수 없길래 짐작만 하고 있었는데,\n지금 보니까 호크아이 소대는 비밀 임무를 수행하고 있었던 거군요!",
  ui_story_5080_50800100_108_dialog_content = "......",
  ui_story_5080_50800100_109_dialog_content = "이번 임무는 대장님이 지휘하시니까 분명히 멋지게 완수할 수 있겠죠!\n저도 이번 기회에 제대로 보고 배울게요!",
  ui_story_5080_50800100_110_dialog_content = "어쨌든 잡담은 이쯤 하고 날 따라와. 너희에게 임무에 대해 설명해 줄 테니까.",
  ui_story_5080_50800100_111_dialog_content = "(왠지... 과거 얘기가 나오는 걸 엄청 껄끄러워하는 것 같은데?\n전설적인 인물이라고 하지 않았나...?)",
  ui_story_5080_50800100_112_dialog_content = "이번 임무는 내가 소대를 이끌고 레디젤 렌치의 근거지인 사막 깊은 곳에 들어가서,\n어떤 특수한 암귀를 조사하는 거야.",
  ui_story_5080_50800100_113_dialog_content = "그 암귀는 고온 환경에서 출몰하고, 용암의 힘을 다룰 수 있어서,\n녀석들이 나타난 지역엔 뚜렷하게 흔적이 남지.",
  ui_story_5080_50800100_114_dialog_content = "극도로 위험한 존재들이니까, 절대 무모하게 행동하지 마.",
  ui_story_5080_50800100_115_dialog_content = "예상밖의 상황이 벌어지지 않도록, 너흰 전적으로 내 지시에 따라 행동해야 해.",
  ui_story_5080_50800100_116_dialog_content = "그리고 내가 개인적으로 조사할 일도 있어. 그 시간엔 너희 모두 자유롭게 움직여도 좋아.",
  ui_story_5080_50800100_117_dialog_content = "무슨 일인데요?",
  ui_story_5080_50800100_118_dialog_content = "<color=#FFB400>프리버드</color> 소대에 대해 들어 본 적 있어?",
  ui_story_5080_50800100_119_dialog_content = "못 들어 본 것 같아요... 죄송해요.",
  ui_story_5080_50800100_120_dialog_content = "그럼 됐어. 이건 너희 임무 밖의 일이니까 굳이 협조하지 않아도 돼.\n다만... 혹시라도 단서를 발견한다면 내게 알려주면 좋겠어.",
  ui_story_5080_50800100_121_dialog_content = "우린 레디젤 렌치의 리더 사메야마랑 사이가 괜찮으니까,\n암귀 조사 문제는 그냥 바로 가서 물어봐도 괜찮을 것 같아.",
  ui_story_5080_50800100_122_dialog_content = "그렇구나... 어쩌면 그게 대원수님이 너흴 지목하신 이유일지도 모르겠네.\n친분으로 정보를 교환할 수 있다는 건 효율적이지. 승인해 줄게, 다녀와.",
  ui_story_5080_50800100_123_dialog_content = "네? 그럼 대장님은...",
  ui_story_5080_50800100_124_dialog_content = "난 일루미나의 소대장이야. 사막의 도적과는 친분이 없어.\n게다가 그 지명수배자들과 마주치면 체포하고 싶은 충동이 들 거야.",
  ui_story_5080_50800100_125_dialog_content = "내 신경은 쓰지 말고 너희끼리 다녀와. 난 혼자 정찰을 하러 갈 테니까.",
  ui_story_5080_50800100_126_dialog_content = "혼자서요? 너무 위험하잖아요... 차라리 두 명씩 팀을 나누면 어떨까요?",
  ui_story_5080_50800100_127_dialog_content = "처음 만난 나와 팀을 이루는 것보단, 이미 팀워크가 형성된 너희 셋을 합치는 게 더 강해.",
  ui_story_5080_50800100_128_dialog_content = "여기서 흩어지자. 너흰 레디젤 렌치에 가서 정보를 수집해. 이건 명령이야.",
  ui_story_5080_50800100_129_dialog_content = "나중에 내가 너흴 찾아갈 테니까.",
  ui_story_5080_50800100_130_dialog_content = "이렇게 그냥 가는 거야? 진짜 단호하네.",
  ui_story_5080_50800100_131_dialog_content = "무례하긴 해도, 군인으로선 확실히 훌륭한걸.",
  ui_story_5080_50800100_132_dialog_content = "...바이스, 난 아까 레이첼이 말한 그 소대가 좀 신경 쓰여.",
  ui_story_5080_50800100_133_dialog_content = "「프리버드」, 그리고 「호크아이」... 괜한 생각인가? 왠지 뭔가 관계가 있을 것 같단 말이지.",
  ui_story_5080_50800100_134_dialog_content = "그건 아마 우리 일루미나의 부대 명명법일 텐데... 어라? 「프리버드」 소대면, 일루미나 소속...?",
  ui_story_5080_50800100_135_dialog_content = "이번 임무는 암귀 조사야.\n하지만 저 소대장은 어째서 일루미나의 소대에 대한 정보를 찾고 있는 거지?",
  ui_story_5080_50800100_136_dialog_content = "언뜻 보면 아무런 관계도 없어 보이지만... 저런 사람이 무의미한 행동을 할 것 같진 않아.",
  ui_story_5080_50800100_137_dialog_content = "너희가 그러니까 나도 궁금해지잖아...\n그래, 이럴 땐 정보부장 찬스를 써야지. 필리시 선배한테 물어보면 답이 나올 거야.",
  ui_story_5080_50800100_138_dialog_content = "하암── 우리 바이스가 이렇게 갑자기 연락이라니, 무슨 곤란한 일이라도 생긴 거냥?",
  ui_story_5080_50800100_139_dialog_content = "필리시 선배, 물어볼 게 하나 있어요.\n혹시 「프리버드」라는 이름이나, 관련 정보에 대해 들어 본 적 있어요?",
  ui_story_5080_50800100_140_dialog_content = "으음... 우리 일루미나의 소대 같긴 한데, 그런 명명법은 이젠 옛날 스타일이다냥.\n그래도 서류를 뒤져 보면 뭔가 정보를 찾을 수 있을 거다냥.",
  ui_story_5080_50800100_141_dialog_content = "그럼 부탁해요, 필리시 선배. 지금 그게 너무 궁금하거든요.\n다음에 돌아가면 제가 말린 생선 쏠게요.",
  ui_story_5080_50800100_142_dialog_content = "기밀 같은 것만 아니면 알려줘도 문제없다냥... 뭐, 말린 생선은 약속대로 잊지 말라냥.",
  ui_story_5080_50800100_143_dialog_content = "오래 기다렸다냥. 바이스 네가 물어 본 그 소대는 약 40년 전에 위험 임무를 수십 차례나 완벽하게 수행했던, 명실상부한 특수 작전 소대였다냥.",
  ui_story_5080_50800100_144_dialog_content = "기록에 따르면 「프리버드」가 맡은 마지막 임무는 레디젤 사막에서 무언가를 찾는 거였는데...\n그땐 실패해 버렸다고 한다냥.",
  ui_story_5080_50800100_145_dialog_content = "그다음 내용은 고도로 암호화돼 있어서, 나조차도 확인할 방법이 없는 등급이다냥.",
  ui_story_5080_50800100_146_dialog_content = "네? 정보부장조차 마음대로 열람할 수 없는 자료가 있단 말이에요?",
  ui_story_5080_50800100_147_dialog_content = "심지어 소대장이 누구였는지도 찾을 수가 없다냥.\n이 정도 보안 등급이 이렇게 오랫동안 유지된 걸 보면, 어쩌면 탈영병지도 모르겠다냥.",
  ui_story_5080_50800100_148_dialog_content = "이건 정말 엄청난 사안이다냥. 근데 바이스, 어디서 그 이름을 들은 거냥?",
  ui_story_5080_50800201_1_dialog_content = "엄청 늦네... 사메야마는 왜 아직도 안 오는 거야?",
  ui_story_5080_50800201_2_dialog_content = "다들 멀리서 바쁘게 뭘 하고 있었어. 무슨 공사를 하는 모양이야.",
  ui_story_5080_50800201_3_dialog_content = "......",
  ui_story_5080_50800201_4_dialog_content = "바이스, 표정이 안 좋네... 괜찮아?",
  ui_story_5080_50800201_5_dialog_content = "응? 괜찮아. 그냥... 대장님이 왜 그 소대에 대한 걸 물었을까 생각 중이었어.",
  ui_story_5080_50800201_6_dialog_content = "심지어 탈영병으로 의심되는 소대였고 말이야.",
  ui_story_5080_50800201_7_dialog_content = "레이첼은 정찰 임무를 주로 맡는 특수 부대원인 거겠지?",
  ui_story_5080_50800201_8_dialog_content = "그럼 혹시 탈영병을 조사하고 있는 건 아닐까?",
  ui_story_5080_50800201_9_dialog_content = "그치만 벌써 그렇게나 오래된 일인데, 아직까지도 계속 추적하고 있단 말이야?",
  ui_story_5080_50800201_10_dialog_content = "아니면... 그 소대가 레이첼이랑 무슨 관계가 있는 건가?",
  ui_story_5080_50800201_11_dialog_content = "「프리버드」... 그리고 「호크아이」...",
  ui_story_5080_50800201_12_dialog_content = "어이! 너희들, 뭘 그렇게 죽상인 거냐?",
  ui_story_5080_50800201_13_dialog_content = "사메야마!",
  ui_story_5080_50800201_14_dialog_content = "오랜만이다, 애송이. 이젠 제법 다부져 보이는데? 어때, 우리랑 일할 생각 없냐?",
  ui_story_5080_50800201_15_dialog_content = "그건 아무래도 좀...",
  ui_story_5080_50800201_16_dialog_content = "하하하하하! 괜찮아, 나중에 내킬 때면 언제든지 말하라고!\n그래서 오늘은 또 뭔 일이지? 여기까지 다 찾아오고 말이야.",
  ui_story_5080_50800201_17_dialog_content = "실은 우리가 이번에 특별한 임무를 하나 받았거든...\n혹시 사막에서 무슨 특이한 암귀 같은 거 본 적 있어?",
  ui_story_5080_50800201_18_dialog_content = "하아? 예를 좀 들어 봐.",
  ui_story_5080_50800201_19_dialog_content = "어... 그러니까... 아마 엄청 뜨거워 보이고, 화산을 좋아하는 그런 암귀일려나...?",
  ui_story_5080_50800201_20_dialog_content = "그게 뭔 소리야? 여기 화산 지대엔 발에 치이는 게 암귀라고.",
  ui_story_5080_50800201_21_dialog_content = "화산에 가까이 살고, 용암을 다룰 줄 아는 암귀야.",
  ui_story_5080_50800201_22_dialog_content = "몹시 강하고, 지나간 자리엔 확연한 흔적을 남겨.",
  ui_story_5080_50800201_23_dialog_content = "혹시 이런 암귀에 대해 뭔가 떠오르는 거 있어?",
  ui_story_5080_50800201_24_dialog_content = "「용암의 암귀」라... 그건 불가능해. 그런 암귀는 이미 십수 년 전부터 모습을...",
  ui_story_5080_50800201_25_dialog_content = "아는구나?",
  ui_story_5080_50800201_26_dialog_content = "더 자세히 말해 줘. 마침 녀석에 대한 정보가 필요하거든.",
  ui_story_5080_50800201_27_dialog_content = "애초에 케케묵은 일이고, 게다가 우리 식구들 과거와 얽힌 일이기도 한데...",
  ui_story_5080_50800201_28_dialog_content = "뭐, 됐어. 알고 싶다면 말해줄 순 있어.",
  ui_story_5080_50800201_29_dialog_content = "내가 그런 암귀를 알고 있는 건 맞다. 아니...\n정확히는 우리 <color=#FFB400>레디젤 렌치</color>의 고참 멤버들에게 놈은 철천지원수다.",
  ui_story_5080_50800201_30_dialog_content = "왜 그런 거지?",
  ui_story_5080_50800201_31_dialog_content = "그건 십몇 년 전쯤, <color=#FFB400>어둠의 위기</color> 때 있었던 일이다.\n그때만 해도 난 대장 밑에서 심부름이나 하는 꼬맹이였지.",
  ui_story_5080_50800201_32_dialog_content = "근데 어느 날, 갑자기 암귀들이 모래폭풍처럼 들이닥쳤고,\n우린 그 무렵의 터전에서 쫓겨나는 신세가 됐다.",
  ui_story_5080_50800201_33_dialog_content = "우리 어린애들이 무사히 피할 수 있게 엄호해 주려고,\n대장은 사람들을 데리고 후방을 막으러 갔다.",
  ui_story_5080_50800201_34_dialog_content = "아직도 기억나는군... 그 암귀 무리 중엔 두려울 정도로 강한 놈이 하나 있었지.\n놈은 용암으로 모래를 불태워 유리로 만들어 버렸거든...",
  ui_story_5080_50800201_35_dialog_content = "...어?",
  ui_story_5080_50800201_36_dialog_content = "뭐야, 잘 못 들은 거냐? 놈은...",
  ui_story_5080_50800201_37_dialog_content = "뭐야?!",
  ui_story_5080_50800201_38_dialog_content = "우와아아아──!",
  ui_story_5080_50800201_39_dialog_content = "미안해! <color=#FFB400>저주받은 광전사</color>! 빨리 도와줘!",
  ui_story_5080_50800201_40_dialog_content = "PlayerName, 위험해!",
  ui_story_5080_50800201_41_dialog_content = "으아아──! 당장 멈춰!",
  ui_story_5080_50800201_42_dialog_content = "으아아악──",
  ui_story_5080_50800201_43_dialog_content = "사랑하는 달링~ 노래는 멈추지 않아~",
  ui_story_5080_50800201_44_dialog_content = "엄청난 괴력이야! 역시 <color=#FFB400>저주받은 광전사</color>라니까!",
  ui_story_5080_50800201_45_dialog_content = "제타?! 그리고 바바라, 타이니? 너희 지금 뭐 하는 거냐?",
  ui_story_5080_50800201_46_dialog_content = "트럭으로 캠프를 들이받다니, 소란을 피워도 적당히 좀...",
  ui_story_5080_50800201_47_dialog_content = "설명할 시간 없어! 빨리 차 타!",
  ui_story_5080_50800201_48_dialog_content = "하아?!",
  ui_story_5080_50800201_49_dialog_content = "<color=#FFB400>저주받은 광전사</color>! 이 소리 안 들려? 저 멀리서 들려오는 발소리가...!",
  ui_story_5080_50800201_50_dialog_content = "봐! 와 버렸다구! 「사막의 정예 사냥꾼」이!",
  ui_story_5080_50800201_51_dialog_content = "저기 좀 봐! 저건...",
  ui_story_5080_50800201_52_dialog_content = "<size=45>레이첼?!</size>",
  ui_story_5080_50800201_53_dialog_content = "저건 또 뭐 하는 녀석이야? 제타, 똑바로 설명해. 너희 대체 뭔 짓을 한 거야?",
  ui_story_5080_50800201_54_dialog_content = "망했다...",
  ui_story_5080_50800201_55_dialog_content = "으으, 에어백 때문에 끼어서 내릴 수가 없어!",
  ui_story_5080_50800201_56_dialog_content = "뭐 대단한 일이라고. 차 문을 뜯어 줄 테니까 기다려.",
  ui_story_5080_50800201_57_dialog_content = "안 돼! 빨리 저 녀석한테서 도망쳐야 한단 말이야! 저 여자는 「마왕의 앞잡이」라구!",
  ui_story_5080_50800201_58_dialog_content = "「레디젤 사막의 도적」, 어서 훔친 물건을 내놔!",
  ui_story_5080_50800201_59_dialog_content = "흥, 잘도 큰소리를 치는군.",
  ui_story_5080_50800201_60_dialog_content = "가만 보니까 일루미나의 병사잖아?",
  ui_story_5080_50800201_61_dialog_content = "레이첼! 사메야마! 둘 다 내 얘기 좀...",
  ui_story_5080_50800201_62_dialog_content = "시끄러워!",
  ui_story_5080_50800201_63_dialog_content = "일루미나 녀석이 우리 애들을 뒤쫓은 걸로도 모자라서, 우리 캠프에 차를 들이받게 만들다니...",
  ui_story_5080_50800201_64_dialog_content = "사막에서 도적질을 하는 걸로도 모자라서, 감히 겁도 없이 내 「전우」를 훔쳐? 용서 못 해...",
  ui_story_5080_50800201_65_dialog_content = "오? 한번 붙어 보자 이거냐? 일루미나 녀석이랑 치고받는 것도 꽤 오랜만인데 말이야.",
  ui_story_5080_50800201_66_dialog_content = "얼마든지 덤벼.",
  ui_story_5080_50800201_67_dialog_content = "상황이 안 좋아... 바이스, 카렌! 우리가 얼른 두 사람을 막아야 해!",
  ui_story_5080_50800201_68_dialog_content = "내가 지휘를 맡을게. 동시에 움직이자!",
  ui_story_5080_50800202_1_dialog_content = "귀찮게 날아다니는 것들... 싹 다 꺼져!",
  ui_story_5080_50800202_2_dialog_content = "이제 어쩔 생각이지?",
  ui_story_5080_50800202_3_dialog_content = "움직이지 마, 터져서 날아가고 싶지 않으면.",
  ui_story_5080_50800202_4_dialog_content = "오? 언제 내 손에 폭탄을 붙였지? 꽤 빠르잖아?",
  ui_story_5080_50800202_5_dialog_content = "이 거리에서 폭탄이 터지면 너나 나나 무사하지 못해.",
  ui_story_5080_50800202_6_dialog_content = "죽는 걸 두려워하지 않는 녀석이었나... 재미있네, 그럼 어디 한번 해 볼까!",
  ui_story_5080_50800202_7_dialog_content = "「레디젤 렌치의 수괴」가 상대라면, 내 목숨과 맞바꿀 가치는 충분해...",
  ui_story_5080_50800202_8_dialog_content = "잠깐! 스톱! 멈춰! 둘 다 일단 진정 좀 하라니까!",
  ui_story_5080_50800202_9_dialog_content = "그래요, 대장님! 아직 임무를 수행해야 하잖아요! 임무를 생각하라구요!",
  ui_story_5080_50800202_10_dialog_content = "사메야마, 너한테 무슨 일이라도 생기면 다른 사람들은 어쩌려고 그래?",
  ui_story_5080_50800202_11_dialog_content = "여긴 다른 「아이들」도 있잖아.",
  ui_story_5080_50800202_12_dialog_content = "「아이들」?",
  ui_story_5080_50800202_13_dialog_content = "으아아앙!",
  ui_story_5080_50800202_14_dialog_content = "대체 무슨 일이 있었던 거야? 같이 얘기해 보고 해결할 방법을 찾아보자. 응?",
  ui_story_5080_50800202_15_dialog_content = "우리가 「마왕의 앞잡이」를 건드린 탓이야... 나 혼자 책임질 테니까 「내 동료들」은 놔줘!",
  ui_story_5080_50800202_16_dialog_content = "......",
  ui_story_5080_50800202_17_dialog_content = "제타, 대체 뭐가 어떻게 된 거냐.",
  ui_story_5080_50800202_18_dialog_content = "이 모든 건 용사 제타의 전설에서 시작됐어...",
  ui_story_5080_50800202_19_dialog_content = "용사 제타는 운전 기술을 열심히 갈고닦았지만, 그래도 「레이싱카의 마녀」를 당해내진 못했어.",
  ui_story_5080_50800202_20_dialog_content = "그건 분명 마녀가 「아이테르」 같은 강한 조력자를 찾았기 때문인 거겠지!\n그렇게 생각한 용사 제타는 동료를 찾기 위한 여정에 나섰어.",
  ui_story_5080_50800202_21_dialog_content = "바로 그때! 전설 속 <color=#FFB400>신예 음유시인</color> 바바라가 나타났어!\n그리고 레지나도! 두 사람은 음유시인 대회를 놓고 다투고 있었지.",
  ui_story_5080_50800202_22_dialog_content = "「저기, 용사 제타~ 네 힘으로 나 좀 도와줘.」",
  ui_story_5080_50800202_23_dialog_content = "「너만 있으면 난 레지나보다 먼저 더 많은 관객을 모을 수 있을 거야.\n관객은 내 힘의 원천이거든!」",
  ui_story_5080_50800202_24_dialog_content = "「좋은 생각이야! 그리고 잊지 마! 용사 제타의 가장 충직한 <color=#FFB400>웨폰마스터</color>인 나도 있다는 거!」",
  ui_story_5080_50800202_25_dialog_content = "아! 설마... 이 두 사람이 바로 용사의 빛에 이끌려 온 동료란 말인가!",
  ui_story_5080_50800202_26_dialog_content = "아무튼 그래서 용사 일행은 분노의 도로 투어에서 레지나보다 먼저\n더 많은 관객을 모으기 위한 여정을 떠났어.",
  ui_story_5080_50800202_27_dialog_content = "바로 이 최신식 <color=#FFB400>레디젤 슈퍼 아이돌 스테이지</color> 전차로 결전을...",
  ui_story_5080_50800202_28_dialog_content = "스톱! 그게 다 뭐야 도대체... 빨리 요점만 말해.",
  ui_story_5080_50800202_29_dialog_content = "...휴.",
  ui_story_5080_50800202_30_dialog_content = "용사 일행이 험난한 사막을 누비며 희망의 노래를 전하고 있을 때, 용사 제타는 발견했어!",
  ui_story_5080_50800202_31_dialog_content = "고독하고, 강인한 한 마리의 매를 말이야.",
  ui_story_5080_50800202_32_dialog_content = "저 녀석, 조명이나 스피커로 쓰면 딱이겠는데?",
  ui_story_5080_50800202_33_dialog_content = "웨폰마스터는 그렇게 말했지만! 제타는 그 매가 고귀한 정신을 지녔다는 걸 알아봤어.",
  ui_story_5080_50800202_34_dialog_content = "그래서 제타는 그 고독한 매도 동료로 받아 주기로 결정했지!",
  ui_story_5080_50800202_35_dialog_content = "그치만 고독한 매를 뒤쫓는 사악한 앞잡이가 들이닥쳤고,\n계속 따라다니는 걸로도 모자라서, 우릴 공격하기까지 했어.",
  ui_story_5080_50800202_36_dialog_content = "사악한 앞잡이의 총알은 너무 무서웠고, 용사 제타는 겁이...\n아, 아니, 동료들의 안전을 위해 함부로 차를 세울 수 없었어!",
  ui_story_5080_50800202_37_dialog_content = "그래서 속도를 잔뜩 내다가 캠프를 들이받았다는 거냐?",
  ui_story_5080_50800202_38_dialog_content = "제타는 광전사라면 트럭을 세워줄 수 있을 거라고 믿고 있었거든!",
  ui_story_5080_50800202_39_dialog_content = "이 자식아...",
  ui_story_5080_50800202_40_dialog_content = "...장난은 집어치워.",
  ui_story_5080_50800202_41_dialog_content = "당장 <color=#FFB400>호크헌터 3호</color>를 돌려줘.",
  ui_story_5080_50800301_1_dialog_content = "얘 이름이 <color=#FFB400>호크헌터 3호</color>였구나? 이름도... 엄청 멋있네!",
  ui_story_5080_50800301_2_dialog_content = "알겠어... <color=#FFB400>호크헌터 3호</color>는 주인이 없는 고독한 매가 아니었으니까...\n지금 바로 돌려줄게. 이제 싸우지 마...",
  ui_story_5080_50800301_3_dialog_content = "어이, 멋대로 왔다가 멋대로 갈 수 있을 것 같냐?",
  ui_story_5080_50800301_4_dialog_content = "일루미나 녀석이 겁도 없이 우리 캠프를 부수고, 우리 꼬맹이들도 다치게 만들어 놓고,\n이대로 그냥 내빼겠다?",
  ui_story_5080_50800301_5_dialog_content = "쟤들이 내 <color=#FFB400>호크헌터 3호</color>를 빼앗아 간 게 먼저야.\n당신이 멋대로 말한다고 이치가 달라지진 않아.",
  ui_story_5080_50800301_6_dialog_content = "그럼 이런 말은 못 들어봤나? 레디젤 렌치는 「이치보다 식구가 먼저」라고.",
  ui_story_5080_50800301_7_dialog_content = "더 해볼 생각인가?",
  ui_story_5080_50800301_8_dialog_content = "둘 다 그만 좀 해!",
  ui_story_5080_50800301_9_dialog_content = "무슨 일이야? 밖은 난장판이고, 여긴 또 분위기가 왜 이렇게 갑갑해?",
  ui_story_5080_50800301_10_dialog_content = "예리아?!\n예리아 씨?!",
  ui_story_5080_50800301_11_dialog_content = "뭔 바람이 불어서 여기까지 온 거냐?",
  ui_story_5080_50800301_12_dialog_content = "나도 딱히 외출하고 싶진 않았는데... 사메야마, 화산이 「포효」하고 있는 게 들려?",
  ui_story_5080_50800301_13_dialog_content = "「분노의 화산」이 깨어났어. <color=#FFB400>15년 전</color> 그때처럼.",
  ui_story_5080_50800301_14_dialog_content = "...뭐라고?",
  ui_story_5080_50800301_15_dialog_content = "대장! 여긴 괜찮아?",
  ui_story_5080_50800301_16_dialog_content = "바깥은 어떻게든 전부 처리했어. 다들 괜찮지?",
  ui_story_5080_50800301_17_dialog_content = "어이, 타이니, 바바라, 그리고 제타, 다들 어디 있어?",
  ui_story_5080_50800301_18_dialog_content = "이 자식들아! 단체로 몰려오지 말라고!",
  ui_story_5080_50800301_19_dialog_content = "아직 얘기하는 중이잖아, 어이! 그만해! 이 바보들아──!",
  ui_story_5080_50800301_20_dialog_content = "「분노의 화산」이 깨어났다고 하던데, 그게 진짜야?",
  ui_story_5080_50800301_21_dialog_content = "제타, 빨리 대답해. 너 괜찮은 거야?",
  ui_story_5080_50800301_22_dialog_content = "난 괜찮아! 「마음씨 고운 공주님」!",
  ui_story_5080_50800301_23_dialog_content = "「분노의 화산」의 움직임이 들렸어. 으르렁거리는 걸 보면 분명히 깨어난 거야.",
  ui_story_5080_50800301_24_dialog_content = "<color=#FFB400>어둠의 위기</color> 때 분화한 뒤로 지금까지 쭉 잠들어 있었는데, 대체 무슨 일이 벌어...",
  ui_story_5080_50800301_25_dialog_content = "<size=45>다들 입 좀 다물어!</size>",
  ui_story_5080_50800301_26_dialog_content = "젠장할, 그 일루미나 녀석 어디 갔어?",
  ui_story_5080_50800301_27_dialog_content = "응? 어느 일루미나 녀석? 나?",
  ui_story_5080_50800301_28_dialog_content = "허억... 허억...",
  ui_story_5080_50800301_29_dialog_content = "하아... 여기까지 왔으면... 하아... 괘, 괜찮겠지?",
  ui_story_5080_50800301_30_dialog_content = "이, 일단 말하지 말고 숨부터 골라.",
  ui_story_5080_50800301_31_dialog_content = "아깐 진짜 위험했어. 아무리 우리가 사메야마랑 아는 사이라지만, 아마 수습하기 힘들었을 거야.",
  ui_story_5080_50800301_32_dialog_content = "네가 기회를 포착해 우리 모두 빠져나올 수 있어서 다행이었어.",
  ui_story_5080_50800301_33_dialog_content = "...이미 예상한 일이었어. 그 녀석들과는 말이 통하지 않아.",
  ui_story_5080_50800301_34_dialog_content = "녀석들은 탈영병들로 이루어진 도적단이니까.",
  ui_story_5080_50800301_35_dialog_content = "그렇지 않아!",
  ui_story_5080_50800301_36_dialog_content = "레디젤 렌치 사람들이 그렇게까지 나쁘진 않다고...\n대화로 잘 풀었으면 사메야마도 막무가대로 나오진 않았을 거야.",
  ui_story_5080_50800301_37_dialog_content = "그리고 다들 레디젤 사막에서 오래 지냈으니까, 「프리버드」의 소식을 알지도 모르고...",
  ui_story_5080_50800301_38_dialog_content = "탈영병이 얼마나 믿을 수 있는지를 두고 입씨름하는 건 무의미해. 이 이야기는 여기서 끝내자.",
  ui_story_5080_50800301_39_dialog_content = "너희가 녀석들 캠프에 가 있는 동안, 나도 이번 임무의 조사 대상이 남긴 흔적을 찾아냈어. 따라와.",
  ui_story_5080_50800301_40_dialog_content = "내 말 아직 안 끝났는데...",
  ui_story_5080_50800301_41_dialog_content = "봐, 고온에서 불탄 모래야. 그리고 화산재의 흔적까지...",
  ui_story_5080_50800301_42_dialog_content = "틀림없어. 바로 이 앞에 있어.",
  ui_story_5080_50800301_43_dialog_content = "근데... 대상이 하나가 아닌 것 같아요.",
  ui_story_5080_50800301_44_dialog_content = "타깃이 「증식」했을 가능성이 높아. 다들 조심해.",
  ui_story_5080_50800301_45_dialog_content = "대장님! 녀석들을 포착했어요!",
  ui_story_5080_50800301_X45_dialog_content = "그어어... 크으...",
  ui_story_5080_50800301_46_dialog_content = "저건... 용암... 아니, 암귀들인가?",
  ui_story_5080_50800301_47_dialog_content = "전에 봤던 암귀하곤 완전히 달라. 저 녀석들은 무슨 걸어 다니는 용암처럼 생겼어...",
  ui_story_5080_50800301_48_dialog_content = "생김새가 너무 이상해. 게다가 약점도 이렇게 봐서는 모르겠어.",
  ui_story_5080_50800301_49_dialog_content = "저렇게 높은 열에너지로 보호받고 있다면, 원거리 공격은 큰 효과가 없을 거야.",
  ui_story_5080_50800301_50_dialog_content = "전투 준비.",
  ui_story_5080_50800301_51_dialog_content = "하지만...",
  ui_story_5080_50800301_52_dialog_content = "화이트 랜서, 당신 능력은 녀석들에겐 상극이고, 당신은 정면 돌격이 특기니까, 당신이 선봉에 서.",
  ui_story_5080_50800301_53_dialog_content = "일루미나의 소대장, 당신에게 날 지휘할 권한은 없을 텐데.",
  ui_story_5080_50800301_54_dialog_content = "당신은 「하늘을 나는 말」을 불러낼 수 있지?\n정면 교전 중에 그 힘을 사용해서 불시에 날아올라 공격한다면 기습이 가능할 거야.",
  ui_story_5080_50800301_55_dialog_content = "녀석들의 구조를 보면 열에너지로 온몸을 방어하는 건 힘들어.\n일단 빈틈이 보이면 당신 기술로 녀석들을 단번에 없앨 수 있을 거야.",
  ui_story_5080_50800301_56_dialog_content = "......",
  ui_story_5080_50800301_57_dialog_content = "해칠링 2호, 넌 기동성을 발휘해서 화이트 랜서가 교전하는 동안\n「속사 감지」로 저 암귀들을 공격해.",
  ui_story_5080_50800301_58_dialog_content = "어떤 암귀든 공격하는 순간엔 반드시 약점을 드러내기 마련이야.\n그리고 그때가 바로 네 능력을 발휘할 순간이야.",
  ui_story_5080_50800301_59_dialog_content = "약점에 공격이 명중하면 녀석들은 반드시 균형을 잃을 테니,\n화이트 랜서, 그때가 녀석들을 없앨 기회야.",
  ui_story_5080_50800301_60_dialog_content = "네!",
  ui_story_5080_50800301_61_dialog_content = "나와 호크헌터 1호, 2호, 3호는 암귀들의 공격을 압박해서 녀석들을 화이트 랜서 쪽으로 유인할게.",
  ui_story_5080_50800301_62_dialog_content = "지속적인 공격으로 견제한다면, 효과적으로 녀석들을 한데 모을 수 있고,\n그럼 저 괴물 녀석들을 하나씩 처치하는 게 가능해질 거야.",
  ui_story_5080_50800301_63_dialog_content = "그 전술이라면... 당신 말대로 하자고.",
  ui_story_5080_50800301_64_dialog_content = "(딱 한 번 본 것만으로도 카렌이랑 바이스의 능력을 꿰뚫어 보고, 맞춤형 전술까지 세우다니...)",
  ui_story_5080_50800301_65_dialog_content = "아이테르 1호.",
  ui_story_5080_50800301_66_dialog_content = "...네!",
  ui_story_5080_50800301_67_dialog_content = "전투 중 지휘는 네게 맡길게.",
  ui_story_5080_50800301_68_dialog_content = "어?",
  ui_story_5080_50800301_69_dialog_content = "아무리 준비를 철저히 한다고 해도, 전투 상황은 항상 순식간에 변하기 마련이야.",
  ui_story_5080_50800301_70_dialog_content = "넌 우리에겐 보이지 않는 「빛」을 볼 수 있어.\n그러니까 전투 중엔 네가 나보다 더 명확한 지시를 내릴 수 있을 거야.",
  ui_story_5080_50800301_71_dialog_content = "...게다가, 너흰 이미 훌륭한 팀워크를 가지고 있어.",
  ui_story_5080_50800301_72_dialog_content = "그러니 나보다도... 네가 저 둘의 「파트너」로 훨씬 더 적합해.",
  ui_story_5080_50800301_73_dialog_content = "레이첼, 너...",
  ui_story_5080_50800301_74_dialog_content = "대장이라고 불러.",
  ui_story_5080_50800301_75_dialog_content = "준비해, 아이테르 1호!",
  ui_story_5080_50800302_1_dialog_content = "대장님, 조심하세요!",
  ui_story_5080_50800302_2_dialog_content = "윽... 화이트 랜서, 지금이야!",
  ui_story_5080_50800302_3_dialog_content = "「영혼 찌르기」!",
  ui_story_5080_50800302_4_dialog_content = "큰일이야! 대장님이 다치셨어... 어서 빨리...",
  ui_story_5080_50800302_5_dialog_content = "해칠링 2호, 멍하니 뭐 하고 있어? 한 놈이 네 쪽으로 갔어!",
  ui_story_5080_50800302_6_dialog_content = "호크헌터 1호, 호크헌터 2호, 어서 막아!",
  ui_story_5080_50800302_7_dialog_content = "크에엑!",
  ui_story_5080_50800302_8_dialog_content = "...따라잡았어.",
  ui_story_5080_50800302_9_dialog_content = "다 해치웠어... 진짜 큰일 날 뻔했네.",
  ui_story_5080_50800302_10_dialog_content = "해칠링 2호, 뭐 하는 거야?",
  ui_story_5080_50800302_11_dialog_content = "전...",
  ui_story_5080_50800302_12_dialog_content = "넌 병사로서 너무 감정적이야.",
  ui_story_5080_50800302_13_dialog_content = "설령 내가 다쳤더라도 먼저 날 신경 쓸 게 아니라, 임무를 최우선으로 여겨야지.",
  ui_story_5080_50800302_14_dialog_content = "우린 일개 중대 규모의 암귀를 소멸시켰어.\n이 정도 피해는 가장 효율적이면서도 적은 대가야.",
  ui_story_5080_50800302_15_dialog_content = "...설마 저 둘과 너무 오래 같이 지내서... 네가 일루미나의 병사라는 사실을 잊은 거야?",
  ui_story_5080_50800302_16_dialog_content = "그...그런 거 아니에요.",
  ui_story_5080_50800302_17_dialog_content = "말이 너무 심하잖아. 바이스는 그냥 레이첼 네가 걱정돼서 그런 건데.",
  ui_story_5080_50800302_18_dialog_content = "...전투 중에 정신이 다른 곳에 팔리면 예기치 못한 대가를 치를 수도 있어.\n만약 아까 바이스가 다쳤다면 어쩔 셈이지?",
  ui_story_5080_50800302_19_dialog_content = "내 지시를 따랐는데도 임무에 실패했다면, 그건 다 내 책임인 거야.",
  ui_story_5080_50800302_20_dialog_content = "난 내 부하들에 대한 책임을 질 거야... 너희가 날 믿어준다면 말이야.",
  ui_story_5080_50800302_21_dialog_content = "확실히 당신 말대로야. 당신은 노련하고 성숙한 대장이야.",
  ui_story_5080_50800302_22_dialog_content = "이미 당신 생각은 이해했어.",
  ui_story_5080_50800302_23_dialog_content = "카렌?",
  ui_story_5080_50800302_24_dialog_content = "어휴, 진짜... 바이스, 괜찮아?",
  ui_story_5080_50800302_25_dialog_content = "응...",
  ui_story_5080_50800302_26_dialog_content = "이 암귀들... 그리고 시체의 이런 「모습」은...",
  ui_story_5080_50800302_27_dialog_content = "대장님, 아직 피가 나는데요...",
  ui_story_5080_50800302_28_dialog_content = "그냥 가게 둬. 어차피 네 말은 안 들을 거야.",
  ui_story_5080_50800302_29_dialog_content = "저 사람은 우리가 알지 못하는 「짐」을 짊어지고 있어.",
  ui_story_5080_50800302_30_dialog_content = "난 저런 눈빛을 잘 알아. 일루미나의 병사도 백야성 사람들과 닮을 수 있었던 거였구나...",
  ui_story_5080_50800302_31_dialog_content = "난 오랫동안 전선에서 복무했고, 암귀는 셀 수 없이 많이 봐 왔어.",
  ui_story_5080_50800302_32_dialog_content = "하지만 저런 암귀는 나로서도 처음 보는 녀석들이야.",
  ui_story_5080_50800302_33_dialog_content = "머리의 구조로 봤을 때, 놈들은 「어둠의 밑바닥」을 벗어난 지 이미 한참 됐을 거야.",
  ui_story_5080_50800302_34_dialog_content = "게다가 녀석들의 생리학적 구조는 전투를 위해 진화한 암귀들과는 조금 달라.",
  ui_story_5080_50800302_35_dialog_content = "피부는 내열성을 지녔고, 몸엔 에너지를 저장하는 기관이 존재했어...\n놈들은 환경에 맞춰 진화한 거야.",
  ui_story_5080_50800302_36_dialog_content = "정말 이상해. 시체의 잔류 시간도 더 길고...",
  ui_story_5080_50800302_37_dialog_content = "...이상한 점이 하나 더 있어요. 녀석들은 서로 너무 닮았어요.",
  ui_story_5080_50800302_38_dialog_content = "눈치챘구나. 예리하네... 감정적인 면만 빼면, 넌 무척 뛰어난 정찰대장이야.",
  ui_story_5080_50800302_39_dialog_content = "미안한데, 어떤 게 너무 닮았다는 거야? 암귀 생김새는 다 거기서 거기 아냐?",
  ui_story_5080_50800302_40_dialog_content = "다른 암귀들의 겉모습은 사실 「닮았다」기 보다는 「똑같다」는 표현이 더 맞아.",
  ui_story_5080_50800302_41_dialog_content = "그래서 암귀는 애초에 「번식」을 통해 생겨난 게 아닐 거라고 추측하는 병사들도 있어.",
  ui_story_5080_50800302_42_dialog_content = "하지만 이 녀석들은 「후손」이 분명해... 닮긴 했지만 똑같이 생기진 않았으니까.",
  ui_story_5080_50800302_43_dialog_content = "녀석들은 비슷한 「유전적 특성」을 가지고 있어. 마치 대를 이어 이어져 내려온 것처럼 말이야.",
  ui_story_5080_50800302_44_dialog_content = "자료에 따르면 마지막으로 이런 암귀들이 발견된 건 30여 년 전이야.",
  ui_story_5080_50800302_45_dialog_content = "그때 발견된 녀석들보다 덩치가 작고 힘도 약한 걸 보면,\n이 녀석들은 모종의 방식으로 「번식」한 후손들일지도 몰라...",
  ui_story_5080_50800302_46_dialog_content = "나쁘지 않은 추리네.",
  ui_story_5080_50800302_47_dialog_content = "<color=#FFB400>어둠의 위기</color> 때 레디젤 렌치에서도 그런 암귀들을 본 사람들이 있었어.\n그때와 비교하면 너희가 처치한 녀석들은 너무 작고 약해.",
  ui_story_5080_50800302_48_dialog_content = "예리아 씨?! 왜 이젠 예리아 씨까지 귀신처럼 사라졌다 나타났다 하는 거죠?!",
  ui_story_5080_50800302_49_dialog_content = "그거야 이 사막 전체가 내 관할 구역이니까.",
  ui_story_5080_50800302_50_dialog_content = "당신... 호크헌터 3호의 탐지를 피했어?",
  ui_story_5080_50800302_51_dialog_content = "음? 그게 그 드론 이름인 모양이구나? 고장 난 것 같던데.",
  ui_story_5080_50800302_52_dialog_content = "뭐? 호크헌터 3호, 어서 돌아와!",
  ui_story_5080_50800302_53_dialog_content = "15년이 지나 화산이 다시 포효할 때, 녀석들이 또 나타날 줄이야...",
  ui_story_5080_50800302_54_dialog_content = "예리아 씨, 뭔가 알고 계신 건가요?",
  ui_story_5080_50800302_55_dialog_content = "후훗, 나도 그저 <color=#FFB400>답</color>을 찾아다니고 있었을 뿐이야.",
  ui_story_5080_50800302_56_dialog_content = "호크헌터 3호의 「트랜스밋 모듈」이 망가졌잖아... 게다가 어째서 위에 이상한 부품이...",
  ui_story_5080_50800302_57_dialog_content = "아──아── 들려? 다들 안녕──",
  ui_story_5080_50800302_58_dialog_content = "이 목소리는...",
  ui_story_5080_50800302_59_dialog_content = "제타?",
  ui_story_5080_50800302_60_dialog_content = "<color=#FFB400>웨폰마스터</color> 덕분에 미리 고독한 매한테 이걸 달아둘 수 있었어... 이름이 뭐더라...",
  ui_story_5080_50800302_61_dialog_content = "아! 「백도어」... 참 이상한 이름이라니까!\n뭐, 됐어. 아무튼 우리가 그 고독한 매에 연락 수단을 남겨 둔 거야.",
  ui_story_5080_50800302_62_dialog_content = "그 매를 <color=#FFB400>치료</color>하고 싶다면 「페어리 장로」 예리아의 집으로 와.",
  ui_story_5080_50800302_63_dialog_content = "...그런 눈으로 쳐다보지 마. 내가 저런 설정으로 보여?",
  ui_story_5080_50800302_64_dialog_content = "적이 호크헌터 3호에 손을 댔어... 지금 당장 수리해야 해...",
  ui_story_5080_50800302_65_dialog_content = "!!!",
  ui_story_5080_50800302_66_dialog_content = "공구 가방이... 언제 타버린 거지?",
  ui_story_5080_50800302_67_dialog_content = "임무에 너무 몰두해서 그래. 자기 안전은 생각도 안 하고 싸웠잖아.\n아까 그 공격 때 이미 망가져 있었어.",
  ui_story_5080_50800302_68_dialog_content = "저들이 당신 집에 있다는 건... 이 일도 쿠리어 당신과 관계가 있는 건가?",
  ui_story_5080_50800302_69_dialog_content = "난 어떤 과거에 대한 해답을 찾으려고 왔을 뿐이야. 다른 꿍꿍이는 없어.",
  ui_story_5080_50800302_70_dialog_content = "하지만 네게선 무척 익숙한 그림자가 보이는걸.",
  ui_story_5080_50800302_71_dialog_content = "아니면 날 따라와도 좋아. 그럼 우리 모두 각자 원하는 걸 찾을 수 있을지도 모르니까.",
  ui_story_5080_50800302_72_dialog_content = "......",
  ui_story_5080_50800302_73_dialog_content = "예리아 씨는 쿠리어 길드의 장로고, 우리가 믿을 수 있는 사람이야.",
  ui_story_5080_50800302_74_dialog_content = "...가자.",
  ui_story_5080_50800401_1_dialog_content = "번거롭게 만들어서 죄송해요. 어쩌다 보니 차까지 얻어 타게 됐네요.",
  ui_story_5080_50800401_2_dialog_content = "처음 태워 주는 것도 아닌데 뭘. 자, 앉아.",
  ui_story_5080_50800401_3_dialog_content = "으음...",
  ui_story_5080_50800401_4_dialog_content = "앗! 앞에 레디젤 렌치 캠프가 있어! 다들 숙여!",
  ui_story_5080_50800401_5_dialog_content = "걱정 마. 다들 한창 바쁘거든.",
  ui_story_5080_50800401_6_dialog_content = "못 고쳐, 이건 못 고친다고! 짜증 나 죽겠네! 제타는 어디 갔어? 찾으면 절대 가만 안 둬!",
  ui_story_5080_50800401_7_dialog_content = "저거 예리아 차 아냐? 예리아! 식사 준비 끝났다는데, 먹고 갈래?",
  ui_story_5080_50800401_8_dialog_content = "다음에.",
  ui_story_5080_50800401_9_dialog_content = "그럼 아주르 부르러 가야겠네. 다음엔 같이 먹자.",
  ui_story_5080_50800401_10_dialog_content = "예리아 씨, 앞에 함정이 있으니까 천천히 가세요...",
  ui_story_5080_50800401_11_dialog_content = "알려 줘서 고마워.",
  ui_story_5080_50800401_12_dialog_content = "어이, 예리아! 이거 좀 봐봐. 이 책, 《레디젤의 대장이 되는 법》이 아니지?\n내가 글 잘 모른다고 저 녀석들이 나 속인 거 아냐?",
  ui_story_5080_50800401_13_dialog_content = "애초에 그런 책 같은 건 없어. 그리고 네가 아니면 또 누가 속겠니?",
  ui_story_5080_50800401_14_dialog_content = "예리아, 저번에 공구 갖다준다고 고생 많았어.\n이번 주에 시간 괜찮으면 가서 차 개조해 줄게.",
  ui_story_5080_50800401_15_dialog_content = "좋아.",
  ui_story_5080_50800401_16_dialog_content = "예리아 씨... 왠지 조금 달라지신 것 같네요.",
  ui_story_5080_50800401_17_dialog_content = "예전엔 찾기 힘든 곳에 사셨는데, 지금은 레디젤 렌치 사람들이랑 전부 잘 지내시는 것 같아서요.",
  ui_story_5080_50800401_18_dialog_content = "후훗, PlayerName 군은 참 예리하네.",
  ui_story_5080_50800401_19_dialog_content = "사람은 바뀌기 마련이야.",
  ui_story_5080_50800401_20_dialog_content = "어쩌면 예리아 씨 덕분에 저도 다른 사람들과 더 어울려 볼까 생각하게 됐던 건지도 모르겠네요.",
  ui_story_5080_50800401_21_dialog_content = "...저, 저기, 좀 좁은데? 바이스... 뒷자리가 그렇게 넓지가 않다고...!",
  ui_story_5080_50800401_22_dialog_content = "노래란 건 자고로, 모름지기, 크게, 자유롭게 불러야 제맛이지──!",
  ui_story_5080_50800401_23_dialog_content = "아~ 바보는 항상 시끄럽다니까~",
  ui_story_5080_50800401_24_dialog_content = "실패, 좌절, 공포는 널 도망치게 만들었어!",
  ui_story_5080_50800401_25_dialog_content = "도망은 골칫거리만 가져올 뿐!",
  ui_story_5080_50800401_26_dialog_content = "제타의 운전 실력은 별로야~ 하지만 친구라면 괜찮다고 해 줘야지~",
  ui_story_5080_50800401_27_dialog_content = "바이스, 너 안색이 안 좋아. 무슨 일 있어?",
  ui_story_5080_50800401_28_dialog_content = "아, 아무것도 아니야...\n대장님, 차가 이렇게 흔들리는데 직접 붕대 감지 마세요...",
  ui_story_5080_50800401_29_dialog_content = "도착하면 제가 감아 드릴게요.",
  ui_story_5080_50800401_30_dialog_content = "괜찮아. 이미 혼자가 익숙하니까.",
  ui_story_5080_50800401_31_dialog_content = "이런 환경도 별거 아니야... 그리고 존댓말 안 해도 돼. 나이 차이도 한 살밖에 안 나니까.",
  ui_story_5080_50800401_32_dialog_content = "그런데도 넌 이미 한 사람 몫을 하는 소대장이 됐잖아.\n난 딱히 너한테 존경을 받을 만한 사람이 아냐.",
  ui_story_5080_50800401_33_dialog_content = "넌 일루미나의 정찰병이지? 옷을 보니까 그중에서도 정예 병사인 모양이네.",
  ui_story_5080_50800401_34_dialog_content = "난 알 수 있어. 넌 다른 아기새들과 달라. 영락없는 맹금류지.",
  ui_story_5080_50800401_35_dialog_content = "과연 어떤 임무 때문에 널 여기 보낸 걸까?",
  ui_story_5080_50800401_36_dialog_content = "일루미나의 기밀이야. 당신과는 관계없어.",
  ui_story_5080_50800401_37_dialog_content = "그거야 모르지. 운명은 덧없기 마련이거든.",
  ui_story_5080_50800401_38_dialog_content = "근데 너 같은 맹금류를 여기 보낸 걸 보면, 분명히 더 깊은 뜻이 있을 것 같네.",
  ui_story_5080_50800401_39_dialog_content = "꼬맹이, 이거 봐. 바로 이런 <color=#FFB400>흔적</color>이야.",
  ui_story_5080_50800401_40_dialog_content = "카프카 말대로야. 전에 예리아가 말했던 <color=#FFB400>흔적</color>이 바로 이거라고.",
  ui_story_5080_50800401_41_dialog_content = "내가 그렇게 부르지 말라고 했지... 근데, 이거 그냥 용암 아냐?",
  ui_story_5080_50800401_42_dialog_content = "멀쩡한 곳에 갑자기 웬 용암이 생긴 거지?",
  ui_story_5080_50800401_43_dialog_content = "앞으로 더 가보자. 다른 걸 발견할 수 있을지도 모르니까.",
  ui_story_5080_50800401_44_dialog_content = "어이, 로이! 이것들 암귀 맞지? 너덜너덜하지만 딱 봐도 암귀 시체잖아?",
  ui_story_5080_50800401_45_dialog_content = "누군가 처치했어... 이상하네. 소멸이 이렇게 오래 걸리는 암귀는 나도 처음이라고.",
  ui_story_5080_50800401_46_dialog_content = "로이, 잘 봐. 이거 「그때」 봤던 <color=#FFB400>그 암귀</color>랑 같은 종 아냐?",
  ui_story_5080_50800401_47_dialog_content = "15년 전, 우리가 도망칠 때... <color=#FFB400>대장</color>은 우릴 엄호하다 <color=#FFB400>그 암귀</color>한테...",
  ui_story_5080_50800401_48_dialog_content = "...놈들을 구분할 수 있는 건 너뿐이야.",
  ui_story_5080_50800401_49_dialog_content = "닮았어. 하지만 그때 <color=#FFB400>그놈</color>하곤 역시 달라. 아무래도 <color=#FFB400>놈의 후손</color>인 모양이야.",
  ui_story_5080_50800401_50_dialog_content = "이 망할 자식, 10년 동안 새끼까지 잔뜩 쳤단 말이야?",
  ui_story_5080_50800401_51_dialog_content = "계속 추적해! 흔적을 뒤따라가서, <color=#FFB400>그놈</color> 소굴을 박살 내 버리자고!",
  ui_story_5080_50800401_52_dialog_content = "이미 화산 근처까지 왔잖아. 주변 공기가 엄청 뜨거워졌어.\n아무래도 예리아 말대로 정말 녀석이 깨어난 모양이야.",
  ui_story_5080_50800401_53_dialog_content = "왜 흔적이 여기서 끊긴 거지?",
  ui_story_5080_50800401_54_dialog_content = "이건 다른 암귀의 발자국이야... 놈들이 흔적을 엉망으로 만들었을 수도 있어.",
  ui_story_5080_50800401_55_dialog_content = "분노의 화산은 땅속 깊은 곳에 위치한 화산이니까, 이 밑에 길이 여러 개 숨겨져 있을지도 모르지.",
  ui_story_5080_50800401_56_dialog_content = "확실한 목표 없이 무작정 지하를 탐사하는 건 위험해.",
  ui_story_5080_50800401_57_dialog_content = "쳇, 숨지 말고 나와라! 다 덤벼 보라고!",
  ui_story_5080_50800401_58_dialog_content = "난 이제 열 몇 살짜리 꼬맹이가 아니야! 나와서 끝장을 보잔 말이다!",
  ui_story_5080_50800401_59_dialog_content = "빌어먹을!",
  ui_story_5080_50800401_60_dialog_content = "벽 그만 쳐. 여긴 구조가 약하다고── 으아아악──",
  ui_story_5080_50800401_61_dialog_content = "<color=#e8d9bb>주먹질에 벽이 흔들리고 동굴 깊은 곳에서 메아리가 울려 퍼졌다.\n그러자 어둠 속에서 수많은 암귀가 움직이는 소리가 들려왔다.</color>",
  ui_story_5080_50800401_62_dialog_content = "여긴 곧 무너지겠어! 근데 아무래도 주인이 드디어 손님을 맞이하러 온 모양이야.",
  ui_story_5080_50800401_63_dialog_content = "저기 봐, 로이! 저 녀석들 맞지?",
  ui_story_5080_50800401_64_dialog_content = "드디어 못 참고 나온 건가? 놈들 소굴이 이 근처에 있나 보군.",
  ui_story_5080_50800401_65_dialog_content = "꼬맹이, 조심해... 그리고 속전속결로 끝내야 해.",
  ui_story_5080_50800401_66_dialog_content = "흥, 내 렌치가 그렇게 만만한 줄 알아? 가자, 로이!",
  ui_story_5080_50800402_1_dialog_content = "들어와. 편하게 있어. 어차피 아무도 없을 테니까...",
  ui_story_5080_50800402_2_dialog_content = "짠! 용사 제타의 무적 그림 기술!",
  ui_story_5080_50800402_3_dialog_content = "우와! 살아 있는 거 같아!",
  ui_story_5080_50800402_4_dialog_content = "이건 용사 제타의 기술 중에서도 시시한 편이라구!",
  ui_story_5080_50800402_5_dialog_content = "너희 또 몰래 내 집에 들어와서 멋대로 낙서했니?",
  ui_story_5080_50800402_6_dialog_content = "「페어리 장로」의 집은 너무 진부해! 이건 구세주의 친필이니까 기쁘게 받아!",
  ui_story_5080_50800402_7_dialog_content = "...됐어. 물건만 안 망가뜨리면 됐지 뭐.",
  ui_story_5080_50800402_8_dialog_content = "그리고 난 「페어리 장로」가 아냐. 나보다는 나로세르가 그 호칭에 더 잘 어울릴걸.",
  ui_story_5080_50800402_9_dialog_content = "만난 적은 없지만 되게 멋진 이름이네! 아, 맞다! 편지들은 우리가 잘 넣어 뒀어.",
  ui_story_5080_50800402_10_dialog_content = "엉망진창으로 널려 있던 우편물도 정리했고, 쓰레기도 내다 버렸어.",
  ui_story_5080_50800402_11_dialog_content = "그래? 대단한걸.",
  ui_story_5080_50800402_12_dialog_content = "헤헤, 지금까지 쭉 「페어리 장로」한테서 임무 보상을 받아 왔잖아.\n용사 제타는 보상을 받고 입을 쓱 닦는 사람이 아니라구!",
  ui_story_5080_50800402_13_dialog_content = "알겠으니까 편지에 물감 묻히지 마.\n다들 거기 서 있지 말고 들어와서 앉아.",
  ui_story_5080_50800402_14_dialog_content = "진짜 많이 변하셨네요, 예리아 씨... 다른 사람들이랑 더 잘 어울리고, 무척 즐거워 보여요.",
  ui_story_5080_50800402_15_dialog_content = "정말 잘됐어요.",
  ui_story_5080_50800402_16_dialog_content = "그러니? 뭐, 이 꼬마애들 덕분에 확실히 전처럼 지루하진 않게 됐어.",
  ui_story_5080_50800402_17_dialog_content = "이건 정찰과 타격 기능을 모두 갖춘 생체공학 드론, 호크헌터 3호야.\n일루미나 첨단 과학의 집약체인데... 너희가 정말 수리할 수 있겠어?",
  ui_story_5080_50800402_18_dialog_content = "웨폰마스터, 그럼 너한테 맡길게!",
  ui_story_5080_50800402_19_dialog_content = "핑거 트래킹 테스트 시작. 왼쪽, 오른쪽, 왼쪽... 「트랜스밋 모듈」이 망가졌네.\n충격 때문인 거 같아.",
  ui_story_5080_50800402_20_dialog_content = "훗, 전부 우리의 자랑스러운 웨폰마스터만 믿으면 된다구. 못 하는 게 없거든!",
  ui_story_5080_50800402_21_dialog_content = "웨폰마스터, 도와줄 거지?",
  ui_story_5080_50800402_22_dialog_content = "최선을 다해 볼게.",
  ui_story_5080_50800402_23_dialog_content = "공구 줘. 나도 같이 고칠 수 있으니까.",
  ui_story_5080_50800402_24_dialog_content = "이 녀석들은 내 전우야... 함부로 다른 사람 손에만 맡길 순 없어.",
  ui_story_5080_50800402_25_dialog_content = "서두를 거 없어. 「중립 영웅: 호크 슈터」!",
  ui_story_5080_50800402_26_dialog_content = "......",
  ui_story_5080_50800402_27_dialog_content = "제타는 원래 저래. 너무 신경 쓰지 마.",
  ui_story_5080_50800402_28_dialog_content = "고독한 매는 네 부하니까, 용사 제타가 네 동료한테 손을 대는 일은 이제 없을 거야.",
  ui_story_5080_50800402_29_dialog_content = "고독한 매를 다치게 만든 것도 내 책임이니까, 용사 제타가 상처를 치료해 줄게!",
  ui_story_5080_50800402_30_dialog_content = "너 근데 정작 일은 전부 타이니한테 맡겼잖아...",
  ui_story_5080_50800402_31_dialog_content = "아이테르여! 운명 같은 재회가 네게 이토록 강력한 동료를 안겨 주었을 줄이야!",
  ui_story_5080_50800402_32_dialog_content = "알아듣게 좀 말해...",
  ui_story_5080_50800402_33_dialog_content = "그치만 용사 제타는 절대 포기하지 않아!",
  ui_story_5080_50800402_34_dialog_content = "넌 중립 영웅이라 아이테르랑 한 파티가 될 수 있었으니까,\n그럼 용사 제타랑도 같이 다닐 수 있을 거잖아!",
  ui_story_5080_50800402_35_dialog_content = "네가 실수로 마도에 빠져들 뻔했더라도 괜찮아.\n너처럼 강한 부하라면 난 신경 안 쓰고 받아줄 수 있으니까!",
  ui_story_5080_50800402_36_dialog_content = "난...",
  ui_story_5080_50800402_37_dialog_content = "말 안 해도 용사 제타는 다 알아!",
  ui_story_5080_50800402_38_dialog_content = "너처럼 자존심이 대단한 사람은 분명히 납득할 수 없겠지?",
  ui_story_5080_50800402_39_dialog_content = "괜찮아. 용사 제타는 너랑 공평하게 경쟁할 거거든.\n그러니까 웨폰마스터한테 고독한 매를 치료해 주라고 한 거야.",
  ui_story_5080_50800402_40_dialog_content = "네가 철저히 패배를 인정하게 만들어 줄게...\n후후후, 「호크 슈터」처럼 강력한 부하가 생긴다면 그 「마녀」도 더는 내 상대가 안 되겠지.",
  ui_story_5080_50800402_41_dialog_content = "말투는 오히려 네가 더 악당 같은데?",
  ui_story_5080_50800402_42_dialog_content = "대장, 제타가 하는 말에 굳이 어울려 줄 필요 없어.\n제타는 그냥... 말투가 좀 재미있는 스타일일 뿐이야.",
  ui_story_5080_50800402_43_dialog_content = "마, 맞아, 대장. 둘이 호크헌터 3호를 다 고치고 나면 바로 가자.",
  ui_story_5080_50800402_44_dialog_content = "괜찮아.",
  ui_story_5080_50800402_45_dialog_content = "자, 들었지? 제타, 얼른 레이첼한테 사과... 어?",
  ui_story_5080_50800402_46_dialog_content = "비록 넌 레디젤 사막의 도적이지만... 저기...",
  ui_story_5080_50800402_47_dialog_content = "모르고 그랬던 거니까, 이번엔 됐어.",
  ui_story_5080_50800402_48_dialog_content = "넌 아직 어려. 저 사람들처럼 사막의 악당이 되진 마.",
  ui_story_5080_50800402_49_dialog_content = "후후후, 넌 아무것도 모르는구나! 제타의 꿈은 전설의 영웅이자, 사막의 구세주가 되는 거라구!",
  ui_story_5080_50800402_50_dialog_content = "그럼 다행이고. 내가 너흴 기습했을 때 다치진 않았어?",
  ui_story_5080_50800402_51_dialog_content = "어? 응! 안 다쳤어! 용사 제타가 그 정도 일로 다칠 리가 없잖아?\n그리고 무섭지도 않았어! 절대 놀라서 운 거 아냐!",
  ui_story_5080_50800402_52_dialog_content = "잘했어. 넌 참 용감하구나.",
  ui_story_5080_50800402_53_dialog_content = "...잘못 본 거 아니지?",
  ui_story_5080_50800402_54_dialog_content = "레이첼이 제타를 고분고분하게 길들였어...",
  ui_story_5080_50800402_55_dialog_content = "대장한테... 저런 면도 있었구나.",
  ui_story_5080_50800402_56_dialog_content = "어쩌면 카렌 말대로 레이첼은 성숙한 대장이라서, 사실 남을 잘 돌볼 수 있는 건지도 모르겠네.",
  ui_story_5080_50800402_57_dialog_content = "그치만...",
  ui_story_5080_50800402_58_dialog_content = "(저게 레이첼의 진짜 모습인 건가? 그럼 왜 우리한테는 차갑게 구는 거지?)",
  ui_story_5080_50800402_59_dialog_content = "(임무 때문에 감정을 숨기는 걸까? 아니면... 더 복잡한 사정이 있다거나...)",
  ui_story_5080_50800402_60_dialog_content = "재미있네. 사막엔 언제나 이런저런 새들이 날아다니지만, 자기 발톱을 거두는 맹금류는 처음 봤어.",
  ui_story_5080_50800402_61_dialog_content = "제타, 이 드론의 외부 장갑 사이에 모래가 들어가서 몇몇 회로가 타버렸어.",
  ui_story_5080_50800402_62_dialog_content = "이건 고치려면 좀 골치 아플 것 같은데. 난 이런 정밀한 작업엔 좀 약해.",
  ui_story_5080_50800402_63_dialog_content = "뭐, 뭐라고?",
  ui_story_5080_50800402_64_dialog_content = "못 하겠으면 공구 줘. 내가 알아서 고칠 수 있으니까.",
  ui_story_5080_50800402_65_dialog_content = "아니, 아니야, 잠깐! 잠깐만 기다려!",
  ui_story_5080_50800402_66_dialog_content = "용사 제타가 다 책임지겠다고 했잖아. 고수의 대결다운 모습을 보이라구!",
  ui_story_5080_50800402_67_dialog_content = "이제 막 불이 붙었는데, 갑자기 픽 꺼지면 어떡해... 웨폰마스터, 정말 포기할 거야?",
  ui_story_5080_50800402_68_dialog_content = "「기계 해커」 오디를 떠올려 봐! 오디는 정밀 작업을 잘하잖아! 이대로 오디한테 질 셈이야?",
  ui_story_5080_50800402_69_dialog_content = "...너 지금... 뭐라고 했냐?",
  ui_story_5080_50800402_70_dialog_content = "...잘 보고 있어. 이 정도 일은 아무것도 아니니까!",
  ui_story_5080_50800402_71_dialog_content = "오디는 무슨, 나한텐 상대도 안 된다구! 내가 지금 바로 고칠 테니까!",
  ui_story_5080_50800402_72_dialog_content = "왜 타이니가 맨날 제타한테 잡혀 있던 건지 좀 알 것 같네.",
  ui_story_5080_50800402_73_dialog_content = "상황을 보니까 금방 해결될 문제는 아닌 것 같은데. 해도 졌으니까 다들 여기서 묵고 가.",
  ui_story_5080_50800402_74_dialog_content = "그럼 예리아 씨한테 너무 민폐 아닌가요?",
  ui_story_5080_50800402_75_dialog_content = "민폐도 슬슬 익숙하거든.",
  ui_story_5080_50800402_76_dialog_content = "그리고... 맹금류 아가씨, 왠지 우린 나눌 얘기가 꽤 많을 것 같은걸.",
  ui_story_5080_50800500_1_dialog_content = "<color=#e8d9bb>밤이 깊어지며 사막의 기온도 점차 차가워졌다.\n그리고 사람 하나 없어 보이는 모래언덕 아래에서는 암류가 흐르는 소리가 들려왔다.</color>",
  ui_story_5080_50800500_2_dialog_content = "<color=#e8d9bb>검은 그림자가 꿈틀대다가 땅에서 솟구쳐 올랐다.</color>",
  ui_story_5080_50800500_3_dialog_content = "으아아아──! 퉷!",
  ui_story_5080_50800500_4_dialog_content = "퉤퉤퉤퉤퉤퉤!",
  ui_story_5080_50800500_5_dialog_content = "퉤, 콜록콜록... 퉤엣! 로, 로이, 괜찮아?",
  ui_story_5080_50800500_6_dialog_content = "꼬맹아... 다음부턴 동굴을 무너트리기 전에 먼저 말부터 해. 난 늙어서 이런 고생은 못 버틴다고.",
  ui_story_5080_50800500_7_dialog_content = "하하, 뭐 그래도 이렇게 통쾌한 것도 정말 오랜만이었잖아.",
  ui_story_5080_50800500_8_dialog_content = "그건 맞긴 한데, 동굴이 무너진 마당에 이제 어디 가서 놈들 소굴을 찾냔 말이야...\n게다가 그 정도 수라니, 제대로 골치 아프겠어.",
  ui_story_5080_50800500_9_dialog_content = "됐어. 돌아가면 다른 소린 하지 말고, 우리가 그 암귀 소굴을 쓸어버렸다고만 해.",
  ui_story_5080_50800500_10_dialog_content = "괜찮겠어? 우리가 없앤 암귀가 전부는 아닌 게 확실하잖아.",
  ui_story_5080_50800500_11_dialog_content = "아래쪽 통로가 미로처럼 연결돼 있었어. 놈들을 봐서는 진짜 본거지는 화산 안에 있을지도 몰라...",
  ui_story_5080_50800500_12_dialog_content = "그럼 우리가 화산에 들어가서 쓸어버리면 그만이지!",
  ui_story_5080_50800500_13_dialog_content = "그걸로 될까?",
  ui_story_5080_50800500_14_dialog_content = "거긴 전임 대장도 못 당해낸 그런 암귀가 있을 가능성이 높아.\n우리가 본 놈들보다 훨씬 크고 강하겠지.",
  ui_story_5080_50800500_15_dialog_content = "얼른 모두한테 연락해서 힘을 모아 맞서야 한다고.",
  ui_story_5080_50800500_16_dialog_content = "위험이 닥치면 당연히 말해야지.\n하지만 <color=#FFB400>그 암귀놈</color>이 얽힌 일이라면 절대 꼬맹이들을 끌어들이지 않겠어.",
  ui_story_5080_50800500_17_dialog_content = "그때랑 지금이 뭐가 달라? 너도 그땐 저 꼬맹이들 나이였어.\n그런데 지금은 멀쩡하게 대장이 됐잖아.",
  ui_story_5080_50800500_18_dialog_content = "그게 어떤 느낌인지 아니까 말할 수 없다는 거야!\n우리가 <color=#FFB400>그놈</color>한테 품은 원한은 캠프의 꼬맹이랑은 전혀 상관없잖아!",
  ui_story_5080_50800500_19_dialog_content = "지금 렌치를 쥐고 있는 건 나야. 대장 자리를 이어받은 건 나라고.\n내가 전임 대장의 복수를 해서 형제들의 한을 풀어 주겠어. 그러니까...",
  ui_story_5080_50800500_20_dialog_content = "일단 아무 말도 하지 마, 로이.",
  ui_story_5080_50800500_21_dialog_content = "「내가 모든 걸 해결하겠다」 이거냐...? 전임 대장도 너랑 똑같이 그런 말을 했었지.",
  ui_story_5080_50800500_22_dialog_content = "그리고 결국 우린 살아남았지만, 우리 마음속엔 끝없는 후회가 남고 말았어.",
  ui_story_5080_50800500_23_dialog_content = "만약 저 꼬맹이들도 <color=#FFB400>그놈</color>을 만나 그때의 우리처럼 무력감을 느낀다면,\n결국 똑같아지는 거 아니냐고...",
  ui_story_5080_50800500_24_dialog_content = "다르지, 꼬맹아. 그동안 그렇게 많은 일을 겪고도 애들이 성장한 걸 봐줄 줄 모르는 거냐?",
  ui_story_5080_50800500_25_dialog_content = "비록 그때 일을 안 겪었거나, 기억하지 못하는 애들도 있지만, 다들 이젠 훌륭한 우리 식구잖아.",
  ui_story_5080_50800500_26_dialog_content = "제타의 부모가 세상을 떠났을 때, 저 애는 고작 두 살이었어.\n전엔 키가 타이어 정도밖에 안 되던 애가, 지금은 혼자서도 이 사막을 질주한다고.",
  ui_story_5080_50800500_27_dialog_content = "넌 저 애가 과거와 마주할 기회를 빼앗을 셈이야?",
  ui_story_5080_50800500_28_dialog_content = "그런 뜻이 아니잖아. 내 말 이해할 거 아냐, 로이.",
  ui_story_5080_50800500_29_dialog_content = "알아, 넌 아직 애들 손을 놓아주는 게 어색한 거야.\n그러니까 네가 너무 독선적이란 거라고, 꼬맹아.",
  ui_story_5080_50800500_30_dialog_content = "전임 대장이 자주 하던 말 기억해?\n그 사람은 아이들의 모든 선택을 존중해 주고, 누구에게나 자유로울 권리가 있다고 믿었어.",
  ui_story_5080_50800500_31_dialog_content = "아이들이 성장했다는 사실을 직시해.\n우리 같은 아저씨들도 이제 슬슬 아이들 손을 적당히 놓아주는 법을 배울 때가 됐어.",
  ui_story_5080_50800500_32_dialog_content = "폭풍이 다가올 때 아이들과 함께 맞서 줄 순 있어.\n하지만 무작정 아이들 앞에서만 막아 줄 순 없는 거야.",
  ui_story_5080_50800500_33_dialog_content = "폭풍이라...",
  ui_story_5080_50800500_34_dialog_content = "오빠! 로이!",
  ui_story_5080_50800500_35_dialog_content = "이브? 뭐야? 네가 왜 여기 있어?",
  ui_story_5080_50800500_36_dialog_content = "둘이 안 오니까 너무 걱정돼서 우리가 찾으러 왔어.",
  ui_story_5080_50800500_37_dialog_content = "돌아가자, 오빠!",
  ui_story_5080_50800500_38_dialog_content = "로이... 폭풍이 다가오던 그때 말이야. 난 이브의 손을 놓고 싶지 않았어...\n사실 이브를 잃게 될까 너무 두려웠거든...",
  ui_story_5080_50800500_39_dialog_content = "하지만 결국엔 오히려 이브가 자기 자신을 구하고, 날 구했어...",
  ui_story_5080_50800500_40_dialog_content = "난 가족의 손을 절대 놓지 않을 거야. 하지만... 어쩌면 네 말이 맞을지도 모르겠어.\n저 애들은 우리 생각보다 훨씬 더 강해.",
  ui_story_5080_50800500_41_dialog_content = "뭐, 그렇다고 해서 이번에 쟤들을 데려가겠단 소리는 아냐.\n집 지키는 일만 맡아 줘도 도움은 될 테니까.",
  ui_story_5080_50800500_42_dialog_content = "아무튼 각자 무슨 일을 맡을지는 돌아가서 천천히 논의해 보자고...\n어이, 그 반응은 뭐야? 손수건은 또 어디서 튀어나왔어?",
  ui_story_5080_50800500_43_dialog_content = "꼬맹아... 이 아저씨는 정말 감동했다... 15년의 시간 동안 넌 점점 더 어른스러워졌구나...",
  ui_story_5080_50800500_44_dialog_content = "뭔 멍청한 소리를 하고 있어? 내가 대장 노릇을 몇 년이나 했는데,\n날 다른 꼬맹이들하고 똑같이 취급하지 말라고!",
  ui_story_5080_50800500_45_dialog_content = "늦었잖아. 대체 어디 갔었던 거야? 아무튼 식사 시간 됐으니까 나 말리지 마. 라비, 기다려!",
  ui_story_5080_50800500_46_dialog_content = "근데 무슨 일 있었어? 둘 다 꼴이 아주 엉망이네.",
  ui_story_5080_50800500_47_dialog_content = "아무 일 없었다. 화산 근처에 가서 조사 좀 하고 온 것뿐이야.",
  ui_story_5080_50800500_48_dialog_content = "흐음... 아주르가 조만간 돌아온다던데. 아저씨, 다음에 나가면 술 좀 사다 줘.",
  ui_story_5080_50800500_49_dialog_content = "자, 식사, 식사하시죠! 이야, 하마터면 큰일 날 뻔했네요. 굶어 죽는 줄 알았다니까요.",
  ui_story_5080_50800500_50_dialog_content = "어? 제타랑 타이니는?",
  ui_story_5080_50800500_51_dialog_content = "몰라. 이 말린 도마뱀 엄청 맛있네...\n혹시 무슨 일 생겨서 둘이 지하 통로로 도망치는 중인 거 아냐?!",
  ui_story_5080_50800500_52_dialog_content = "이 시간까지 안 돌아오다니, 나도 좀 걱정이 되는데 말이지.",
  ui_story_5080_50800500_53_dialog_content = "야, 바바라. 사고는 같이 쳐 놓고, 걔네 둘은 어디 갔어?",
  ui_story_5080_50800500_54_dialog_content = "어... 그때 정신이 없긴 했는데, 아마 예리아 따라갔을걸.",
  ui_story_5080_50800500_55_dialog_content = "「구세주 제타의 새로운 팀원」을 찾겠다나 뭐라나, 설마 그 여자를 찾으러 간 건가?",
  ui_story_5080_50800500_56_dialog_content = "예리아를 따라갔다고? 만약 둘이 그 일루미나 여자를 찾으러 간 거라면 그냥 내버려둬.",
  ui_story_5080_50800500_57_dialog_content = "저기, 우린 그 사람에 대해서 아는 게 아무것도 없잖아. 게다가 화산도 폭발했고.\n그러니까 제타랑 타이니가 밖에서 돌아다니게 두는 건 너무 위험한 거 같은데...",
  ui_story_5080_50800500_58_dialog_content = "우린 밥 빨리 먹으니까, 우리가 찾으러 갈게!",
  ui_story_5080_50800500_59_dialog_content = "난 운전 잘 하니까, 내가 찾으러 가겠어!",
  ui_story_5080_50800500_60_dialog_content = "내 생각엔...",
  ui_story_5080_50800500_61_dialog_content = "네가 밤길에 운전하면 맨날 차를 뒤집어 놓잖아, 괜찮겠어?",
  ui_story_5080_50800500_62_dialog_content = "내가 찾으러 갈게. 난 지금 밥 안 먹어도 되거든!",
  ui_story_5080_50800500_63_dialog_content = "그래도, 역시...",
  ui_story_5080_50800500_64_dialog_content = "내가 갈게! 내 열정적인 노랫소리는 길 잃은 여행자의 등대가 돼 줄 테니까!",
  ui_story_5080_50800500_65_dialog_content = "그건 네가 내는 소음이 너무 시끄러워서 그런 거겠지.",
  ui_story_5080_50800500_66_dialog_content = "뭐가 어째?!",
  ui_story_5080_50800500_67_dialog_content = "다들 적당히 좀 해라!",
  ui_story_5080_50800500_68_dialog_content = "이 멍청이들아, 내가 갈 테니까 다들 얌전히 밥이나 먹고 있어!",
  ui_story_5080_50800500_69_dialog_content = "잘 먹겠습니다~ 어? 음식 다 나왔는데 왜 안 먹어?",
  ui_story_5080_50800500_70_dialog_content = "무례한 질문이란 건 알지만, 이런 것들이... 정말 음식인 거야? ...어라?!",
  ui_story_5080_50800500_71_dialog_content = "우와! 이 벌레 구이, 식감이 전보다 훨씬 바삭한데!",
  ui_story_5080_50800500_72_dialog_content = "뱀 꼬리 숯불구이도 육질이 더 좋아졌어!",
  ui_story_5080_50800500_73_dialog_content = "카렌, 왜 한 입도 안 먹어? 걱정 마. 나도 전에는 너처럼 거부감이 있었는데,\n먹어 보니까 거짓말 아니고 진짜 맛있거든!",
  ui_story_5080_50800500_74_dialog_content = "PlayerName... 호의는 고맙지만 사양할게...\n그런 걸 들고 있을 땐 내게서 조금만 떨어져 줄래?",
  ui_story_5080_50800500_75_dialog_content = "이 맛은...!",
  ui_story_5080_50800500_76_dialog_content = "우리 일루미나의 1등급 통조림보다 훨씬 훌륭하잖아...",
  ui_story_5080_50800500_77_dialog_content = "일루미나의 병사 대우가 그렇게 참혹할 줄은...",
  ui_story_5080_50800500_78_dialog_content = "대장도 레디젤의 요리를 좋아하게 될 줄은 몰랐어.",
  ui_story_5080_50800500_79_dialog_content = "난 입맛이 까다로운 편이 아니거든.",
  ui_story_5080_50800500_80_dialog_content = "배불러! 그럼 난 수리하던 거 계속하러 갈 테니까, 다들 방해하지 마!",
  ui_story_5080_50800500_81_dialog_content = "제타처럼 육즙 팡팡 사막쥐 구이를 좋아하는구나! 진짜 맛있지!",
  ui_story_5080_50800500_82_dialog_content = "후후, 일루미나의 사악한 간부라도 정의의 미식을 이해할 수 있는 거였네!",
  ui_story_5080_50800500_83_dialog_content = "어느 한 쪽이 사악하다고 해야 한다면, 그건 레디젤 렌치야.\n그런 너희가 우리와 비슷한 점이 있다니... 난 인정 못 해.",
  ui_story_5080_50800500_84_dialog_content = "(이럴 때면 또 독설을 한단 말이지...)",
  ui_story_5080_50800500_85_dialog_content = "그럴 리 없는데? 제타는 인정 잘해!\n걱정 마, 언젠가는 구세주 제타가 널 거기서 해방시켜 줄 거니까!",
  ui_story_5080_50800500_86_dialog_content = "언제든지 제타의 차에 타도 좋아. 네 자리는 남겨 둘게!",
  ui_story_5080_50800500_87_dialog_content = "어때? 엄청 멋있었지? 늘 이런 대사를 말하고 싶었다니까!",
  ui_story_5080_50800500_88_dialog_content = "레디젤 렌치는... 일루미나에서 도망친 타락한 병사들이야.",
  ui_story_5080_50800500_89_dialog_content = "자기 출신과 명예를 잊었을 뿐만 아니라, 도적이 돼서 과거의 동포와 시민들에게 총구를 겨누었어.",
  ui_story_5080_50800500_90_dialog_content = "심지어 너 같은... 어린애도 그걸 당연하게 받아들이고 있어.",
  ui_story_5080_50800500_91_dialog_content = "제타는 아이가 아니고, 우리도 네 말처럼 그렇지 않아! 너야말로 뭘 잘못 알고 있는 거라구!",
  ui_story_5080_50800500_92_dialog_content = "너 같은 아이가 레디젤의 도적들 손에서 자라며, 옳고 그름을 판단하지 못하는 것도 우리 일루미나의 책임이야... 우린 꼭 최선을 다해 이 문제를 해결할 거야.",
  ui_story_5080_50800500_93_dialog_content = "그 해결이란 게 <color=#FFB400>집행자</color>들을 보내 탈영병들을 처리하는 거니?",
  ui_story_5080_50800500_94_dialog_content = "네?! 그런 얘긴 저도 들어 본 적 없었는데요...",
  ui_story_5080_50800500_95_dialog_content = "이 사막에 아직 이름이 붙지 않고, 심지어는 <color=#FFB400>레디젤 렌치</color>도 존재하지 않았을 무렵에도,\n여긴 줄곧 일루미나에서 도망쳐 나온 사람들이 있었어.",
  ui_story_5080_50800500_96_dialog_content = "일루미나의 추격을 피하고, 자유를 찾기 위해, 그들은 황량한 사막 깊숙이 들어가는 걸 선택했지.",
  ui_story_5080_50800500_97_dialog_content = "결국 일루미나의 <color=#FFB400>집행자</color>들이 사막까지 쫓아와서 탈영병들을 처형해 버렸지만 말이야.",
  ui_story_5080_50800500_98_dialog_content = "어떻게 그런 일이...",
  ui_story_5080_50800500_99_dialog_content = "왜 사막의 첫 유민들이 무기를 들었을까? 왜 그들은 사람이 없는 땅에서도 서로를 경계해야 했을까? 그건 다 일루미나 덕분이야.",
  ui_story_5080_50800500_100_dialog_content = "...전부 지나간 일이야. 지금의 대원수님은 그런 수단을 지지하지 않으시고,\n이미 새로운 제도를 추진하고 계셔.",
  ui_story_5080_50800500_101_dialog_content = "더는 탈영병을 추적해 처형하는 일도 없어!\n레디젤 도적들이 무기를 내려놓고 일루미나에 돌아올 마음만 있다면, 그 누구도 추궁하지 않아...",
  ui_story_5080_50800500_102_dialog_content = "어둠의 위기 때 사메야마는 사람들을 데리고 자난성을 지원했었어...\n아쉽게도 별로 좋은 보답은 받지 못했지만.",
  ui_story_5080_50800500_103_dialog_content = "분명히 중간에 무슨 오해가 있었을 거야.\n대화로 잘 풀었다면, 양측 모두 만족할 만한 방법을 찾을 수 있었을 거고.",
  ui_story_5080_50800500_104_dialog_content = "가능하다면... 난 당신들을 해치고 싶지 않아.\n그렇지만 외부인인 당신들은 탈영병이 어떤 의미를 지니는지 전혀 몰라.",
  ui_story_5080_50800500_105_dialog_content = "한 사람의 결정은 자신과 관련된 수많은 사람에게 피해를 주고...\n심지어는 가문의 명예도 하루아침에 땅에 떨어트려.",
  ui_story_5080_50800500_106_dialog_content = "(이상해... 아주 강렬한 감정이 느껴져. 레이첼이... 어떤 기억을 되짚고 있어.)",
  ui_story_5080_50800500_107_dialog_content = "그러니? 일루미나에서 태어난 새는 날개가 묶여 선택할 권리조차 없다는 걸까?",
  ui_story_5080_50800500_108_dialog_content = "난 레디젤 렌치에서 태어났지만, 사람들과 썩 잘 어울리진 못했어.\n그렇지만 이 녀석들이 자유로운 바보들이란 건 아주 잘 알아.",
  ui_story_5080_50800500_109_dialog_content = "난 녀석들을 떠나 혼자서 둥지를 짓는 걸 선택할 수 있고, 녀석들도 저마다 선택을 할 수 있어.",
  ui_story_5080_50800500_110_dialog_content = "그런 녀석들이 일루미나로 돌아가서, 너처럼 일루미나의 관리를 받으며 개성을 잃게 되는 건... 상상조차 할 수 없는 일이지.",
  ui_story_5080_50800500_111_dialog_content = "그렇게 말하지 마세요. 전 딱히 뭐가 나쁜지 잘 모르겠는데요!",
  ui_story_5080_50800500_112_dialog_content = "일루미나에 가면 아무것도 못 하는 거야? 자동차 질주는? 할 수 있어?",
  ui_story_5080_50800500_113_dialog_content = "음, 지하성에는 귀중한 시설들이 있어서, 보통은... 안 돼.",
  ui_story_5080_50800500_114_dialog_content = "무서워. 안 갈래.",
  ui_story_5080_50800500_115_dialog_content = "아, 아니야! 일루미나는 그렇게 나쁘지 않아. 우리도 여러 대회를 열고 있거든.\n그리고 운전병이 되겠다고 신청할 수도 있어!",
  ui_story_5080_50800500_116_dialog_content = "일루미나의 강령은 모든 오로리안을 지키는 거야.\n설령 개인의 희생이 다소 필요할 수도 있겠지만, 그건 어쩔 수 없는 일이야.",
  ui_story_5080_50800500_117_dialog_content = "후훗, 맹금류 아가씨처럼 강인한 사람을 길러낸 걸 보면, 일루미나도 꽤 공을 많이 들였겠어.",
  ui_story_5080_50800500_118_dialog_content = "능청 떨지 마. 우리 가문은 대대로 영웅을 배출했어.\n일루미나를 향한 우리의 신념을 당신은 상상조차 못 할 거야.",
  ui_story_5080_50800500_119_dialog_content = "여명의 빛을 위해 희생하는 게 뭐가 어때서?\n살면서 목숨보다도 중요한 건 오직 명예뿐이야!",
  ui_story_5080_50800500_120_dialog_content = "사람들이 모두 목숨을 잃으면? 누가 영웅을 기억해 줄까?",
  ui_story_5080_50800500_121_dialog_content = "맹금류 아가씨는 영웅 가문 출신이구나.\n그런데 당신 할아버지의 할아버지가 어떤 일을 했는지, 뭘 좋아했는지 기억해?",
  ui_story_5080_50800500_122_dialog_content = "당신은 분명히 어렸을 때부터 선조들의 명예에 대해 듣고 자랐겠지...\n그런데 그들 개인의 존재에 대해선 뭘 알고 있어?",
  ui_story_5080_50800500_123_dialog_content = "그건...",
  ui_story_5080_50800500_124_dialog_content = "...어쩌면 세월이 지나면서 영웅의 행적은 흐릿해질 수도 있겠지.\n하지만 영웅의 업적은 후세에 길이 남는 법이야.",
  ui_story_5080_50800500_125_dialog_content = "세상은 아직도 암귀로 가득하지만, 우린 여전히 이 세상에 태어나고, 성장하면서 삶을 계승하고 있어... 그것이 가능했던 배경에는 수많은 영웅들이 바친 목숨이 있어.",
  ui_story_5080_50800500_126_dialog_content = "설령 우리가 자신을 희생한 영웅 모두를 알지는 못하겠지만,\n그들의 공훈은 늘 우리와 함께하고, 아스트라 대륙과 함께 존재하지.",
  ui_story_5080_50800500_127_dialog_content = "나 역시 영웅들의 이야기에 영향을 받았고, 수없이 많은 갈림길을 지나 오늘까지 올 수 있었어...\n그 선택엔 일말의 후회도 없어!",
  ui_story_5080_50800500_128_dialog_content = "영웅의 존재와 그들의 이야기는 사라지지 않아!\n다양한 방식으로 사람들에게 영향을 주면서 영원히 그 의미를 후세에 전하고 있으니까!",
  ui_story_5080_50800500_129_dialog_content = "카렌...",
  ui_story_5080_50800500_130_dialog_content = "백야성의 공주님이 정말 훌륭한 말을 해 줬네.",
  ui_story_5080_50800500_131_dialog_content = "화이트 랜서... 당신 말이 맞아.",
  ui_story_5080_50800500_132_dialog_content = "대장, 벌써 한참 들었잖아. 안 들어갈 거야?",
  ui_story_5080_50800500_133_dialog_content = "쉿! 조용히 해. 조금 더... 들어봐야겠어.",
  ui_story_5080_50800500_134_dialog_content = "그래! 화이트 랜서 말대로야! 내게도 한때... 정의를 위해 목숨을 바친 전우들이 있었어.\n난 그들에게 은혜를 입었고, 그로 인해 자랑스러웠어.",
  ui_story_5080_50800500_135_dialog_content = "그건 모두가 본받을 만한 행동이야.",
  ui_story_5080_50800500_136_dialog_content = "맞아... 그럴 만한 가치가 있었다고... 그게 아니면, 난...",
  ui_story_5080_50800500_137_dialog_content = "...대장? 어디 가는...",
  ui_story_5080_50800500_138_dialog_content = "혼자 있게 해 주자.",
  ui_story_5080_50800500_139_dialog_content = "흥... 제타, 타이니, 돌아가자.",
  ui_story_5080_50800500_140_dialog_content = "...레디젤의 두목? 언제부터...",
  ui_story_5080_50800500_141_dialog_content = "고쳤어! 내가 다 고쳤다니까! 오디한테 똑똑히 말해줄 거야! 네가 못 고쳐 본 것도 난 고쳤다고!",
  ui_story_5080_50800500_142_dialog_content = "<color=#FFB400>광전사</color>, 제타는 아직 여기 더 있고 싶은데... 으음...",
  ui_story_5080_50800500_143_dialog_content = "...너도 이제 다 컸으니까 알아서 해라. 예리아, 우리 애들은 너한테 부탁한다.",
  ui_story_5080_50800500_144_dialog_content = "잠깐! 당신... 그 암귀를 알고 있지? 그렇지?",
  ui_story_5080_50800500_145_dialog_content = "레디젤 렌치는 사막에서 오래 활동했으니까, 당신들은 분명히 놈의 존재를 알고 있을 거야.\n내게 놈의 근거지가 있는 곳을 알려줄 수 있겠어?",
  ui_story_5080_50800500_146_dialog_content = "여기 와서 비경을 찾았던 일루미나 병사는 너뿐만이 아니다.\n셀 수 없이 많이 봤지만, 다시 돌아온 자는 하나도 없었지.",
  ui_story_5080_50800500_147_dialog_content = "그렇다고 네가 저들에 비해 특별할 것도 없고 말이야.\n포기해라, 일루미나의 임무 때문에 목숨을 버리지 말라고.",
  ui_story_5080_50800500_148_dialog_content = "거 참, 대체 몇 년이 지났는데 아직도 사람을 죽으라고 보내고 앉았어?",
  ui_story_5080_50800500_149_dialog_content = "당신은 몰라! 이건 군인의 사명이야! 비경을 탐색해서 얻는 효용은 당신 상상보다 훨씬 커!\n설령 목숨을 잃더라도 그건 명예로운 희생이야!",
  ui_story_5080_50800500_150_dialog_content = "좋아, 넌 희생이란 말을 아주 입에 달고 사는군.\n그럼 대답해 봐라. 넌 「희생」의 진정한 의미를 알고 있나?",
  ui_story_5080_50800500_151_dialog_content = "너한테 있어서 「희생」이란 뭘 뜻하지?",
  ui_story_5080_50800500_152_dialog_content = "희생은 대의를 위해, 여명의 빛을 위해, 목숨도 아까워하지 않는 고귀한 행동이야!",
  ui_story_5080_50800500_153_dialog_content = "그...그리고 죽음을 무릅쓰더라도 임무를 완수하겠다는 각오라고!",
  ui_story_5080_50800500_154_dialog_content = "하하하하하──!",
  ui_story_5080_50800500_155_dialog_content = "...왜 웃는 거지? 무슨 뜻이냐고!",
  ui_story_5080_50800500_156_dialog_content = "역시 너도 그들과 별반 다를 게 없군.\n돌아가, 아가씨. 이 사막은 이미 너무 많은 목숨을 집어삼켰어.",
  ui_story_5080_50800500_157_dialog_content = "가자, 타이니.",
  ui_story_5080_50800500_158_dialog_content = "달라... 전혀 다르다고... 아무것도 모르면서... 내가 어떤 「각오」로 여기까지 왔는데...",
  ui_story_5080_50800500_159_dialog_content = "더는 가문의 명예를 실추시킬 순 없어... 반드시... 그 치욕들을 씻어내고 말 거라고...",
  ui_story_5080_50800601_1_dialog_content = "바이스, 아직 안 잤네?",
  ui_story_5080_50800601_2_dialog_content = "오늘 임무 보고서를 써야 하거든. 괜찮아... 하암... 먼저 자.",
  ui_story_5080_50800601_3_dialog_content = "너 지금 엄청 졸린 거 아니야?",
  ui_story_5080_50800601_4_dialog_content = "겨우 선배랑 같이 임무를... 수행하게 됐는데... 좀처럼 없는 기회라구...",
  ui_story_5080_50800601_5_dialog_content = "금방... 끝나...",
  ui_story_5080_50800601_6_dialog_content = "비켜 봐. 내가 대신 적어줄게.",
  ui_story_5080_50800601_7_dialog_content = "후아아... 그럴 순... 없어...",
  ui_story_5080_50800601_8_dialog_content = "끝에 조금밖에 안 남았잖아. 내가 채울게.",
  ui_story_5080_50800601_9_dialog_content = "훗, 바이스랑 오래 알고 지내서 그런지, PlayerName 너도 그런 일에 많이 익숙해졌구나.",
  ui_story_5080_50800601_10_dialog_content = "바이스한테 많이 배워서 어느새 몸에 익은 모양이야... 괜찮으니까 카렌 너도 일찍 쉬어.",
  ui_story_5080_50800601_11_dialog_content = "왠지 다른 문제도 있어 보이는데... 뭐, 네가 그렇게 말한다면 알겠어. 잘 자.",
  ui_story_5080_50800601_12_dialog_content = "(이제 마지막 부분만 남았어. 얼른 끝내자.)",
  ui_story_5080_50800601_13_dialog_content = "그리고, 그리고... 이 부분도 정말 굉장하다구!",
  ui_story_5080_50800601_14_dialog_content = "(이건... 제타 목소리 아냐? 엄청 신났나 보네. 목소리가 방 안까지 들릴 정도잖아.)",
  ui_story_5080_50800601_15_dialog_content = "구세주 제타랑 사악한 마녀의 레이싱!",
  ui_story_5080_50800601_16_dialog_content = "(누구랑 얘기 중인 거지? ...다 적었으니까 나가서 확인해 보자.)",
  ui_story_5080_50800601_17_dialog_content = "제타의 차가 샤샤샥하고 순식간에 사룡의 발톱을 벗어났고, 그리고 쿵! 콰아아앙!",
  ui_story_5080_50800601_18_dialog_content = "제타 님은 이렇게 간단하게 사룡을 들이받아 쓰러뜨렸고,\n심지어는 마녀조차 날 무척이나 숭배했다구.",
  ui_story_5080_50800601_19_dialog_content = "(허풍이 너무 심하잖아... 어? 옆에는... 보초를 서던 레이첼이잖아?)",
  ui_story_5080_50800601_20_dialog_content = "그리고 또, 넌 아마 모르겠지만, 차가 부릉부릉할 땐 모래 속에서 도마뱀이 잔뜩 나와!",
  ui_story_5080_50800601_21_dialog_content = "근데 그거 진짜 맛있어! 오늘 식사 메뉴로 나왔던 거보다 훨씬 야들야들하다구.",
  ui_story_5080_50800601_22_dialog_content = "우린 다들 맛있는 간식을 잘 만들어. 너도 분명히 마음에 들 거야.",
  ui_story_5080_50800601_23_dialog_content = "...내 전투식량 먹어 볼래?",
  ui_story_5080_50800601_24_dialog_content = "싫어. 보기만 해도 맛없을 거 같단 말이야.",
  ui_story_5080_50800601_25_dialog_content = "아, 참! 제타가 말했었나? 난 랠리에 나갈 때 항상 나 혼자 참가했어!",
  ui_story_5080_50800601_26_dialog_content = "그 사악한 마녀조차 전설의 아이테르를 길잡이로 데려갔는데도 말이야!",
  ui_story_5080_50800601_27_dialog_content = "그치만 제타는 언제나 혼자서 위대한 사막 정복 여행을 떠난다구!",
  ui_story_5080_50800601_28_dialog_content = "정말 대단하네. 겉보기와는 전혀 다르잖아.",
  ui_story_5080_50800601_29_dialog_content = "후후, 이제야 이 용사 제타를 숭배할 마음이 들었어? 어때? 마음이 흔들리지?\n그러니까 얼른 그 사악한 조직을 벗어나서 내 부하가 되라구!",
  ui_story_5080_50800601_30_dialog_content = "넌 처음 왔는데도 사막을 건널 수 있었으니까, 랠리의 길잡이를 맡아도 엄청 잘할 거야.",
  ui_story_5080_50800601_31_dialog_content = "제타의 차에 타면 다음 우승 트로피를 차지하는 영광을 누릴 수 있을 거라구.",
  ui_story_5080_50800601_32_dialog_content = "영광이라... 난 운전보다는 기계 쪽에 더 자신 있는데, 내가 할 수 있을까?",
  ui_story_5080_50800601_33_dialog_content = "입문 과정은 다 제타한테 맡겨. 내가 직접 널 전설적인 드라이버의 파트너로 만들어 줄 테니까!",
  ui_story_5080_50800601_34_dialog_content = "그걸 뭐라고 하더라... 길 잃은 사람을 이끌어 주는 보물, 그...그래, 가이드북!\n어떻게 만드는지 가르쳐 줄게!",
  ui_story_5080_50800601_35_dialog_content = "그거 재미있을 것 같네.",
  ui_story_5080_50800601_36_dialog_content = "(뭐야, 이 상황? 둘이 진짜로 이야기를 나누고 있었어...?)",
  ui_story_5080_50800601_37_dialog_content = "그치? 그렇지? 사막엔 재미있는 일이 엄청 많아! 그럼 내일부터 제타가 직접 가르쳐 줄게!",
  ui_story_5080_50800601_38_dialog_content = "제타 손으로 가르친 너만 있다면, 제타는 반드시... 그 마녀한테 이길 수 있을 거야...",
  ui_story_5080_50800601_39_dialog_content = "이제 잘 시간이야. 금방 잠들 거 같아... 잘 자...",
  ui_story_5080_50800601_40_dialog_content = "<color=#e8d9bb>털썩──</color>",
  ui_story_5080_50800601_41_dialog_content = "...참, 아프지도 않니?",
  ui_story_5080_50800601_42_dialog_content = "잘 자... 좋은 꿈 꿔.",
  ui_story_5080_50800601_43_dialog_content = "(어쩔 땐 자상했다가, 또 어쩔 땐 차갑다가... 대체 어느 게 진짜 레이첼일까?)",
  ui_story_5080_50800601_44_dialog_content = "(아무래도 지금이 레이첼하고 대화를 나눠 볼 좋은 기회인... 어라?\n이건... 또야... 이 강렬한 감정...)",
  ui_story_5080_50800601_45_option_content = "[레이첼을 감응한다]",
  ui_story_5080_50800601_46_dialog_content = "타깃 확보, 임무 완수. 대장, 우리가 성공했어요.",
  ui_story_5080_50800601_47_dialog_content = "잘했어... 유적 안에 아직 암귀가 많으니까, 긴장 풀지 말고 곧바로 떠나자.",
  ui_story_5080_50800601_48_dialog_content = "그린아울, 레드팔콘. 「데이터 코어」는 이미 입수했어. 잠입 경로를 따라 복귀해.",
  ui_story_5080_50800601_49_dialog_content = "이거 엄청 무거운데요? 대장. 역시 제가 메고 갈게요.",
  ui_story_5080_50800601_50_dialog_content = "괜찮아. 넌 주변을 잘 살펴 줘. 이제 곧 입구로 돌아가서 대원들과 합류할 거야.",
  ui_story_5080_50800601_51_dialog_content = "대장, 암귀들이 술렁이는 것 같습니다.",
  ui_story_5080_50800601_52_dialog_content = "놈들의 움직임이 변했어요... 한데 모여서 뭘 하려는 걸까요?",
  ui_story_5080_50800601_53_dialog_content = "...아니, 아무래도 우리 쪽으로 달려들 작정인 것 같아.",
  ui_story_5080_50800601_54_dialog_content = "어서 가자!",
  ui_story_5080_50800601_55_dialog_content = "그린아울, 레드팔콘, 즉시 응답하라! 출구 쪽 상황은?",
  ui_story_5080_50800601_56_dialog_content = "암귀들의 이동 경로가 바뀌었어요. 마치 하나의 목표를 향해 이동는 것 같아요...\n이런, 대장! 놈들이 대장 쪽으로 달려가고 있어요!",
  ui_story_5080_50800601_57_dialog_content = "침착하게 행동해. 원래 계획대로 봉쇄되지 않게 정문을 확보해. 우리가 곧 갈 테니까.",
  ui_story_5080_50800601_58_dialog_content = "화이트구스, 저 암귀들은 신경 쓰지 말고, 어서 가!",
  ui_story_5080_50800601_59_dialog_content = "내가 녀석들을 유인할 테니까, 그레이윙 넌 우선 대장이 떠날 수 있게 엄호해!",
  ui_story_5080_50800601_60_dialog_content = "멍청한 소리하지 마! 가려면 다 같이 가야지! 대장, 어서 「코어」를 버리세요!\n그런 걸 메고 있으면 암귀한테 따라잡힐 겁니다!",
  ui_story_5080_50800601_61_dialog_content = "대체 놈들이 어떻게 우리 위치를 알아낸 거죠? 마치 「코어」를 지키기라도 하는 양...",
  ui_story_5080_50800601_62_dialog_content = "화이트구스, 너도 따라 와. 단독 행동은 용납할 수 없어.",
  ui_story_5080_50800601_63_dialog_content = "하지만, 대장... 이러다간 시간이...",
  ui_story_5080_50800601_64_dialog_content = "<color=#e8d9bb>탕탕탕──</color>",
  ui_story_5080_50800601_65_dialog_content = "대장, 이쪽입니다!",
  ui_story_5080_50800601_66_dialog_content = "그린아울과 레드팔콘이에요!",
  ui_story_5080_50800601_67_dialog_content = "저 바보들이...! 왜 명령을 안 따른 거야?! 너희가 이쪽으로 와 버리면, 정문 통로는 어쩔 셈이지?",
  ui_story_5080_50800601_68_dialog_content = "저희가 안 왔으면 다들 여기서 꼼짝도 못 했을 겁니다.",
  ui_story_5080_50800601_69_dialog_content = "혼을 내든 벌을 주든 나중에 하세요. 일단 대장이랑 다들 데리고 나가는 게 급하니까요!",
  ui_story_5080_50800601_70_dialog_content = "바보들...",
  ui_story_5080_50800601_71_dialog_content = "다들 왜 그렇게 느린가 했습니다. 그렇게 무거운 걸 메고 계셨던 겁니까?",
  ui_story_5080_50800601_72_dialog_content = "이게 바로 「코어」인가요? 대장, 이런 걸 들고 어떻게 가요... 차라리...",
  ui_story_5080_50800601_73_dialog_content = "그럴 순 없어! 임무는 그 무엇보다 중요해! 이 안의 「데이터」는 일루미나를 바꿀 힘이 있어...\n「호크아이 소대」는 절대 제 한 목숨이 아까워서 임무를 포기하지 않아!",
  ui_story_5080_50800601_74_dialog_content = "게다가 임무를 포기한다면, 우린 탈영병으로 전락해...\n너희 가족들까지 이 일에 연루돼 치욕을 겪게 만들 순 없어.",
  ui_story_5080_50800601_75_dialog_content = "정문이 코앞이야! 다들 어서 가! 내가 후방에서 엄호할 테니까, 일루미나로 「코어」를 가져가!",
  ui_story_5080_50800601_76_dialog_content = "동의할 수 없습니다!",
  ui_story_5080_50800601_77_dialog_content = "그레이윙... 명령을 거역할 셈이야?",
  ui_story_5080_50800601_78_dialog_content = "일루미나 임무수첩 제6장 31조에 따르면, 부대장은 모든 대원이 동의한다면\n표결을 통해 소대의 최고 명령을 제시할 수 있습니다.",
  ui_story_5080_50800601_79_dialog_content = "대장님, 저희 중에 대장님보다 뛰어난 정찰병은 없습니다.\n그러니 정문 너머에 도달했다고 해도, 지상으로 돌아갈 수 있을지는 미지수입니다.",
  ui_story_5080_50800601_80_dialog_content = "저 그레이윙은 부대장으로서, 모든 대원이 호크헌터 대장의 지상 철수를\n지원하는 결정에 대한 표결을 제안합니다.",
  ui_story_5080_50800601_81_dialog_content = "전 동의해요!",
  ui_story_5080_50800601_82_dialog_content = "저희 생각도 같습니다.",
  ui_story_5080_50800601_83_dialog_content = "너희들...",
  ui_story_5080_50800601_84_dialog_content = "「임무는 무엇보다도 중요하다」고 했죠... 호크헌터, 이제 당신의 임무는 변경됐습니다.",
  ui_story_5080_50800601_85_dialog_content = "「코어」를 가지고 일루미나로 돌아가세요. 가족들이 기다리고 있지 않습니까?",
  ui_story_5080_50800601_86_dialog_content = "저희도 곧 뒤따라가겠습니다. 걱정 마세요.",
  ui_story_5080_50800601_87_dialog_content = "어서 가세요, 대장!",
  ui_story_5080_50800601_88_dialog_content = "너, 너희들...",
  ui_story_5080_50800601_89_dialog_content = "...기다리고 있어. 지상으로 돌아가면 곧바로 지원을 요청할게.",
  ui_story_5080_50800601_90_dialog_content = "암귀들이 온다. 다들 두렵나?",
  ui_story_5080_50800601_91_dialog_content = "대장이 안전하게 정문을 했어. 이제 두려울 게 뭐 있겠어?",
  ui_story_5080_50800601_92_dialog_content = "정문을 폭파해. 녀석들이 이 선을 넘지 못하게.",
  ui_story_5080_50800601_93_dialog_content = "뭐?! 그레이윙! 그만둬──!",
  ui_story_5080_50800601_94_dialog_content = "대장은 늘 어깨에 무거운 책임을 지고 있었죠... 정말 죄송합니다. 짐을 또 하나 얹게 되겠군요.",
  ui_story_5080_50800601_95_dialog_content = "터트려──!",
  ui_story_5080_50800602_1_dialog_content = "(레이첼이... 혼자가 된 이유가 저런 일들을 겪어서였어? 그래서 우릴 찾아왔고...)",
  ui_story_5080_50800602_2_dialog_content = "(차갑게 굴면서 우리한테 정을 주지 않으려고 했던 것도, 저 일을 겪고 나서...\n다시 대원들을 잃게 될까 두려워서였던 거야?)",
  ui_story_5080_50800602_3_dialog_content = "(또 남의 가슴 아픈 과거를 보고 말았잖아. 정말 이대로 레이첼한테 이 이야기를 꺼내도 되는 걸까...)",
  ui_story_5080_50800602_4_dialog_content = "그레이윙, 화이트구스, 그린아울, 레드팔콘... 동료들... 아직 날 지켜보고 있니?",
  ui_story_5080_50800602_5_dialog_content = "<color=#e8d9bb>탁!</color>",
  ui_story_5080_50800602_6_dialog_content = "누구냐?! 감히...",
  ui_story_5080_50800602_7_dialog_content = "야옹!",
  ui_story_5080_50800602_8_dialog_content = "...고양이?",
  ui_story_5080_50800602_9_dialog_content = "...이리 와, 고양아.",
  ui_story_5080_50800602_10_dialog_content = "말린 생선 먹고 싶니?",
  ui_story_5080_50800602_11_dialog_content = "착하지, 아이 착해... 너, 쿠리어가 키우는 애니?",
  ui_story_5080_50800602_12_dialog_content = "털이 참 부드럽네. 정말 귀여워.",
  ui_story_5080_50800602_13_dialog_content = "군번줄 소리를 듣고 온 거니? 너도 내 동료들과 얘기해 보고 싶어?",
  ui_story_5080_50800602_14_dialog_content = "그 고양이, 로이가 주워 온 거야.\n지금까지 쭉 레디젤 렌치 캠프에서 크면서 버릇이 잘못 들었어.",
  ui_story_5080_50800602_15_dialog_content = "...크흡!",
  ui_story_5080_50800602_16_dialog_content = "냐아앙──!",
  ui_story_5080_50800602_17_dialog_content = "어, 언제부터... 설마 다 봤어?",
  ui_story_5080_50800602_18_dialog_content = "신경 쓰지 마. 난 아스트라 대륙 곳곳을 여행하면서 별별 사람을 다 봤거든.\n그래서 네 취미에 대해서도 별생각 없어.",
  ui_story_5080_50800602_19_dialog_content = "그리고 네가 무정한 사람이 아니란 것쯤은 진작에 알고 있었어.",
  ui_story_5080_50800602_20_dialog_content = "근데 미안하지만 말참견 좀 할게, 맹금류 아가씨.\n항상 그렇게 차갑게 행동하면 동료들이 상처받을 거야.",
  ui_story_5080_50800602_21_dialog_content = "...그건 레디젤 렌치 사람들을 거부하는 당신도 마찬가지일 텐데.",
  ui_story_5080_50800602_22_dialog_content = "거부한다고? 아니, 난 그냥 그 시끌벅적한 녀석들에게서 한 발 떨어져 방황하고 있을 뿐이야.",
  ui_story_5080_50800602_23_dialog_content = "역시 넌 <color=#FFB400>그 사람</color>과 많이 닮았어. 그래서 아주, 아주 익숙한 느낌이 들었지.",
  ui_story_5080_50800602_24_dialog_content = "「그 사람」?",
  ui_story_5080_50800602_25_dialog_content = "레디젤 렌치엔 일루미나의 병사가 많지만, 그중에서도 그 사람만이 가장 특별했어.",
  ui_story_5080_50800602_26_dialog_content = "그 사람도 너처럼 특수 임무를 수행하던 정예 병사였고,\n아주 젊었을 때 소대를 이끌고 사막에 들어왔어.",
  ui_story_5080_50800602_27_dialog_content = "그 사람이... 비경 탐색 임무에서 생환했었다는 말이야?",
  ui_story_5080_50800602_28_dialog_content = "혹시 그 사람이나 그 소대의 이름 기억해? 내가 아는 사람일 수도 있을 것 같아.",
  ui_story_5080_50800602_29_dialog_content = "이름...? 내가 그 사람을 알게 됐을 때 그 사람은 이미 자기 과거와 작별한 뒤였는걸.\n나한테 알려 준 그 이름이 본명이 맞는지도 잘 모르겠네.",
  ui_story_5080_50800602_30_dialog_content = "하지만 그 사람이 이끌었던 소대의 이름은 아직 기억해. 「프리버드」였어.\n내가 자유롭게 여행하는 새를 동경하게 된 것도 그 이름 때문이었거든.",
  ui_story_5080_50800602_31_dialog_content = "「프리버드」?!",
  ui_story_5080_50800602_32_dialog_content = "(레이첼이 계속 찾고 있던 그 소대잖아?)",
  ui_story_5080_50800602_33_dialog_content = "그 사람... 역시 사막으로 도망쳤던 건가. 변절해서 레디젤 렌치의 일원이 됐었다니...",
  ui_story_5080_50800602_34_dialog_content = "그 사람과 내가 닮았다고 했는데, 그건 당신 오해야.\n난 그 사람과 닮은 구석이라곤 전혀 없어. 난 그 치욕스러운 탈영병과 달라!",
  ui_story_5080_50800602_35_dialog_content = "미안하게 됐는데, 맹금류 아가씨. 오해는 내가 아니라 네가 하고 있는 것 같아.",
  ui_story_5080_50800602_36_dialog_content = "내가 아는 그 사람은 탈영병이기는커녕, 마지막 순간까지 모든 사람 앞에서\n가슴을 펴고 당당히 서 있었거든.",
  ui_story_5080_50800602_37_dialog_content = "그 사람의 몸에 흐르는 열정은, 손에 쥔 렌치보다도 붉었어.\n그래서 사메야마에게 전해졌어도, 그 빛을 잃지 않았지.",
  ui_story_5080_50800602_38_dialog_content = "그렇다면... 당신한테 해 줄 이야기가 하나 있어.",
  ui_story_5080_50800602_39_dialog_content = "「프리버드」의 대원이었던 <color=#FFB400>내 고모</color>가 말해 준 이야기야...",
  ui_story_5080_50800602_40_dialog_content = "30여 년 전, 일루미나는 「프리버드」라는 이름의 특수 작전 소대를 만들었어.",
  ui_story_5080_50800602_41_dialog_content = "그 소대는 각지에서 선발된 정예들로 이루어져 있었고, 불가능하다고 여겨지는 임무를 전문적으로 맡아 수행했지.",
  ui_story_5080_50800602_42_dialog_content = "아무리 어려운 임무라도, 프리버드는 임무를 백이면 백 완수해서,\n다들 그 소대에 합류하는 걸 명예로 여겼어.",
  ui_story_5080_50800602_43_dialog_content = "그 소대가 지금도 존재했다면, 너와 아주 잘 맞았겠네.",
  ui_story_5080_50800602_44_dialog_content = "그 소대의 마지막 임무는 아주 중요한 기밀 임무였고,\n우리 고모와 소대원들은 목숨을 걸어야 했지...",
  ui_story_5080_50800602_45_dialog_content = "소대원들은 엄청난 희생을 치렀지만, 정작 소대장은 대원들을 배신하고 멋대로 임무를 중단했어.\n그렇게 모두를 <color=#FFB400>탈영병</color>으로 만들고는, 살아남은 사람들을 데리고 일루미나로 돌아왔어.",
  ui_story_5080_50800602_46_dialog_content = "그러더니 나중에는 일루미나에서 탈주해서, 우리 고모까지 나락에 빠트렸지!",
  ui_story_5080_50800602_47_dialog_content = "그 사람 때문에 고모는 탈영병으로 취급받고, 변절자로 의심받았어.\n명예를 잃었을 뿐만 아니라, 사람들에게 무시당하며 수없이 좌천까지 당했다고!",
  ui_story_5080_50800602_48_dialog_content = "가문에 누를 끼치지 않기 위해, 고모는 집에 돌아올 엄두도 못 냈고,\n우리 아버지와의 사이도 순식간에 멀어졌지...",
  ui_story_5080_50800602_49_dialog_content = "하지만 고모가 그렇게 애를 썼어도, 가문의 명성은 여전히...",
  ui_story_5080_50800602_50_dialog_content = "(레이첼...)",
  ui_story_5080_50800602_51_option_content = "[레이첼의 기억에 감응한다]",
  ui_story_5080_50800602_52_dialog_content = "저기 봐! 탈영병네 애가 오고 있어.",
  ui_story_5080_50800602_53_dialog_content = "쟤 설마 뻔뻔하게 박물관에 가려는 건 아니겠지?\n거긴 영웅을 기념하는 곳이지, 탈영병을 위한 곳이 아니잖아!",
  ui_story_5080_50800602_54_dialog_content = "탈영병이 나온 집안에서 가정 교육을 어떻게 했을지 누가 알겠어?",
  ui_story_5080_50800602_55_dialog_content = "정말로 저희 뒤를 탈영병 집안의 자식에게 맡기실 겁니까?",
  ui_story_5080_50800602_56_dialog_content = "레이첼이라고? 비쩍 마르고 약해 보이는데, 보나마나 의지도 약하겠지...",
  ui_story_5080_50800602_57_dialog_content = "안 돼, 글렀어, 가망이 없어...",
  ui_story_5080_50800602_58_dialog_content = "난 그런 사람이 아냐. 나, 난... 반드시 모두에게 증명해 보일 거야!",
  ui_story_5080_50800602_59_dialog_content = "그래. 우리 레이첼처럼 훌륭한 아가씨가 이 세상에 또 어디 있겠어.\n다른 사람들에게 증명해 보이지 않아도 넌 이미 훌륭한 전사야.",
  ui_story_5080_50800602_60_dialog_content = "고모... 방금 난 그런 뜻으로 한 말이 아냐... 고모를 닮고 싶지 않다는 게 아니라...",
  ui_story_5080_50800602_61_dialog_content = "괜찮아, 레이첼. 난 다른 사람이 뭐라고 하든 신경 쓰지 않아.\n그러니까 너도 다른 사람들 말에 꺾이지 마.",
  ui_story_5080_50800602_62_dialog_content = "조금 전에 보여 준 그 기세로, 다른 사람들에게 넌 고모처럼 못나지 않았다고 당당히 말해 줘.",
  ui_story_5080_50800602_63_dialog_content = "고모... 미안해...",
  ui_story_5080_50800602_64_dialog_content = "레이첼, 똑바로 서서 날 봐. 고모는 널 탓하려는 게 아냐.",
  ui_story_5080_50800602_65_dialog_content = "우리 레이첼이 힘든 일을 많이 겪게 만들어서 고모가 미안해.\n하지만 넌 앞으로도 아주 많은 비난을 받게 될 거야.",
  ui_story_5080_50800602_66_dialog_content = "그래도 쓰러지지 말고, 다른 사람들한테 굴복하지 마.\n그 사람들의 말을 인정하지 말고, 큰 소리로 반박해 줘. 아까처럼.",
  ui_story_5080_50800602_67_dialog_content = "고모는 네가 고모보다 훨씬 대단하다는 거 다 알아.",
  ui_story_5080_50800602_68_dialog_content = "그러니까 너 자신을 믿어, 레이첼! 네가 어떤 선택을 하든, 끝까지 밀고 나가야 해.\n다른 사람들의 쓸데없는 말에 귀 기울일 필요 없어!",
  ui_story_5080_50800602_69_dialog_content = "고모는 분가해서 혼자 살면서, 마치 고모의 친딸처럼 나한테 잘해줬어...\n그러니까 난 고모에게 고통을 안겨 준 그 사람을... 절대 용서 못 해.",
  ui_story_5080_50800602_70_dialog_content = "그래서 난 한계를 넘어서고, 그 속박을 벗어던지기 위해 노력하겠다고 다짐했어...\n난, 비극이 되풀이되는 걸 막을 거야.",
  ui_story_5080_50800602_71_dialog_content = "어차피 그 녀석은 탈영병 집안이잖아. 언젠가는 못 버티고 나가 떨어질걸?",
  ui_story_5080_50800602_72_dialog_content = "아냐, 난 그 친구 대단하다고 생각해. 다들 걔 의지 하나는 인정한다니까.\n너도 괜히 뒤에서 뭐라 그러지 마.",
  ui_story_5080_50800602_73_dialog_content = "히이로, 이번 기수 중에서 마음에 드는 생도가 있나?",
  ui_story_5080_50800602_74_dialog_content = "다들 역부족입니다. 제 훈련을 버거워하더군요.",
  ui_story_5080_50800602_75_dialog_content = "그건 네가 너무 엄격한 거다... 참, <color=#FFB400>그 아이</color>는 어떻지?\n그 아이까지 기량이 부족하진 않을 텐데.",
  ui_story_5080_50800602_76_dialog_content = "<color=#FFB400>그 생도</color>는... 자신에 대한 요구치가 너무 높습니다. 신체 조건이 동기들에 비해 떨어지기 때문에,\n억지로 버티는 건 좋지 않다고 생각합니다.",
  ui_story_5080_50800602_77_dialog_content = "따라서 영구적인 부상을 입기 전에 그 생도를 떨어트리려 했습니다만,\n끈기가 대단해서 아무리 강도를 높여도 낙오되는 일이 없더군요.",
  ui_story_5080_50800602_78_dialog_content = "남보다 뛰어난 신체 조건을 가지고 있진 않지만, 끝까지 절 따라온 건 오직 그 생도뿐이었습니다.",
  ui_story_5080_50800602_79_dialog_content = "교내에서는 그 생도와 관련된 유언비어들이 많이 돌더군요.\n하지만 그렇게 수군대던 이들도 어느새 그 생도를 우러러보게 되었습니다.",
  ui_story_5080_50800602_80_dialog_content = "전 그 생도를 치하해 줘야 할지, 말아야 할지 잘 모르겠습니다.",
  ui_story_5080_50800602_81_dialog_content = "쓰러져도 다시 일어서고, 또 한 번 쓰러져도 그 아이는 꺾이지 않고 다시 일어섰다...\n히이로, 난 그런 자가 바로 영웅이라고 생각한다.",
  ui_story_5080_50800602_82_dialog_content = "그 의지를 인정하고, 보듬어 줘라. 넌 그 아이를 부정할 수 없을 거다.",
  ui_story_5080_50800602_83_dialog_content = "이미 지금도 차마 탈락시키지 못하고 있지 않나.",
  ui_story_5080_50800602_84_dialog_content = "생도 레이첼! 제3군단의 히이로 군단장님께서 귀관의 우수한 성적과 뛰어난 정신력을 인정하셨다.\n이에 귀관의 제3군단 전입을 승인한다!",
  ui_story_5080_50800602_85_dialog_content = "(저게 바로 레이첼이었어... 지금까지 저런 길을 겪으면서...\n사람들이 우러러보는 정예 대장이 됐던 거구나.)",
  ui_story_5080_50800602_86_dialog_content = "그렇구나... 맹금류가 되려고 참 많이 힘들었겠네.",
  ui_story_5080_50800602_87_dialog_content = "후훗, 넌 그냥 그 사람이 정말 「탈영」했다고 믿도록 해.\n어쨌든 그 사람도 내겐 몇 마디 말밖에 안 남기고, 우리의 삶에서 사라져 버렸으니까.",
  ui_story_5080_50800602_88_dialog_content = "그렇게 비겁한 사람이라면, 그때도 아무 탈 없이 도망쳤으면 좋았을 텐데...\n그럼 혹시라도 내게 답을 말해줄 수 있었을 텐데 말이야.",
  ui_story_5080_50800602_89_dialog_content = "답?",
  ui_story_5080_50800602_90_dialog_content = "이 사막은 참 넓지? 아무리 보초를 선다고 해도, 이런 끝없는 밤을 어떻게 지킬 수 있겠어?",
  ui_story_5080_50800602_91_dialog_content = "여긴 너무 광활해, 그래서 허무하기도 해.",
  ui_story_5080_50800602_92_dialog_content = "허무라... 그게 당신이 저들을 받아들이지 못하는 이유야?",
  ui_story_5080_50800602_93_dialog_content = "당신은 여러 곳을 여행했다고 했어. 하지만 결국 정착할 곳은 못 찾았겠지.\n그래서 여기로 돌아온 거고...",
  ui_story_5080_50800602_94_dialog_content = "맞아. 난 어릴 때부터 이상하게 이 사막이 낯설게 느껴졌고,\n저 열정적인 사람들을 이해할 수가 없었어.",
  ui_story_5080_50800602_95_dialog_content = "저들은 매일 떠들썩한 생활을 보내지. 하지만 저들이 정말 삶의 의미를 찾으려고 해 본 적이 있을까?",
  ui_story_5080_50800602_96_dialog_content = "그렇게 왁자지껄하며 인생을 낭비하다가, 어느 날 문득 삶의 의미를 깨닫게 된다면,\n분명히 두렵고 당황스럽겠지.",
  ui_story_5080_50800602_97_dialog_content = "모임엔 결국 끝이 있고, 사람과 사람의 만남엔 헤어짐이 있기 마련이야.\n아무리 떠들썩한 삶이라도, 시간이 지나면 다 허무한 자기성찰만 남을 뿐이야. 무섭지 않아?",
  ui_story_5080_50800602_98_dialog_content = "그래서 당신은 사막 위를 맴돌고 있는 거구나. 여긴 집도 아니고, 여행지도 아닌 거네.",
  ui_story_5080_50800602_99_dialog_content = "당신도 그저 이 사막 위를 나는 고독한 철새일 뿐인 거지.",
  ui_story_5080_50800602_100_dialog_content = "지금 보니까 넌 다른 사람의 마음을 참 잘 이해하는구나.\n네가 좋은 대장이라고 칭찬해 준 사람이 정말 아무도 없었어?",
  ui_story_5080_50800602_101_dialog_content = "(바이스가 깨어 있었으면 좋았을 텐데. 내일 봐서 슬쩍 말해줘야겠어.)",
  ui_story_5080_50800602_102_dialog_content = "그 사람이 살아 있을 때 난 아직 어린애였어.\n그 사람은 내게 많은 지식을 가르쳐 주고, 세상이 얼마나 넓은지 알려 줬어.",
  ui_story_5080_50800602_103_dialog_content = "난 그 사람이 해 준 말을 듣고 자유로운 삶을 갈망하게 됐어.\n내 삶의 의미를 찾고, 드넓은 미래로 날아가고 싶었지.",
  ui_story_5080_50800602_104_dialog_content = "하지만 그 사람은 갑작스럽게 죽어 버렸고, 그땐 그렇게 커다래 보였던 뒷모습마저,\n끝내 우리의 기억 속에서 점점 흐려져 갔어.",
  ui_story_5080_50800602_105_dialog_content = "부모님의 품과 레디젤 렌치를 떠난 내가 그래봤자 뭐 얼마나 대단하겠어?\n이 세상엔 내가 발 디딜 곳도 없는걸.",
  ui_story_5080_50800602_106_dialog_content = "하아, 속도 없는 바보들은 웃으면서 잘만 지내는데, 난 오히려 이 드넓은 허무에 빠져 있다니...\n정말 어쩌면 좋을지 모르겠다니까.",
  ui_story_5080_50800602_107_dialog_content = "왜 나한테 그런 얘기를 하는 거야?",
  ui_story_5080_50800602_108_dialog_content = "네가 아니면 아무에게도 이런 얘긴 털어놓지 못했을걸.",
  ui_story_5080_50800602_109_dialog_content = "그러고 보니까 내가 왜 네게 이런 얘기들을 잔뜩 한 걸까?\n네가 그 사람을 닮아서일까? 아니면 네가... 나하고 닮았기 때문일까?",
  ui_story_5080_50800602_110_dialog_content = "맹금류 아가씨, 혹시... 너도 어쩌다 이 사막에 들어와서 길을 잃고 방황하는 새 아니니?",
  ui_story_5080_50800602_111_dialog_content = "네가 탈영병을 잡으러 온 사람이라면 참 좋을 텐데 말이야.\n갑자기 흔적도 없이 사라진 그 사람을 찾아내서 따끔하게 혼내주면 좋겠거든.",
  ui_story_5080_50800602_112_dialog_content = "그 사람 아니었으면 내가 이렇게 고뇌에 빠질 일도 없었을 거야.\n하긴, 레디젤 렌치가 몰상식한 바보들에서 몰염치한 바보로 변한 것도 다 그 사람 탓이니까...",
  ui_story_5080_50800602_113_dialog_content = "그런데 왜 난 그럴 수가 없는 걸까.",
  ui_story_5080_50800602_114_dialog_content = "쿠리어 장로, 당신...",
  ui_story_5080_50800602_115_dialog_content = "제타는 내가 안아서 데려갈게. 너도 내려가 쉬어.",
  ui_story_5080_50800602_116_dialog_content = "결국엔 모든 게 다 허무해진다면서... 그래도 제타를 안아 주고, 신경 써 주고 있잖아.",
  ui_story_5080_50800602_117_dialog_content = "어쩔 수 없는걸. 저 꼬마들이 그린 낙서의 존재감이 어지간해야 말이지.",
  ui_story_5080_50800602_118_dialog_content = "사막은 밤에 무척 추워. 보초는 내 언령이 대신 서 줄 테니까, 걱정 마.",
  ui_story_5080_50800602_119_dialog_content = "게다가... 네가 계속 여기 있다간 아래에 있는 아이테르가 얼음덩어리가 되고 말걸.",
  ui_story_5080_50800602_120_dialog_content = "(앗! 들켰잖아!)",
  ui_story_5080_50800602_121_dialog_content = "(빨리 자리를 피해야... 으악!)",
  ui_story_5080_50800602_122_dialog_content = "(어째서 이런 데 물통이 있는 거냐고──!)",
  ui_story_5080_50800701_1_dialog_content = "일어나. 임무를 계속해야지.",
  ui_story_5080_50800701_2_dialog_content = "대장... 좋은 아침.",
  ui_story_5080_50800701_3_dialog_content = "...좋은 아침이야. 일단 가서 세수부터 하고 정신 차려!",
  ui_story_5080_50800701_4_dialog_content = "응!",
  ui_story_5080_50800701_5_dialog_content = "오늘도 정찰 임무를 계속할 거야. 다들 일어나! 10분 뒤에 집합해!",
  ui_story_5080_50800701_6_dialog_content = "나도 끼워 줘.",
  ui_story_5080_50800701_7_dialog_content = "너희가 찾는 게 그 특이한 암귀라면, 나도 녀석에 대한 정보를 알고 있거든.",
  ui_story_5080_50800701_8_dialog_content = "어째서? 아직도 호기심이 남은 거야?",
  ui_story_5080_50800701_9_dialog_content = "모든 게 허무로 돌아간다 해도, 이번엔 결말을 보고 싶어졌거든.",
  ui_story_5080_50800701_10_dialog_content = "맹금류 아가씨, 아이테르 군, 안 된단 소리는 안 할거지?",
  ui_story_5080_50800701_11_dialog_content = "게다가 난 「그 사람」이 묻힌 곳을 보고 싶기도 하고.",
  ui_story_5080_50800701_12_dialog_content = "...세수는 다 했어? 그럼 출발 준비!",
  ui_story_5080_50800701_13_dialog_content = "제타는 아직도 자고 있는데?",
  ui_story_5080_50800701_14_dialog_content = "그 아이는 계속 자게 두고, 우린 가자.",
  ui_story_5080_50800701_15_dialog_content = "레디젤의 쿠리어 장로, 이건 내가 조사한 지도야.",
  ui_story_5080_50800701_16_dialog_content = "어제 탐사해 보니까 놈들의 동굴은 이 근처 화산의 지맥과 연결돼 있을 가능성이 높아.",
  ui_story_5080_50800701_17_dialog_content = "내가 지맥에 표시를 해 뒀어. 여기서 오답을 골라내 줄 수 있겠어?",
  ui_story_5080_50800701_18_dialog_content = "노력은 가상하지만, 안타깝게도 이 안엔 정답이 없어.",
  ui_story_5080_50800701_19_dialog_content = "사막 지하엔 깊이 잠든 화산이 하나 더 있거든. 이건 외지인들은 모르는 사실이야.",
  ui_story_5080_50800701_20_dialog_content = "깊이 잠든 화산?",
  ui_story_5080_50800701_21_dialog_content = "훗, 지금은 그렇게 말하면 안 되겠구나. 어제 그 화산이 깨어난 걸 내가 확인했거든.",
  ui_story_5080_50800701_22_dialog_content = "그 암귀들은 지맥을 통해서 사막 곳곳에 출몰하지만, 녀석들의 본거지라면 아마 그곳뿐일 거야.",
  ui_story_5080_50800701_23_dialog_content = "거기 말고 다른 곳은 레디젤 렌치 사람들이 이미 다 다녀봤으니까.",
  ui_story_5080_50800701_24_dialog_content = "대체 그게 무슨 뜻이야?",
  ui_story_5080_50800701_25_dialog_content = "거긴 지하 화산이 있어. 어둠의 위기 때 딱 한 번 분화했었는데,\n갈라진 틈새로 암귀들이 쏟아져 나와서 레디젤 렌치를 습격했었어.",
  ui_story_5080_50800701_26_dialog_content = "레디젤 렌치의 당시 대장도, 그리고 제타의 부모님도 그때 목숨을 잃었지.",
  ui_story_5080_50800701_27_dialog_content = "그 후로 레디젤 렌치 사람들은 사막 곳곳에 집을 짓고 살면서도,\n그 위치는 무의식적으로 피하게 됐어.",
  ui_story_5080_50800701_28_dialog_content = "근데 거기서 암귀가 나온다는 걸 알면, 왜 사람들을 모아서 조사하지 않고 몇 년 동안 방치한 거죠?",
  ui_story_5080_50800701_29_dialog_content = "조사는 했어. 단지 아무것도 발견하지 못했을 뿐이지.",
  ui_story_5080_50800701_30_dialog_content = "그 화산은 분화한 뒤로 몇 년 동안 완전히 잠잠해졌고, 평범한 암귀들이 그 안을 차지했어.",
  ui_story_5080_50800701_31_dialog_content = "레디젤 렌치가 몇 번이나 「청소」했지만 딱히 소용이 없었지.\n그리고 당시의 그런 특이한 암귀는 전혀 찾을 수 없었고.",
  ui_story_5080_50800701_32_dialog_content = "그래서 우린 그 암귀가 하나뿐인 개체고, 당시 전임 대장과 함께 목숨을 잃었을 거라 추정했어.",
  ui_story_5080_50800701_33_dialog_content = "몇 차례의 소탕 끝에 그곳의 보통 암귀들도 점차 수가 줄어들었지.",
  ui_story_5080_50800701_34_dialog_content = "사람은 슬픈 추억을 애써 외면하기 마련이잖아? 그래서 점점 거기 가는 사람들도 없게 됐어.",
  ui_story_5080_50800701_35_dialog_content = "그래도 한때는 집이었던 곳인데... 어떻게 버릴 수가 있어요.",
  ui_story_5080_50800701_36_dialog_content = "PlayerName! 너무 슬퍼하지 마!\n헤븐즈 밸리는 우리가 이미 예쁘게 꾸며놨잖아. 이제 네 동족들만 찾으면 돼.",
  ui_story_5080_50800701_37_dialog_content = "후후, 바이스 양 말이 맞아.\n아이테르 중에도 철새가 돼서 자유를 즐기려던 사람이 있을 수도 있잖아?",
  ui_story_5080_50800701_38_dialog_content = "어쩌면 언젠가는... 철새도 고향 땅의 가지에 발을 내디딜 날이 올지도 몰라.",
  ui_story_5080_50800701_39_dialog_content = "......",
  ui_story_5080_50800701_40_dialog_content = "뭐, 어쨌든 이젠 가끔이라도 거기 가 보는 건 나 하나뿐이야.",
  ui_story_5080_50800701_41_dialog_content = "난 그 지하를 여러 번 탐색해 봤어. 별 성과는 없었지만, 그래도 지름길 정도는 알아.",
  ui_story_5080_50800701_42_dialog_content = "그럼 지도는 당신한테 맡길게. 레디젤의 쿠리어 장로.",
  ui_story_5080_50800701_43_dialog_content = "알겠어. 그럼 출발하자.",
  ui_story_5080_50800701_44_dialog_content = "따, 땅이 흔들려!",
  ui_story_5080_50800701_45_dialog_content = "저기 좀 봐! 화산이 폭발했어!",
  ui_story_5080_50800701_46_dialog_content = "너무 놀랄 거 없어. 서두르자.",
  ui_story_5080_50800701_47_dialog_content = "레디젤 사막의 지맥은 늘 불안정해서 심심하면 화산이 폭발하곤 하는데, 저긴 우리가 찾는 곳이 아냐.",
  ui_story_5080_50800701_48_dialog_content = "그 화산은 이미 오랫동안 잠들어 있었어.\n내가 분화구 근처에 가 봤는데, 활동을 시작한 흔적은 발견하지 못했어.",
  ui_story_5080_50800701_49_dialog_content = "하지만... 지금은 다시 포효하기 시작했어. 그건 안에 있는 암귀들의 소리야.",
  ui_story_5080_50800701_50_dialog_content = "만약 그때 그 암귀가 화산 지맥으로 돌아왔다면, 뭔가 이상이 생긴 게 틀림없어.",
  ui_story_5080_50800701_51_dialog_content = "서둘러!",
  ui_story_5080_50800701_52_dialog_content = "여기야. 여기로 내려가면 지맥 깊은 곳으로 내려갈 수 있는 통로가 있어.\n화산 분화구 쪽 동굴하고도 연결돼 있고.",
  ui_story_5080_50800701_53_dialog_content = "역시... 용암에 불탄 흔적이 잔뜩 있네요.",
  ui_story_5080_50800701_54_dialog_content = "이게 그 암귀가 남긴 흔적인가? 아니면 화산의 용암이 지맥을 타고 흐른 건가?",
  ui_story_5080_50800701_55_dialog_content = "글쎄... 어젠 너무 급하게 조사하느라 안쪽까지는 못 들어갔거든.",
  ui_story_5080_50800701_56_dialog_content = "하지만 확실한 건 이 화산이 지금 깨어나고 있다는 거야.",
  ui_story_5080_50800701_57_dialog_content = "잠깐만요. 우리가 전부 안에 들어가는 건 너무 위험할 것 같아요.",
  ui_story_5080_50800701_58_dialog_content = "카렌, 여기서 차하고 입구 좀 지켜줄 수 있을까?",
  ui_story_5080_50800701_59_dialog_content = "알겠어. 나한테 맡겨.",
  ui_story_5080_50800701_60_dialog_content = "땅이 조금씩 떨리고 있어. 이 아래에 굉장한 힘이 존재하는 모양이야.",
  ui_story_5080_50800701_61_dialog_content = "사화산인 것 같진 않아.",
  ui_story_5080_50800701_62_dialog_content = "땅에 발자국들이 엉망으로 찍혀 있어. 이건... 암귀의 흔적일까?",
  ui_story_5080_50800701_63_dialog_content = "녀석들이 안쪽으로 이동한 흔적이야. 뒤쫓아야 해.",
  ui_story_5080_50800701_64_dialog_content = "잠깐만, 레이첼!",
  ui_story_5080_50800701_65_dialog_content = "이, 이건...!",
  ui_story_5080_50800701_66_dialog_content = "주변의 흔적이 오래되지 않았어. 이 지하 회랑은 갓 만들어진 거야.",
  ui_story_5080_50800701_67_dialog_content = "저기 좀 봐! 분화구가 바로 코앞이야!",
  ui_story_5080_50800701_68_dialog_content = "어째서 갓 만들어진 회랑에 이렇게 커다란 공간이 있는 거지?\n게다가 이렇게 분화구랑 가까운 곳에...",
  ui_story_5080_50800701_69_dialog_content = "아이테르 군, 저 벽 좀 봐.",
  ui_story_5080_50800701_70_dialog_content = "발톱 자국인가요? 엄청 깊고, 커요...",
  ui_story_5080_50800701_71_dialog_content = "틀림없어. 이건 사룡이 남긴 흔적이야.",
  ui_story_5080_50800701_72_dialog_content = "아무래도 여기 녀석의 둥지였거나 사냥터였던 모양이네.",
  ui_story_5080_50800701_73_dialog_content = "어쩐지 아주르 양이 아무리 찾아다녀도 못 찾은 이유가 있었어.",
  ui_story_5080_50800701_74_dialog_content = "녀석은 둥지를 하나만 갖고 있던 게 아니라, 레디젤 사람들이 가기 싫어하는 곳에도\n둥지를 숨겨 뒀던 거예요...",
  ui_story_5080_50800701_75_dialog_content = "예리아 씨... 아주르 씨가 사룡을 찾아다니는 건 어떻게 아셨어요?",
  ui_story_5080_50800701_76_dialog_content = "후후, 말했잖아. 어쨌거나 여기도 내 관할 구역인걸.",
  ui_story_5080_50800701_77_dialog_content = "(거짓말... 사실은 계속 레디젤 사람들을 지켜보고 있었던 거겠죠.)",
  ui_story_5080_50800701_78_dialog_content = "어머, 그러고 보니까 그 사룡이 나타났을 때마다 화산이 폭발했었어.",
  ui_story_5080_50800701_79_dialog_content = "어쩌면 화산 폭발을 피하려고 어쩔 수 없이 둥지에서 나와서\n사람들 앞에 모습을 드러냈던 건 아닐까?",
  ui_story_5080_50800701_80_dialog_content = "용암을 두려워하는 거라면, 굳이 화산 근처에 둥지를 지어야 할 이유가 없어.",
  ui_story_5080_50800701_81_dialog_content = "전혀 말이 안 되잖아.",
  ui_story_5080_50800701_82_dialog_content = "그건 녀석이 누군가를 피해 다녔기 때문이야.",
  ui_story_5080_50800701_83_dialog_content = "그때 그 사람은 사막 곳곳을 다니면서 위협이 될 만한 대상을 없앴어.\n사룡은 그 사람을 피하려고 하는 수 없이 화산에 몸을 숨길 수밖에 없었지.",
  ui_story_5080_50800701_84_dialog_content = "지진이에요! 땅이 또 흔들려요!",
  ui_story_5080_50800701_85_dialog_content = "상황이 심상치 않아. 진원지가 바로 이 아래에 있나 봐! 이러다가... 화산이 곧 폭발하는 거 아냐?",
  ui_story_5080_50800701_86_dialog_content = "대장, 이 정도면 조사 임무를 지속하기 어려울 불가항력적인 상황이야. 우선 여길 떠나자.",
  ui_story_5080_50800701_87_dialog_content = "...너희 먼저 가. 난 여기 남아서 임무를 계속하겠어.",
  ui_story_5080_50800701_88_dialog_content = "하지만 대장... 그건 너무 위험해.",
  ui_story_5080_50800701_89_dialog_content = "임무는 무엇보다도 중요해.",
  ui_story_5080_50800701_90_dialog_content = "사냥꾼은 늘 이렇게 필사적이라니까. 정말 맹금류다운 기질이네.",
  ui_story_5080_50800701_91_dialog_content = "하지만 맹금류 아가씨, 헛된 걸 위해 목숨을 버리겠다니, 정말 이해가 안 돼.\n방황하고 있어서 그런 걸까? 아니면 열정이 과한 걸까?",
  ui_story_5080_50800701_92_dialog_content = "대장, 이런 상황에서까지 무리할 필요는 없어. 다음에 다시 오자!",
  ui_story_5080_50800701_93_dialog_content = "그럴 순 없어. 화산이 폭발하기라도 했다간, 여긴 용암에 파묻힐 거야.\n그리고 용암이 굳고 나면, 모든 게...",
  ui_story_5080_50800701_94_dialog_content = "너흰 어서 가!",
  ui_story_5080_50800701_95_dialog_content = "가려면 다 같이 가야지!",
  ui_story_5080_50800701_96_dialog_content = "해칠링 2호, 너... 왜 또 그런 말을...",
  ui_story_5080_50800701_97_dialog_content = "...「또」?",
  ui_story_5080_50800701_98_dialog_content = "(그때... 레이첼의 소대원이 했던 말이야...)",
  ui_story_5080_50800701_99_dialog_content = "난 안 돼... 도망칠 수 없어...",
  ui_story_5080_50800701_100_dialog_content = "조심해! 암귀가 다가오는 게 느껴져!",
  ui_story_5080_50800701_101_dialog_content = "도망갈지 말지는 나중에 얘기하고, 다들 일단 싸울 준비해!",
  ui_story_5080_50800702_1_dialog_content = "끄, 끝났네...",
  ui_story_5080_50800702_2_dialog_content = "흔들림도 멎었어... 화산이 잠잠해진 건가?",
  ui_story_5080_50800702_3_dialog_content = "암귀들이 왜 이렇게 강해진 거지? 몇 번이나 여길 조사하러 왔었지만,\n이렇게 특이한 녀석들은 처음 봐.",
  ui_story_5080_50800702_4_dialog_content = "이 구조는... 변이한 건가?",
  ui_story_5080_50800702_5_dialog_content = "또 시작됐어!",
  ui_story_5080_50800702_6_dialog_content = "여긴 너무 위험해. 대장, 아니면 일단 아까 왔던 통로로 돌아가는 건 어때?",
  ui_story_5080_50800702_7_dialog_content = "여긴 분화구랑 너무 가까워.",
  ui_story_5080_50800702_8_dialog_content = "음... 해칠링 2호 말대로 다른 길을 찾아야겠어...",
  ui_story_5080_50800702_9_dialog_content = "...이게 뭐지? 이 흔들림은 화산 때문이 아니야.",
  ui_story_5080_50800702_10_dialog_content = "다들 조심해! 통로가 무너지겠어!",
  ui_story_5080_50800702_11_dialog_content = "...레디젤 렌치 사람들은 늘 저렇게 열정적이라니까.",
  ui_story_5080_50800702_12_dialog_content = "야, 예리아! 같이 가서 차 조립하자. 오늘은 분명히 다 끝낼 수 있을걸!",
  ui_story_5080_50800702_13_dialog_content = "맞아. 그리고 우리 이따가 사막 도마뱀도 잡으러 갈 거야.",
  ui_story_5080_50800702_14_dialog_content = "난 됐어.",
  ui_story_5080_50800702_15_dialog_content = "뭐야, 예리아는 또 안 가.",
  ui_story_5080_50800702_16_dialog_content = "그럼 내일 또 올게. 같이 놀자!",
  ui_story_5080_50800702_17_dialog_content = "(거절해도 아무 소용이 없어. 하지만 난 저런 사람들과 어울리지 않아.)",
  ui_story_5080_50800702_18_dialog_content = "또 내가 널 찾게 만들었구나?",
  ui_story_5080_50800702_19_dialog_content = "숨바꼭질하는 거 아냐.",
  ui_story_5080_50800702_20_dialog_content = "그럼 예리아는 날 기다리고 있었던 거구나? 그렇지?",
  ui_story_5080_50800702_21_dialog_content = "얼굴 빨개진 거 다 들켰어.",
  ui_story_5080_50800702_22_dialog_content = "안 빨개졌어.",
  ui_story_5080_50800702_23_dialog_content = "자, 구하느라 꽤 고생했어. 일루미나의 교재야.",
  ui_story_5080_50800702_24_dialog_content = "또 외출했던 거야?",
  ui_story_5080_50800702_25_dialog_content = "응. 움브라톤에 가서 암시장 상인이랑 거래를 좀 했어.",
  ui_story_5080_50800702_26_dialog_content = "그거 아니? 움브라톤 밖엔 정말 멋진 지하 유적이 있는데, 그 안에는 고대 건물이 가득하고,\n재료도 우리가 전혀 모르는 것들이야.",
  ui_story_5080_50800702_27_dialog_content = "지금은 클랜 녀석들이랑 상인들이 잔뜩 모여서 거길 무슨 미궁처럼 개조해 버렸어.",
  ui_story_5080_50800702_28_dialog_content = "사람들은 거기서 값진 물건을 찾으려고 안달이 나 있는데,\n사실 가장 가치 있는 건 그 유적 자체란 걸 다들 모르는 모양이야.",
  ui_story_5080_50800702_29_dialog_content = "유적에 무슨 가치가 있어? 이미 골동품이 돼 버려서 남겨 둬 봤자 아무 쓸모도 없잖아.",
  ui_story_5080_50800702_30_dialog_content = "그걸 말이라고 해? 당연히 가치 있지!",
  ui_story_5080_50800702_31_dialog_content = "유적은 어떤 재료를 써서 지은 걸까? 어떤 상황에서 지어졌을까? 그리고 그걸 지은 건 누구일까?",
  ui_story_5080_50800702_32_dialog_content = "유적 안에는 과학 기술이 있을까? 그 기술들은 우리한테 뭘 가져다줄까?",
  ui_story_5080_50800702_33_dialog_content = "고대 문명은 대체 어떤 모습이었을까? 고대인들은 어떤 세상을 창조했을까?\n그리고 어째서 그 문명이 사라져 버렸을까...",
  ui_story_5080_50800702_34_dialog_content = "이 모든 걸 유적이 우리에게 「가르쳐」 줄 수 있어.",
  ui_story_5080_50800702_35_dialog_content = "그 회랑이 그걸 가르쳐 줄 수 있는 거야?",
  ui_story_5080_50800702_36_dialog_content = "그렇지. 시간만 들인다면 내가 거기서 알아낼 수 있을 거야.",
  ui_story_5080_50800702_37_dialog_content = "꼭... 저번에 나한테 말해 줬을 때랑 똑같네.",
  ui_story_5080_50800702_38_dialog_content = "어느 때?",
  ui_story_5080_50800702_39_dialog_content = "북방 근처에 있는 비경을 정찰하러 갔을 때.",
  ui_story_5080_50800702_40_dialog_content = "아, 내가 연 만드는 법 가르쳐 줬을 때 말하는 거구나.",
  ui_story_5080_50800702_41_dialog_content = "맞아. 그 안에 있는 유적은 우리에게 「비행기」라는 걸 가르쳐 줬고,\n조사를 통해 우리 일루미나도 관련 연구를 시작했어.",
  ui_story_5080_50800702_42_dialog_content = "하지만 내가 너한테 만들어 줄 수 있는 건, 고작 연뿐이었지.",
  ui_story_5080_50800702_43_dialog_content = "회랑 안에는 뭐가 있어?",
  ui_story_5080_50800702_44_dialog_content = "그 안엔 숨어 있는 게 너무 많아. 나도 아직 어떻게 알아봐야 할지 잘 모르겠어.",
  ui_story_5080_50800702_45_dialog_content = "기회가 되면 다시 가서 찾아봐야겠네.",
  ui_story_5080_50800702_46_dialog_content = "어쩌면 너한테도 뭔가 가져다줄 수 있을지도 몰라.",
  ui_story_5080_50800702_47_dialog_content = "...뭐 하나 물어봐도 돼?",
  ui_story_5080_50800702_48_dialog_content = "응? 물어봐.",
  ui_story_5080_50800702_49_dialog_content = "당신은 이 아스트라 대륙에서 안 가 본 곳이 없을 텐데, 왜 아직도 그렇게 열정이 넘쳐?",
  ui_story_5080_50800702_50_dialog_content = "이 세상은 이제 당신한테 하나도 낯설지 않을 거잖아. 그럼 엄청 지루할 거 같은데...",
  ui_story_5080_50800702_51_dialog_content = "예리아, 내가 가져다준 책은 다 봤어?",
  ui_story_5080_50800702_52_dialog_content = "응. 5683권, 하나도 안 빠트리고 다 읽었어.",
  ui_story_5080_50800702_53_dialog_content = "하지만 그 5683권의 책도 아스트라 대륙의 모든 이야기를 담아낼 순 없어.",
  ui_story_5080_50800702_54_dialog_content = "그리고 아스트라 대륙 외에 다른 대륙이 있을지도 모르잖아?\n그곳은 어떤 모습이고, 어떤 사람들이 살고 있을까?",
  ui_story_5080_50800702_55_dialog_content = "그건 나도 지금까지 전혀 몰랐고, 줄곧 궁금해했어.",
  ui_story_5080_50800702_56_dialog_content = "그리고 아스트라 대륙의 대부분 지역을 가 봤지만, 모든 길을 다 기억하진 못해.",
  ui_story_5080_50800702_57_dialog_content = "예리아, 어쩌면 넌 스스로 못 느꼈을지도 모르겠지만, 넌 세상에 대한 호기심이 많은 아이야.",
  ui_story_5080_50800702_58_dialog_content = "넌 서두르느라 그런 풍경들을 흘끗 보고 지나가는 나 같은 「철새」랑 다르게,\n분명히 이 세상을 더 깊이 이해할 수 있을 거야.",
  ui_story_5080_50800702_59_dialog_content = "머리 쓰다듬지 마...",
  ui_story_5080_50800702_60_dialog_content = "좋아. 그럼 이제 네 질문에 대답해 줄게.\n난 풍경은 많이 봤지만, 정작 그 풍경에 남긴 추억은 거의 없어.",
  ui_story_5080_50800702_61_dialog_content = "밤에 드넓은 사막을 바라보다 보면, 내겐 기억에 남는 추억이 너무 적다는 게 느껴져.",
  ui_story_5080_50800702_62_dialog_content = "그거야... 일루미나 사람들이 맨날 임무만 맡겨서 그렇지.",
  ui_story_5080_50800702_63_dialog_content = "그럴 수도 있겠네, 하하하.",
  ui_story_5080_50800702_64_dialog_content = "예리아, 넌 정말 똑똑한 아이야. 아마 묻고 싶은 게 너무 많아서,\n답을 얻지 못하는 너 자신 때문에 방황할 수도 있겠지.",
  ui_story_5080_50800702_65_dialog_content = "하지만 그건 어쩔 수 없는 거야. 왜냐하면 예리아 넌 아직 아이니까.",
  ui_story_5080_50800702_66_dialog_content = "열심히 어른이 되도록 해, 예리아. 미래의 넌 분명히 모든 수수께끼를 꼼꼼히 탐구할 수 있을 거야.",
  ui_story_5080_50800702_67_dialog_content = "나처럼 허겁지겁 사느라, 여행길에 있는 것들을 대충 넘기진 마.",
  ui_story_5080_50800702_68_dialog_content = "넌 분명 「인생」이란 여행길에서 의미를 찾고, 셀 수 없이 많은 추억을 남길 거야.",
  ui_story_5080_50800702_69_dialog_content = "자유롭게, 날개를 활짝 펼치고 살아. 그럼 분명히... 지금 그 고민의 답을 얻을 수 있을 테니까.",
  ui_story_5080_50800702_70_dialog_content = "(이해가 안 돼.)",
  ui_story_5080_50800702_71_dialog_content = "(<color=#FFB400>이 사람</color>과 나는 같은 부류고, 우린 선택할 기회도 없이 자신과 어울리지 않는 환경에서 태어났어.)",
  ui_story_5080_50800702_72_dialog_content = "(난 사막을 떠나, 세상 곳곳에 내 발자국을 남기고 싶어. 하지만 이 사람은 자신을 얽매는 일루미나를 떠났으면서도 이곳에 머물고 있어.)",
  ui_story_5080_50800702_73_dialog_content = "왜... 당신은 왜 여기 남은 거야?",
  ui_story_5080_50800702_74_dialog_content = "예리아, 내가 말해 줬던 <color=#FFB400>그 이야기</color> 아직 기억하니?",
  ui_story_5080_50800702_75_dialog_content = "기억나.",
  ui_story_5080_50800702_76_dialog_content = "마지막엔 혼자 남은 당신이 사막에서 이 <color=#FFB400>렌치</color>를 손에 넣었고, 당신에게 의지하는 사람들도 생겼어.",
  ui_story_5080_50800702_77_dialog_content = "그리고 당신은 그 사람들을 위해 모든 유민을 하나로 모았고, 「레디젤 렌치」는 그래서 탄생했어.",
  ui_story_5080_50800702_78_dialog_content = "당신은 그 사람들에게 아무 책임도 없어. 근데 왜 그 사람들을 위해 남기로 한 거야?",
  ui_story_5080_50800702_79_dialog_content = "난 이 사막에서 태어난 아이인걸. 고향에 오는 게 잘못된 건 아니잖아?\n게다가 난 저 사람들이 자유를 손에 넣게 해 주고 싶었어.",
  ui_story_5080_50800702_80_dialog_content = "자신이 누군지도 모른 채 살아가는 게 암귀랑 무슨 차이가 있겠어?\n난 저 사람들의 영혼에 채워진 족쇄를 풀어서, 그들이 스스로 선택할 수 있게 해 줄 거야.",
  ui_story_5080_50800702_81_dialog_content = "난 이미 인생을 헛되이 보냈어.",
  ui_story_5080_50800702_82_dialog_content = "그래서 난 저 사람들이 자신만의 여정을 깨닫고, 자유로운 인생을 살았으면 좋겠어.",
  ui_story_5080_50800702_83_dialog_content = "(오늘만 사는 것처럼 행동하고, 신나게 소란을 피우는 게 「자유」인 거야?)",
  ui_story_5080_50800702_84_dialog_content = "(난 잘 모르겠어...)",
  ui_story_5080_50800702_85_dialog_content = "난 당신이 해 준 이야기들 덕분에, 세상에 내가 발견해 주길 기다리고 있는 게\n정말 많다는 사실을 깨달았어.",
  ui_story_5080_50800702_86_dialog_content = "그 무렵엔 한동안 이 세계 곳곳을 탐험하는 데 푹 빠져 있었어.",
  ui_story_5080_50800702_87_dialog_content = "오? 그거 정말 대단하네, 예리아.",
  ui_story_5080_50800702_88_dialog_content = "하지만 이 세계는 당신 말처럼 훌륭하진 않았어. 당신은 날 속였어.",
  ui_story_5080_50800702_89_dialog_content = "백야성 귀족들은 오만하고, 일루미나는 여전히 따분해.\n북방 사람들은 자기들만의 동화 속에 갇혀 지내.",
  ui_story_5080_50800702_90_dialog_content = "움브라톤의 속삭이는 회랑은 이스타반의 창고로 변했어.\n이야기로 가득하다던 유적은 이스타반이 신경도 쓰지 않는 상자의 내벽일 뿐이야.",
  ui_story_5080_50800702_91_dialog_content = "모든 게 허무해...",
  ui_story_5080_50800702_92_dialog_content = "그렇게 많은 기적을 만들어 냈던 아이테르 일족도, 결국엔 아무도 말하지 않는 추억으로 변해 버렸어.",
  ui_story_5080_50800702_93_dialog_content = "암귀는 인간을 공격하고, 인간은 암귀에게 반격해.\n이 세상의 생명들은 모두 고통스러운 삶의 나선 속에 갇혀 있어.",
  ui_story_5080_50800702_94_dialog_content = "모든 게 결국 공허로 돌아가는 거야.",
  ui_story_5080_50800702_95_dialog_content = "우리 예리아가 드디어 어른이 됐구나! 하지만 넌 고민이 많아도 너무 많아.",
  ui_story_5080_50800702_96_dialog_content = "잘 모르겠어... 이제 질문을 그만해야 할까?",
  ui_story_5080_50800702_97_dialog_content = "똑똑해서 계속 고독과 허무를 느끼는 거라면, 나도 저 시끄러운 바보들 중의 하나가 돼야 할까?",
  ui_story_5080_50800702_98_dialog_content = "하지만 예리아, 넌 「아이테르」를 만났잖니?",
  ui_story_5080_50800702_99_dialog_content = "너도 알 거야. 그가 나타난 뒤로 헤븐즈 밸리는 더는 잊힌 과거가 아니게 됐어.\n그 추억들을 계승할 사람이 생겼으니까, 새로운 이야기가 시작되겠지.",
  ui_story_5080_50800702_100_dialog_content = "세상의 풍경이 항상 변함없는 건 아니잖아?",
  ui_story_5080_50800702_101_dialog_content = "운명은 무상하지만, 너한테 무료함이나 고통스러운 경험만을 안겨 주는 건 아니야.",
  ui_story_5080_50800702_102_dialog_content = "그 속에 존재하는 관계들은 마치 실처럼 너라는 「연」을 붙잡아 두고 있거든...",
  ui_story_5080_50800702_103_dialog_content = "잠깐만! 어디 가려는 거야? 가지 마!",
  ui_story_5080_50800702_104_dialog_content = "이미 느꼈겠지만, 다들 널 「부르고」 있어.",
  ui_story_5080_50800702_105_dialog_content = "내가 너한테 좋은 선생님은 아니었지만, 예리아... 난 너와 만날 수 있어서 정말 기뻤어.",
  ui_story_5080_50800702_106_dialog_content = "잠깐만! 거기 서! 돌아와! 가지 마... <color=#FFB400>아탈</color>!",
  ui_story_5080_50800702_107_dialog_content = "예리아 씨!",
  ui_story_5080_50800702_108_dialog_content = "......?",
  ui_story_5080_50800702_109_dialog_content = "깨어났군요! 정말 다행이에요.",
  ui_story_5080_50800702_110_dialog_content = "이 녀석이 엄청 걱정했다고. 네 옆에서 한참이나 자기 「특기」를 보여 줬다니까.",
  ui_story_5080_50800702_111_dialog_content = "사메야마...?",
  ui_story_5080_50800702_112_dialog_content = "우리도 있어.",
  ui_story_5080_50800702_113_dialog_content = "...왜 레디젤 렌치 사람들이 다 여기 있는 거야?",
  ui_story_5080_50800702_114_dialog_content = "「페어리 장로」! 드디어 눈을 떴구나! 정말 다행이야. 다친 데는 없어?",
  ui_story_5080_50800702_115_dialog_content = "왜 용사 제타를 두고 간 거야?! 용사 제타는 네 차 소리를 듣자마자 자다가 벌떡 일어났다구!",
  ui_story_5080_50800702_116_dialog_content = "방금 암귀와 교전 중일 때, 제타가 차를 몰고 뒤따라와 줘서 포위에서 벗어날 수 있었어.",
  ui_story_5080_50800702_117_dialog_content = "하지만 마음이 너무 급해서인지 내 말은 전혀 듣지 않아서, 하는 수 없이 여기로 데려왔어...",
  ui_story_5080_50800702_118_dialog_content = "근데 결국엔 동굴이 갑자기 무너져 버렸어. 이거 되게 모험 이야기 주인공 같지 않아?",
  ui_story_5080_50800702_119_dialog_content = "동굴이 붕괴한 것 말인데, 난 처음부터 화산 활동으로 인한 흔들림이 아니라고 생각했어...",
  ui_story_5080_50800702_120_dialog_content = "이게 다 사메야마 때문이야.\n내가 분명히 동굴은 안 튼튼하다고 말까지 했는데 그 괴력으로 렌치를 휘둘러 댔다고.",
  ui_story_5080_50800702_121_dialog_content = "그러게 누가 너더러 따라오라고 했냐?",
  ui_story_5080_50800702_122_dialog_content = "그게 문제라고! 사람을 이렇게 많이 불러 놓고 왜 나만 쏙 뺀 건데? 나 저격하냐?",
  ui_story_5080_50800702_123_dialog_content = "휴, 사메야마 탓할 거 없어. 우린 단지 상황에 맞는 조력자가 필요했을 뿐이니까.",
  ui_story_5080_50800702_124_dialog_content = "어? 그럼 나보다는 요나가 더 낫지 않아?",
  ui_story_5080_50800702_125_dialog_content = "바깥도 위험한 상황이니까, 요나는 남아서 캠프를 지켜야지.",
  ui_story_5080_50800702_126_dialog_content = "걱정 마. 아주르가 돌아오면 요나도 올 거야.",
  ui_story_5080_50800702_127_dialog_content = "도엔이 예리한 감각으로 암귀를 추적할 수 있어.\n그리고 플뢰르 너... 그렇게 겸손할 거 없어. 아저씨는 널 인정하고 있다고.",
  ui_story_5080_50800702_128_dialog_content = "아니지, 내가 똑바로 역할 분배를 했는데, 누가 막 떠벌리고 다닌 거야?!\n왜 이브랑 너까지 따라온 거냐고!",
  ui_story_5080_50800702_129_dialog_content = "미안... 오빠랑 도엔이 안 보이길래, 다른 사람들한테 물어보다 보니까...",
  ui_story_5080_50800702_130_dialog_content = "으아아아! 그 녀석들은 왜 이브 앞에서 입단속 하나 제대로 못 하는 거냐고!",
  ui_story_5080_50800702_131_dialog_content = "나랑 이브를 빼놓고 갈 속셈이었냐? 그건 절대 안 되지!\n그래서 난 내 모든 기술을 동원해서 쫓아왔다고!",
  ui_story_5080_50800702_132_dialog_content = "렉커, 아무래도 넌 이브를 데리고 돌아가는 게 좋겠어. 여긴 너무 위험해.",
  ui_story_5080_50800702_133_dialog_content = "근데 길이 다 무너졌잖아. 지금 다른 길을 찾아 돌아가는 것도 위험해.\n아무래도 둘 다 우리랑 있는 게 낫겠어.",
  ui_story_5080_50800702_134_dialog_content = "다들 됐어! 쳇, 일이 어쩌다 이렇게 된 거냐고...",
  ui_story_5080_50800702_135_dialog_content = "어차피 이렇게 된 거, 이브, 렉커, 너희도 그냥 남아라. 이브, 넌 오빠 뒤에 바짝 붙어 있어!",
  ui_story_5080_50800702_136_dialog_content = "응!",
  ui_story_5080_50800702_137_dialog_content = "우리 모두 힘을 합쳐서, 용감하게 미지에 맞서자!",
  ui_story_5080_50800702_138_dialog_content = "뒤풀이도 준비해 뒀으니까, 누구 하나 빠질 생각 말라고.",
  ui_story_5080_50800702_139_dialog_content = "명심해라, 절대 무리하지 마! 무슨 일이 생기면 바로 내 뒤로 숨어.\nPlayerName, 너희도 마찬가지다.",
  ui_story_5080_50800702_140_dialog_content = "레디젤 렌치... 일이 이렇게 된 이상... 뭐, 됐어.",
  ui_story_5080_50800702_141_dialog_content = "「캔디걸」, 넌 내 뒤만 따라오면 돼. 내가...",
  ui_story_5080_50800702_142_dialog_content = "내가 널 지켜 줄 테니까.",
  ui_story_5080_50800802_1_dialog_content = "기왕 같은 길을 가게 된 거, 이참에 해둘 말이 있다.",
  ui_story_5080_50800802_2_dialog_content = "로이, 이 녀석들한테도 말해줘야겠어. 주변이 점점 더 지하로 가는 걸 보면,\n아무래도 「큰 놈」을 만날 것 같거든.",
  ui_story_5080_50800802_3_dialog_content = "난 괜찮다고 봐. 네가 모르는 부분이 나오면 내가 설명해 줄 테니까.",
  ui_story_5080_50800802_4_dialog_content = "갑자기 분위기가 엄청 진지해졌잖아...",
  ui_story_5080_50800802_5_dialog_content = "15년 전이었지. 그때 아스트라 대륙은 이미 어둠의 위기가 시작된 뒤였고,\n우린 한동안 필사적으로 암귀들과 맞서 싸웠다.",
  ui_story_5080_50800802_6_dialog_content = "하지만 캠프 지하에 화산이 있을 줄은 아무도 몰랐지.\n화산은 어느 날 갑자기 폭발했고, 커다란 균열에서 수많은 암귀가 쏟아져 나왔다.",
  ui_story_5080_50800802_7_dialog_content = "갑작스러운 공격에 우린 손을 쓸 방법이 없었고, 놈들과 싸우면서 철수할 수밖에 없었지.",
  ui_story_5080_50800802_8_dialog_content = "그때 난 고작 열여섯이었고, 전임 대장의 명령대로 몸을 피했다.\n아직 약했던 난 이브와 다른 사람들을 지키면서 도망칠 수밖에 없었다.",
  ui_story_5080_50800802_9_dialog_content = "그때 난 전임 대장 곁에서 같이 후방을 맡았어... 하지만 대장은 끝내 나한테 도망치라고 했고.",
  ui_story_5080_50800802_10_dialog_content = "그리고 대장 일행은 마지막 전투에서 목숨을 잃었어.",
  ui_story_5080_50800802_11_dialog_content = "그 사룡도 그때 거기 있었지. 처음엔 대장도 여유로웠다고. 그런데...",
  ui_story_5080_50800802_12_dialog_content = "화산 폭발이 점점 더 거세지더니, 용암을 뒤집어쓴 암귀가 그 안에서 기어 나왔어.",
  ui_story_5080_50800802_13_dialog_content = "용암을 뒤집어쓴 암귀... 틀림없어. 놈이 바로 우리 타깃이야.",
  ui_story_5080_50800802_14_dialog_content = "대장은 놈이랑 무슨 악연이라도 있는 건지, 놈을 본 대장의 눈에서는 놀라움과... 두려움이 스쳤어.",
  ui_story_5080_50800802_15_dialog_content = "그리고 자긴 놈이 얼마나 강한지 안다면서 우리보고 도망치라고 했었지.",
  ui_story_5080_50800802_16_dialog_content = "너무 진지한 명령이었어. 결국 나도 도망칠 수밖에 없었고,\n마지막 순간, 대장은 노련한 식구들 몇 명과 함께 달려들었지.",
  ui_story_5080_50800802_17_dialog_content = "으음...",
  ui_story_5080_50800802_18_dialog_content = "(강렬한 감정의 파동이 느껴져... 이건... 레이첼의 감정인가?)",
  ui_story_5080_50800802_19_option_content = "(동요하고 있는 거 같은데?)",
  ui_story_5080_50800802_20_dialog_content = "(하긴, 레이첼한테 그 대장이란 사람은 자기 고모의 인생을 망친 탈영병일 테니까.)",
  ui_story_5080_50800802_21_option_content = "(저 얘기를 믿고 싶지 않은 걸까?)",
  ui_story_5080_50800802_22_dialog_content = "(레디젤 렌치의 선대 두목이 타인을 위해 희생하는 고귀한 성품의 소유자라는 얘기를...\n레이첼이 믿게 만드는 건 아무래도 어렵겠지...)",
  ui_story_5080_50800802_23_dialog_content = "(레이첼 눈에는 그저 죽음을 두려워하는 탈영병일 테니까.\n하지만 레디젤 사람들한테는 의심할 여지 없는 영웅이야!)",
  ui_story_5080_50800802_24_dialog_content = "그 뒤의 일은 딱히 설명할 게 없다.",
  ui_story_5080_50800802_25_dialog_content = "다 사메야마 덕이지. 나이는 어려도 식구들을 잘 이끌어 줬어.\n더 중요한 건, 사메야마가 대장 노릇을 할 패기가 있었다는 거야.",
  ui_story_5080_50800802_26_dialog_content = "지휘에 따라 우린 유격전을 시작했고, 그러다 트래블러호를 발견했지.",
  ui_story_5080_50800802_27_dialog_content = "덕분에 사기도 높아졌고, 사막의 유민들도 더 많이 구하게 돼서 머릿수도 오히려 더 늘었고 말이야.",
  ui_story_5080_50800802_28_dialog_content = "대장은 죽었지, 위기는 여전히 그대로지, 다른 사람들은 질질 짜고나 있지.\n그러니 어떻게든 기운을 다잡아야 했다.",
  ui_story_5080_50800802_29_dialog_content = "외지인이었던 나랑 이브는 대장 덕을 많이 봤고, 다른 사람들한테도 도움을 많이 받았으니까.",
  ui_story_5080_50800802_30_dialog_content = "그땐 악역을 맡아서 모진 말을 할 사람이 아무도 없었고, 결국 내가 나섰다!\n대장이 세상을 떠난 마당에, 더는 누구도 죽게 만들 순 없었다고.",
  ui_story_5080_50800802_31_dialog_content = "내가 거칠다고 욕해도 상관없었어. 어차피 식구들이 살아남기만 한다면,\n그걸로 대장을 볼 면목이 설 테니 말이야.",
  ui_story_5080_50800802_32_dialog_content = "그땐 다른 건 별로 생각하지도 않았다고.",
  ui_story_5080_50800802_33_dialog_content = "다 큰 어른이 뭘 부끄러워하고 그래?",
  ui_story_5080_50800802_34_dialog_content = "시끄러워! 별 상관도 없는 얘기잖아!",
  ui_story_5080_50800802_35_dialog_content = "화산이 잠잠해진 뒤로 지상에 있는 암귀들은 우리가 서서히 소탕했어.",
  ui_story_5080_50800802_36_dialog_content = "용암이 식고, 우린 전혀 알아볼 수 없게 변한 캠프에서 저 렌치만 발견할 수 있었지.",
  ui_story_5080_50800802_37_dialog_content = "사룡도, 대장도, 그 암귀도, 흔적조차 찾을 수 없었지.",
  ui_story_5080_50800802_38_dialog_content = "그 누구도 입 밖으로 꺼내진 않았지만, 우린 용암 속에서 대장과 놈들이 함께 죽었다고 생각해 왔다.",
  ui_story_5080_50800802_39_dialog_content = "사룡이 다시 나타나기 전까진 말이야...",
  ui_story_5080_50800802_40_dialog_content = "게다가 그 암귀도 이제 다시 나타났잖아? 전임 대장이 놈들한테 잡아먹힌 건 아니겠지?",
  ui_story_5080_50800802_41_dialog_content = "그럴 리가 있겠냐! 대장이 얼마나 강했는지 알아?!",
  ui_story_5080_50800802_42_dialog_content = "됐어, 어차피 이젠 대장의 복수를 할 수 있게 됐으니까.\n지금까진 전혀 못 찾았는데, 이런 길이 숨어 있었잖아...",
  ui_story_5080_50800802_43_dialog_content = "전에는 이 화산이 때때로 포효하곤 했어.",
  ui_story_5080_50800802_44_dialog_content = "다들 암귀 소리란 건 알고 있었지만, 암귀들을 계속 없애도 계속 들리길래,\n우린 어딘가에 우리가 못 찾은 통로가 있을 거라 생각했지.",
  ui_story_5080_50800802_45_dialog_content = "흥, 드디어 찾아냈잖아. 그래도 다시는 오고 싶지 않았던 곳에 또 오게 될 줄은 몰랐는데 말이야.",
  ui_story_5080_50800802_46_dialog_content = "난... 어렸을 때 그 사람 곁에 있는 걸 좋아했어.",
  ui_story_5080_50800802_47_dialog_content = "그 사람의 힘도 직접 봤고 말이야. 사메야마 당신 못지않은 실력이었어.\n그러니까 그 용한테 졌을 리가 없어.",
  ui_story_5080_50800802_48_dialog_content = "게다가 난 그 사람이 뭔가 참고 있다는 걸 느꼈어.",
  ui_story_5080_50800802_49_dialog_content = "필사적으로 어떤 비밀을 숨기고, 스스로를 억누르고 있었지.",
  ui_story_5080_50800802_50_dialog_content = "듣고 보니까 확실히 그런 느낌이 있었어... 나랑 전임 대장은 일루미나 출신이라,\n거기 있을 때부터 그 사람 명성은 많이 들었거든.",
  ui_story_5080_50800802_51_dialog_content = "근데 직접 만나 보니까 생각했던 거랑 좀 다르더라고.",
  ui_story_5080_50800802_52_dialog_content = "왠지 자기 「본모습」을 감추고 있다는 느낌이 자꾸 들었단 말이지.\n어떤 싸움에서든 늘 참고 있는 느낌이었거든.",
  ui_story_5080_50800802_53_dialog_content = "그러다 마지막 순간에야 마치 「봉인」을 푼 것처럼 달라졌어.\n그런 거칠고 난폭한 대장의 모습은 처음이었다고...",
  ui_story_5080_50800802_54_dialog_content = "미쳐 날뛰는 사메야마보다 더 무시무시했다니까.",
  ui_story_5080_50800802_55_dialog_content = "그 비유 좀 굉장히 이상해.",
  ui_story_5080_50800802_56_dialog_content = "그런 그 사람마저 <color=#FFB400>그 암귀</color>에게 목숨을 잃었는데, 우리가 이길 수 있을까?",
  ui_story_5080_50800802_57_dialog_content = "분노의 화산은 곧 폭발할 기세고, 어둠의 위기가 다시 찾아올 수도 있어.\n지금의 레디젤 렌치가 이 모든 걸 다 막아낼 수 있겠어?",
  ui_story_5080_50800802_58_dialog_content = "그걸 말이라고 하냐?",
  ui_story_5080_50800802_59_dialog_content = "얼마든지 오라고!",
  ui_story_5080_50800802_60_dialog_content = "어떻게 생겨 먹은 암귀든, 내가 이 렌치로 제대로 날려줄 테니 말이야!",
  ui_story_5080_50800802_61_dialog_content = "그 암귀가 간이 배 밖으로 튀어나와 내 앞에 나타나 줬으면 좋겠군.\n내가 두 번 다시 날뛰지 못하게 만들어 주지, 반드시!",
  ui_story_5080_50800802_62_dialog_content = "아이테르 1호, 해칠링 2호, 둘 다 내 말 잘 들어.",
  ui_story_5080_50800802_63_dialog_content = "왜 그래? 갑자기 귓속말을 다 하고...",
  ui_story_5080_50800802_64_dialog_content = "우리 임무는... 되도록 그 암귀를 생포하는 거야.",
  ui_story_5080_50800802_65_dialog_content = "경우에 따라선, 사메야마가 놈을 죽이지 못하게 막아야 해.",
  ui_story_5080_50800901_1_dialog_content = "또 처음 보는 좁은 길이야. 이 아래는 대체 뭐가 어떻게 된 거야?",
  ui_story_5080_50800901_2_dialog_content = "넓어지기 시작했어. 이쪽이 제대로 된 길 같아.",
  ui_story_5080_50800901_3_dialog_content = "사막의 지하는 대체로 복잡해. 이 구조로 보자면 여긴 원래 지맥의 회랑의 벽이 아니었을까 싶어.",
  ui_story_5080_50800901_4_dialog_content = "화산 폭발로 흘러나온 용암 때문에 벽면에 구멍이 생겼을 거야.\n암귀들이 그 구멍을 뚫어서 지금과 같은 길을 만든 거고.",
  ui_story_5080_50800901_5_dialog_content = "암벽을 살펴보면 구멍을 판 건 확실해. 다만 공구를 써서 말이야.",
  ui_story_5080_50800901_6_dialog_content = "그러니까 암귀가 판 게 아니라는 거냐?",
  ui_story_5080_50800901_7_dialog_content = "사막엔 아주 오래전부터 사람이 살고 있었어. 아마 그들이 지맥의 회랑을 개척했겠지.",
  ui_story_5080_50800901_8_dialog_content = "이건... 바닥을 봐. 강렬한 진동 때문에 지층이 갈라졌어.",
  ui_story_5080_50800901_9_dialog_content = "아래엔 잘려진 석재가 있어. 이건 건물의 바닥이야.\n여긴 한때 인간이 지은 건물이었던 게 분명해.",
  ui_story_5080_50800901_10_dialog_content = "뭐? 근데 여긴 화산 입구 근처잖아!",
  ui_story_5080_50800901_11_dialog_content = "그렇구나. 그래서 암벽에 공구를 사용한 흔적이 남았던 거야.\n사람들은 함부로 지맥을 파헤친 게 아니라 여기 건물을 지은 거지.",
  ui_story_5080_50800901_12_dialog_content = "어? 일루미나 병사, 뭐 하고 있어? 이런 때 흙놀이 중인 거냐?",
  ui_story_5080_50800901_13_dialog_content = "소란 피울 거 없어. 재료 틈 깊숙한 곳에 남은 잔여물을 파내고 있는 거야.\n그게 여기의 자세한 사정을 알려줄 테니 말이야.",
  ui_story_5080_50800901_14_dialog_content = "석재에 움푹 파인 홈 세 개가 뚜렷하게 남아 있어. 틈새 안에는 불에 탄 재도 있고.",
  ui_story_5080_50800901_15_dialog_content = "틀림없어. 아주 오래전에 누군가가 여기서 솥을 걸고 불을 피웠을 거야.",
  ui_story_5080_50800901_16_dialog_content = "여기서부터 방금 지나온 입구까지의 거리는 딱 방 하나 정도 크기야. 여긴 지하 피난소였던 거지.",
  ui_story_5080_50800901_17_dialog_content = "오래전이라면 여기에 암귀는 없었을 가능성이 높아. 아마 누군가가 쓰던 피난소였겠지.",
  ui_story_5080_50800901_18_dialog_content = "화산이 폭발해 모든 걸 뒤덮기 전까지, 그들은 한때 여기 숨어 있었어.",
  ui_story_5080_50800901_19_dialog_content = "역시 맹금류 아가씨라니까. 말 몇 마디로 여기 묻혀 있던 옛이야기를 끄집어냈잖아.",
  ui_story_5080_50800901_20_dialog_content = "나도 이 나이 먹도록 처음 봤는데 말이야. 하긴, 그러니까 벌써 그 나이에 정찰대장이 됐겠지.",
  ui_story_5080_50800901_21_dialog_content = "사메야마, 지하에서 사는 사람들이 있다는 얘기 들어본 적 있어?",
  ui_story_5080_50800901_22_dialog_content = "나랑 이브도 따지고 보면 밖에서 온 사람인데, 오래전 사정을 어떻게 알겠어?",
  ui_story_5080_50800901_23_dialog_content = "나랑 로이 둘 다 일루미나 출신이야. 나이 지긋한 로이 아저씨도 이 얘기는 모를걸?",
  ui_story_5080_50800901_24_dialog_content = "그 눈빛은 뭐야? 나 아직 젊다고! 게다가 사메야마도 모르는 걸 내가 어떻게 알겠어!",
  ui_story_5080_50800901_25_dialog_content = "근데 여기 정말 사람이 살았다면, 왜 다들 전혀 못 들어본 거지?",
  ui_story_5080_50800901_26_dialog_content = "용사 제타도 들어본 적 없어. 설마 무슨 고대 원시 유적 같은 거야?\n어떤 강력한 힘이 묻혀 있는 건 아닐까? 빛의 거인이라거나?",
  ui_story_5080_50800901_27_dialog_content = "다들 이렇게 역사에 무관심해지다니... 미안해.\n다 내가 열심히 공부하라고 제대로 안 잡아 준 탓이야...",
  ui_story_5080_50800901_28_dialog_content = "나한테는 매달 책을 정리해서 보내달라고 해 놓고, 결국 안 본 거구나.",
  ui_story_5080_50800901_29_dialog_content = "미안해, 예리아.",
  ui_story_5080_50800901_30_dialog_content = "우리한테 더 중요한 건 그런 게 아냐!",
  ui_story_5080_50800901_31_dialog_content = "맞아 맞아. 용사 제타는 지난 일들을 신경 쓸 시간 따윈 없다구.",
  ui_story_5080_50800901_32_dialog_content = "하아, 이미 예상하긴 했지만, 막상 이야기를 듣고 있자니 참... 어이가 없네.",
  ui_story_5080_50800901_33_dialog_content = "다들 정말 앞만 보느라 발밑의 땅도, 옛사람들의 부탁이 뭘 뜻하는지도 전혀 생각을 안 했구나.",
  ui_story_5080_50800901_34_dialog_content = "예리아 씨, 분명히 뭘 알고 있는 거지? 우리한테도 말해줘.",
  ui_story_5080_50800901_35_dialog_content = "난 사막에 대한 이해는 그리 깊진 않지만, 피난소라면... 마침 관련 있는 이야기를 알고 있어.",
  ui_story_5080_50800901_36_dialog_content = "그건 「레디젤 렌치」의 기원이기도 해.",
  ui_story_5080_50800901_37_dialog_content = "전임 대장이 도적들을 제압해 거둬들이면서 우리 「레디젤 렌치」가 생겨난 거 아냐?",
  ui_story_5080_50800901_38_dialog_content = "오래전 이 사막엔 무질서하게 살아가는 유민들, 그리고 범죄자들이 있었어.",
  ui_story_5080_50800901_39_dialog_content = "그들은 바깥세상이 두려웠거나, 아니면 싫증이 나서\n차라리 이 거친 사막에서 살아가는 편을 택했어.",
  ui_story_5080_50800901_40_dialog_content = "이곳이 「자유롭다」고 믿었거든.",
  ui_story_5080_50800901_41_dialog_content = "자유라...",
  ui_story_5080_50800901_42_dialog_content = "어느 날, 가문이 핍박을 받던 백야성의 한 아가씨가\n자신을 모시던 하녀의 손에 이끌려 사막에 들어섰어.",
  ui_story_5080_50800901_43_dialog_content = "하녀는 자신의 주인을 모든 분쟁에서 멀리 떨어진 자신의 고향으로 데려가고 싶었던 거야.",
  ui_story_5080_50800901_44_dialog_content = "「백야성의 분쟁」...인 건가.",
  ui_story_5080_50800901_45_dialog_content = "한 백야성 경비병이 명령을 받고 두 사람을 쫓았어. 그는 기사의 명예가 전부라고 믿는 자였지.",
  ui_story_5080_50800901_46_dialog_content = "재미있게도, 일루미나 병사 한 명도 그 사람처럼 사막에 왔었어.\n그는 마을을 돌아다니며 일루미나의 탈영병을 조사 중이었지.",
  ui_story_5080_50800901_47_dialog_content = "그 병사가 쫓던 자는 전의를 잃고, 지키겠다는 신념도 잃어버린 한 공병이었어.",
  ui_story_5080_50800901_48_dialog_content = "전의를 잃은 일루미나의 병사...",
  ui_story_5080_50800901_49_dialog_content = "추격 과정에서 일루미나의 집행자는 우여곡절 끝에 백야성 경비병이\n자신과 같은 목표를 쫓는 중이라고 오해하게 됐어.",
  ui_story_5080_50800901_50_dialog_content = "그리고 우연히 공병을 만난 아가씨와 하녀는 상대를 현상금 사냥꾼이라고 착각했지.",
  ui_story_5080_50800901_51_dialog_content = "숨 막히는 공포와 쫓고 쫓기는 치열한 추격 속에서,\n이들은 가혹한 운명에 이끌려 한데 엮이고 말았어.",
  ui_story_5080_50800901_52_dialog_content = "마지막엔 공병의 도움으로 아가씨와 하녀는 무사히 기사의 추격을 피할 수 있었고...",
  ui_story_5080_50800901_53_dialog_content = "기사의 방해로 탈영병을 놓친 집행자도 솔트록 마을로 향하는 수밖에 없었지.",
  ui_story_5080_50800901_54_dialog_content = "그거 왠지 바보들의 전설처럼 들리는데.",
  ui_story_5080_50800901_55_dialog_content = "맞아, 그들이 모두 「바보」였기 때문에 서로를 끝까지 해치지 않았던 거야.",
  ui_story_5080_50800901_56_dialog_content = "그들은 자신만의 신념을 가지고 있었지만, 기회를 잡고도 상대를 해치려 하지 않았어.",
  ui_story_5080_50800901_57_dialog_content = "그치만 난 그 이야기가 정말 마음에 들어.",
  ui_story_5080_50800901_58_dialog_content = "마지막 여정에서 이들은 보기 드문 모래폭풍을 만났고,\n길 위에 있는 모든 게 거친 모래에 파묻히고 말았어.",
  ui_story_5080_50800901_59_dialog_content = "위기의 순간, 사냥감은 사냥꾼에게 도움의 손길을 내밀었고,\n 사냥꾼도 자신의 임무를 포기했지.",
  ui_story_5080_50800901_60_dialog_content = "이런저런 일들을 겪으며 사냥꾼들의 임무는 기한을 넘겨버렸고,\n어느새 자신들도 「탈영병」 취급을 받게 되고 말았어.",
  ui_story_5080_50800901_61_dialog_content = "비슷한 처지인 데다 서로를 도왔던 감정이 쌓이면서,\n그들은 마침내 서로를 이해하고 신뢰할 수 있었어.",
  ui_story_5080_50800901_62_dialog_content = "그래서 결국엔 함께 솔트록 마을로 가서 평화롭게 살기로 약속했던 거야.",
  ui_story_5080_50800901_63_dialog_content = "그 이야기는 해피엔딩인 거야?",
  ui_story_5080_50800901_64_dialog_content = "아니. 하녀의 고향, 그러니까 소문의 오아시스인 솔트록 마을에 도착한 이들은\n그제서야 화산 폭발로 마을이 파괴됐다는 걸 알게 됐어.",
  ui_story_5080_50800901_65_dialog_content = "그나마 목숨을 건진 사람들도 마을 밖에서 이 틈을 노리고 온 도적 떼에게\n약탈당하면서 궁지에 몰려 있었어.",
  ui_story_5080_50800901_66_dialog_content = "그들을 위한 오아시스는 전혀 존재하지 않았고, 그토록 갈망하던 평안도 누릴 수 없었어.",
  ui_story_5080_50800901_67_dialog_content = "희망을 잃은 외부인들은 이곳이 바깥세상과 전혀 다르지 않다는 것을 깨달았어.",
  ui_story_5080_50800901_68_dialog_content = "......",
  ui_story_5080_50800901_69_dialog_content = "마을 성녀의 인도에 따라 출구로 달아나던 생존자들은 때마침 마을을 찾아온\n이 외부인들과 마주치게 됐어.",
  ui_story_5080_50800901_70_dialog_content = "구원을 찾아서 온 이들이 졸지에 누군가의 구원자가 되었던 거야.",
  ui_story_5080_50800901_71_dialog_content = "굳건한 의지를 지켜왔던 기사도, 반드시 철칙을 따르는 군인도 그 순간 그들을 외면할 수 없었어.",
  ui_story_5080_50800901_72_dialog_content = "그러나 그 위기일발의 상황에서 렌치를 든 공병이 도적 떼에게\n달려들 줄은 누구도 짐작하지 못했지.",
  ui_story_5080_50800901_73_dialog_content = "그의 용감한 행동이 모든 사람을 격려했고, 도적 떼는 결국 달아났어.",
  ui_story_5080_50800901_74_dialog_content = "영웅 이야기였구나! 제타 알아, 그때 든 렌치가 바로 레디젤 렌치 맞지?",
  ui_story_5080_50800901_75_dialog_content = "후훗, 서두르지 마. 이야기는 아직 끝나지 않았으니까.",
  ui_story_5080_50800901_76_dialog_content = "그 공병 덕분에 사람들은 희망을 되찾았고, 사막에서 새로운 오아시스를 찾는 여정을\n다시 시작하게 됐어.",
  ui_story_5080_50800901_77_dialog_content = "그 과정에서 그들은 점점 더 많은 유민들을 받아들였고,\n어느새 막강한 세력으로 성장하게 됐던 거야.",
  ui_story_5080_50800901_78_dialog_content = "그들은 마침내 「레디젤」이 풍부한 작은 오아시스를 찾았고, 그곳에 캠프를 세웠어.",
  ui_story_5080_50800901_79_dialog_content = "이게 바로 아탈... 아니, 전임 대장이 내게 들려준 전설이야.",
  ui_story_5080_50800901_80_dialog_content = "이 전설은 오래전 이 사막에 오로리안이 생존했었다는 걸 확실히 증명하고 있어.",
  ui_story_5080_50800901_81_dialog_content = "그들도 우리처럼 자신의 삶을 찾으려고 최선을 다했던 거군.",
  ui_story_5080_50800901_82_dialog_content = "지하 피난소는 추격병이나 도적을 피하는 용도로 쓰였던 거겠지?",
  ui_story_5080_50800901_83_dialog_content = "근데 그들이 화산 폭발에 파묻힌 건지, 아니면 통로 깊은 곳에서 화산을 발견하고 떠난 건지는...\n나도 몰라.",
  ui_story_5080_50800901_84_dialog_content = "쳇, 이거 좀 질투가 난단 말이지... 불공평하잖냐!\n전임 대장은 왜 너만 특별하게 대한 거냔 말이다! 우리한텐 아무 얘기도 해 준 적 없었다고.",
  ui_story_5080_50800901_85_dialog_content = "그거야 너희들이 이런 데 전혀 관심이 없었으니까 그렇지.",
  ui_story_5080_50800901_86_dialog_content = "난 한때 지적 호기심이 충만했어. 그래서 그 사람의 이야기에도 관심이 많았고,\n늘 이야기를 들려달라고 조르곤 했어.",
  ui_story_5080_50800901_87_dialog_content = "하지만 이 이야기를 봐.\n네가 더 많이 알수록 과거는 결국 사라지고 만다는 허무감에 사로잡히게 돼...",
  ui_story_5080_50800901_88_dialog_content = "게다가 사메야마 넌 그때 막 합류한 데다가 동생을 돌보느라 정신이 없었잖아.",
  ui_story_5080_50800901_89_dialog_content = "그땐 지금과 달리 모든 게 쉽지 않았어. 매일 먹을 걸 찾아다니는 것만으로도 바빴다고.",
  ui_story_5080_50800901_90_dialog_content = "그리고 너도 마찬가지였지. 아주르한테 운전이다 뭐다 가르쳐 준다고 말이야!",
  ui_story_5080_50800901_91_dialog_content = "그저 살아있으면 된 거라고... 지금을 살아가는 것만으로도 충분하다고 난 늘 그렇게 생각해 왔어.",
  ui_story_5080_50800901_92_dialog_content = "그때 우린 이런 것들을 찾아 나설 여유가 없었어.",
  ui_story_5080_50800901_93_dialog_content = "뭐, 상관없잖아. 이젠 다르다고!",
  ui_story_5080_50800901_94_dialog_content = "지금 레디젤 렌치에서 지내는 건 무척 만족스러워.\n난 최고의 지식인이 될 수 있는 조건도 갖추고 있다고.",
  ui_story_5080_50800901_95_dialog_content = "사메야마, 돌아가면 두고 봐! 열심히 공부해서 꼭 너보다 더 훌륭한 리더가 될 테니까.",
  ui_story_5080_50800901_96_dialog_content = "이 자식... 지금 편하게 사는 건 내 덕 아니었냐?",
  ui_story_5080_50800901_97_dialog_content = "그러니까... 이야기 속 그 사람이 들고 있던 렌치가 당신들의 정신적 상징이 된 거네.",
  ui_story_5080_50800901_98_dialog_content = "하지만 일루미나 공병의 렌치는 애초에 무기가 아냐. 그리고 저렇게 크게 만들지도 않아.",
  ui_story_5080_50800901_99_dialog_content = "지금 레디젤 두목이 쥔 렌치 무게는 아마 톤 단위일 것 같은데?",
  ui_story_5080_50800901_100_dialog_content = "그래, 이젠 나 말고 이걸 자유롭게 휘두를 수 있는 사람은 거의 없지.",
  ui_story_5080_50800901_101_dialog_content = "어떤 공병이 그런 렌치를 들고 다니겠어?",
  ui_story_5080_50800901_102_dialog_content = "맹금류 아가씨는 이 이야기가 가짜라고 생각해?",
  ui_story_5080_50800901_103_dialog_content = "그 「소문」은 당신들 두목이 레디젤 렌치의 과거를 미화하려고 꾸며낸 얘기일 수도 있어.",
  ui_story_5080_50800901_104_dialog_content = "일루미나의 자료에 따르면 이 사막에는 늘 도적 떼가 활개 치며 악행을 일삼았고,\n사람들을 선동해서 탈영을 부추겼다고 해.",
  ui_story_5080_50800901_105_dialog_content = "이들은 자길 「레디젤 클랜」이라고 하면서 줄곧 다른 오로리안들을 위협했어.",
  ui_story_5080_50800901_106_dialog_content = "그리고 그 사람은... 내 고모를 데리고 갔다가 탈영병으로 만들더니,\n어느새 여기로 도망쳐서 레디젤 클랜의 우두머리가 됐지.",
  ui_story_5080_50800901_107_dialog_content = "그 여자는 유민들을 강제로 자기 세력에 끌어들여 힘을 키웠고,\n서서히 이 사막을 지배하기 시작했어. 그리고 마침내 「레디젤 렌치」가 탄생했던 거야.",
  ui_story_5080_50800901_108_dialog_content = "당신이 말한 이야기는 그저 레디젤 렌치의 역사를 미화하려고\n그 여자가 지어낸 것일 가능성이 높아.",
  ui_story_5080_50800901_109_dialog_content = "어이, 일루미나 아가씨. 다른 사람이 존경하는 대상한테 막말을 하면 안 된다는 건 못 배웠나?",
  ui_story_5080_50800901_110_dialog_content = "우리가 잠깐 힘을 합쳤다고 해서 그런 말을 해도 된다는 뜻은 아니라고!",
  ui_story_5080_50800901_111_dialog_content = "잠깐만, 이상하지 않아? 레이첼 네 말대로라면 그 사람은 여길 이미 지배하게 됐는데,\n왜 굳이 과거를 미화하려고 하는데?",
  ui_story_5080_50800901_112_dialog_content = "난 레디젤 렌치가 믿는 그 사람이 그런 짓을 하진 않았을 것 같아.",
  ui_story_5080_50800901_113_dialog_content = "그럼 그 여자가... 설마 진심으로 사람들을 지키려고 했던 걸까?",
  ui_story_5080_50800901_114_dialog_content = "그래서... 너희들의 정신까지 지키려고...?",
  ui_story_5080_50800901_115_dialog_content = "......",
  ui_story_5080_50800901_116_dialog_content = "거 봐라, 말하면 다 알아듣는 녀석이면서... 쳇.",
  ui_story_5080_50800901_117_dialog_content = "...잠깐만, 또 지진인 거야?",
  ui_story_5080_50800901_118_dialog_content = "아니, 이건 암귀들이 움직이는 거야.",
  ui_story_5080_50800901_119_dialog_content = "좋아, 그럼 잘 봐두라고, 일루미나의 「군대개미 아가씨」!\n우리 레디젤 렌치의 생존법과 가족을 지키는 결심을 보여줄 테니 말이야!",
  ui_story_5080_50800901_120_dialog_content = "지금 바로 모든 힘을 꺼내서 확실하게 보여주마!",
  ui_story_5080_50801000_1_dialog_content = "아이참, 온통 화상 입었잖아. 오빠, 너무 흥분했어.",
  ui_story_5080_50801000_2_dialog_content = "이 정도 상처쯤은 아무렇지도 않아!",
  ui_story_5080_50801000_3_dialog_content = "어이, 로이, 슬슬 밥 시간 아냐? 다들 배고플 거라고!",
  ui_story_5080_50801000_4_dialog_content = "뭐 맛있는 게 있으려나?",
  ui_story_5080_50801000_5_dialog_content = "아, 그렇네── 좋아, 그럼 준비해 볼까. 얘들아, 냄비 꺼내.",
  ui_story_5080_50801000_6_dialog_content = "도엔, 가자! 분화구에서 「야생의 맛」을 잡아 오자고!",
  ui_story_5080_50801000_7_dialog_content = "당신들 뭐 하는 거야?",
  ui_story_5080_50801000_8_dialog_content = "당연히 「워라밸」을 지키려는 거 아니겠어? 일루미나의 아가씨.",
  ui_story_5080_50801000_9_dialog_content = "놀랄 거 없어. 항상 저러거든... 배부르게 먹고 나면 일도 잘할 거야.",
  ui_story_5080_50801000_10_dialog_content = "저 사람들 「괴식」 먹기 싫으면 우리도 챙긴 거 있어.",
  ui_story_5080_50801000_11_dialog_content = "지금은 임무 중이잖아!",
  ui_story_5080_50801000_12_dialog_content = "남이 먹자고 밥부터 먹겠다니... 기습이라도 당하면 어쩔 셈이야?",
  ui_story_5080_50801000_13_dialog_content = "해칠링 2호, 아이테르 1호, 화이트 랜서, 우린 임무를 계속 수행한다.",
  ui_story_5080_50801000_14_dialog_content = "응, 대장!",
  ui_story_5080_50801000_15_dialog_content = "<color=#e8d9bb>꼬르륵──</color>",
  ui_story_5080_50801000_16_dialog_content = "앗... 미안... 아침밥을 제때 못 먹었더니...",
  ui_story_5080_50801000_17_dialog_content = "......",
  ui_story_5080_50801000_18_dialog_content = "대장, 내가 아는 일루미나의 고참 병사가 한 명 있는데,\n늘 우리한테 「잘 먹어야 싸울 힘이 난다」고 말하거든.",
  ui_story_5080_50801000_19_dialog_content = "그 사람은 그걸 자기 격언으로 삼았고, 다들 그 말에 동의했어.",
  ui_story_5080_50801000_20_dialog_content = "제타랑 바이스는 일어나자마자 싸우고 계속 이동했잖아...",
  ui_story_5080_50801000_21_dialog_content = "밥도 못 먹고 계속 싸우는 느낌을 일루미나의 고참들이라면 다 잘 알고 있을걸.",
  ui_story_5080_50801000_22_dialog_content = "하지만 그 사람들은 그래도 버틸 수 있었어.",
  ui_story_5080_50801000_23_dialog_content = "그러니까 후배들이라도 밥을 잘 먹었으면 하는 생각이었던 거야.",
  ui_story_5080_50801000_24_dialog_content = "...에너지를 보충하지 않으면 이동할 수 없겠지. 임무 완수를 위해 지금 휴식과 식사를 허가할게.",
  ui_story_5080_50801000_25_dialog_content = "보초는 내가 서겠어. 모두가 긴장을 풀어버리면 안 되니까...",
  ui_story_5080_50801000_26_dialog_content = "대장, 하다못해 전투식량 정도라도 같이 먹으면 되잖아! 대장!",
  ui_story_5080_50801000_27_dialog_content = "내버려둬. 임무를 무사히 끝내고 싶다는 생각뿐일 테니까.",
  ui_story_5080_50801000_28_dialog_content = "우리 왔... 어? 왜 다들 먼저 먹고 있어?!",
  ui_story_5080_50801000_29_dialog_content = "용사 제타는 뭘 하든 항상 1등이야! 그럼 난 보초 서는 거 도와주러 갈게!",
  ui_story_5080_50801000_30_dialog_content = "...넌 식사 속도가 꽤 빠르구나. 훈련까지 더하면 훌륭한 군인이 될 수 있을 거야.",
  ui_story_5080_50801000_31_dialog_content = "제타는 일루미나 병사가 되는 건 관심 없거든? 난 세상을 구할 운명을 지닌 자니까!",
  ui_story_5080_50801000_32_dialog_content = "너도 먹어 봐! 이 벌레구이 육포 진짜 맛있어! 제타가 너 주려고 특별히 가져온 거야.",
  ui_story_5080_50801000_33_dialog_content = "고마워... 「캔디걸」.",
  ui_story_5080_50801000_34_dialog_content = "제타는 「구세주 용사」지, 그런 행인 캐릭터 같은 「캔디걸」이 아니라구!",
  ui_story_5080_50801000_35_dialog_content = "넌 멋있긴 하지만 아직 품위가 부족해! 분명히 어린 나이에 「마왕군」에 끌려가서 그런 거겠지?",
  ui_story_5080_50801000_36_dialog_content = "정말 고생이 많았겠네, 「구세주의 잃어버렸던 숙적 언니」!",
  ui_story_5080_50801000_37_dialog_content = "「언니」...?",
  ui_story_5080_50801000_38_dialog_content = "응! 제타는 언니의 「용사 여동생」이야.\n걱정 마, 언니의 정신 속박을 풀 방법을 꼭 찾아줄 테니까!",
  ui_story_5080_50801000_39_dialog_content = "어? 지금 웃은 거야? 웃는 거 처음 봤어... 역시 이런 게 가족의 힘이란 건가?!",
  ui_story_5080_50801000_40_dialog_content = "너무 신경 쓰지 마. 소꿉놀이를 좋아해서 멋대로 설정하는 것뿐이니까...",
  ui_story_5080_50801000_41_dialog_content = "언니라... 후후...",
  ui_story_5080_50801000_42_dialog_content = "뭔가 생각난 모양인데, 너 여동생이 있구나? 그렇지?",
  ui_story_5080_50801000_43_dialog_content = "맞아... 똑똑한 데다 나보다 튼튼해. 그리고... 귀엽고.",
  ui_story_5080_50801000_44_dialog_content = "졸업하면 분명히 훌륭한 군인이 될 거야.",
  ui_story_5080_50801000_45_dialog_content = "난 동생이 무척 자랑스러워.",
  ui_story_5080_50801000_46_dialog_content = "뭐야... 에이...",
  ui_story_5080_50801000_47_dialog_content = "제타, 인정할 수 없다는 표정인데.",
  ui_story_5080_50801000_48_dialog_content = "부러워... 질투하는 거 아냐! 그러니까 제타 말은...",
  ui_story_5080_50801000_49_dialog_content = "이런 언니가 있다면... 동생은 분명히 행복하겠지.",
  ui_story_5080_50801000_50_dialog_content = "「호크 슈터」는 저 마녀보단 훨씬 다정할 테니까.",
  ui_story_5080_50801000_51_dialog_content = "아니, 난 아직 멀었어.",
  ui_story_5080_50801000_52_dialog_content = "좀 더 노력해야 해... 좀 더... 더는 가족에게 폐를 끼치지 않게 말이야.",
  ui_story_5080_50801000_53_dialog_content = "워우어어어──♪",
  ui_story_5080_50801000_54_dialog_content = "왜 갑자기 노래를 부르고 앉았어? 시끄러워!",
  ui_story_5080_50801000_55_dialog_content = "모르는 모양인데, 바바라가 쟤한테 너보다 더 재능이 있다고 그랬거든.",
  ui_story_5080_50801000_56_dialog_content = "뭐야?!",
  ui_story_5080_50801000_57_dialog_content = "「사메야마보다 더 훌륭한 레디젤 최고의 테너」── 바바라가 그랬어, 오빠.",
  ui_story_5080_50801000_58_dialog_content = "그래서 저렇게 죽어라 연습하는 거라고. 벌써 노래로 청중을 휘어잡을 준비가 됐다고 하던데?",
  ui_story_5080_50801000_59_dialog_content = "이런, 그럼 나도 연습해야겠네. 밴드에 들어가 주겠다고 약속했거든.",
  ui_story_5080_50801000_60_dialog_content = "드럼 스틱이 어디 있더라... 이건 아니고... 이것도 아니고... 아, 찾았다!",
  ui_story_5080_50801000_61_dialog_content = "자, 내가 박자를 쳐 줄 테니까 다 같이 연습 시작하자고!",
  ui_story_5080_50801000_62_dialog_content = "뭐야, 이 녀석들...",
  ui_story_5080_50801000_63_dialog_content = "더 격렬하게! 더! 플뢰르, 네 모든 열정을 드럼 스틱에 쏟아부어!",
  ui_story_5080_50801000_64_dialog_content = "내 목소리를 쫓아 와──! 템포! 더 빨리! 더 빨리!",
  ui_story_5080_50801000_65_dialog_content = "여기서 더 시끄럽게 굴면 암귀가 쫓아 올 거다.",
  ui_story_5080_50801000_66_dialog_content = "벽 두들기지 마, 플뢰르. 암귀가 온다고!",
  ui_story_5080_50801000_67_dialog_content = "그나마 사메야마한테 상식이란 게 있어 다행이야, 레디젤 렌치...",
  ui_story_5080_50801000_68_dialog_content = "자, 렌치 빌려줄 테니까 연습할 거면 여기다 치라고. 더 과격해도 괜찮아!",
  ui_story_5080_50801000_69_dialog_content = "암귀가 몰려들면 어쩌려고 그래?",
  ui_story_5080_50801000_70_dialog_content = "상관없잖아? 놈들을 못 찾을까 걱정하던 거 아니었나? 더! 더 빨리! 템포가 안 맞잖아!",
  ui_story_5080_50801000_71_dialog_content = "하아... 답이 없네.",
  ui_story_5080_50801000_72_dialog_content = "이렇게 광활한 사막에 살면서 탐구심도 없이 날마다 저렇게 소란만 피우고 있으니...",
  ui_story_5080_50801000_73_dialog_content = "근데 예리아 씨, 탐구심이란 과연 뭘까요?",
  ui_story_5080_50801000_74_dialog_content = "아이테르 군, 너도 정신이 멍해지기 시작한 거니?",
  ui_story_5080_50801000_75_dialog_content = "아니요, 전 그냥... 저 사람들은 이런 거친 환경에서 살아왔지만,\n왠지 한 번도 불평한 적이 없는 것 같아서요...",
  ui_story_5080_50801000_76_dialog_content = "저들은 지금까지 줄곧 즐거운 삶의 방식을 찾으려고 노력해 왔어요.\n그리고 확실히 즐겁게 지내고 있고요.",
  ui_story_5080_50801000_77_dialog_content = "그래서 전 레디젤 렌치가 자기 인생에 대한 탐구심을 이미 충분히 가지고 있는 것 같거든요.",
  ui_story_5080_50801000_78_dialog_content = "맞아요. 예리아 씨는 해박한 지식을 갖고 있지만, 일상에선 조금 소극적이잖아요...",
  ui_story_5080_50801000_79_dialog_content = "그게 정말 좋은 걸까요?",
  ui_story_5080_50801000_80_dialog_content = "일루미나 소속인 바이스 양이 그런 말을 하면 내가 뭐라고 답해야 할지 잘 모르겠는걸.",
  ui_story_5080_50801000_81_dialog_content = "어쩌면 예리아 씨는 일루미나 사람들이 삶과 자유를 이야기할 자격이 없다고 생각할 수도 있겠죠.",
  ui_story_5080_50801000_82_dialog_content = "하지만 전 어릴 적부터 거기서 자라면서 확실하게 알게 됐어요.\n소중한 사람을 지키기 위한 방어선이 되는 것, 그게 바로 일루미나의 정신이란 걸요.",
  ui_story_5080_50801000_83_dialog_content = "어쩌면 우린 자신을 희생하게 될 수도 있겠죠.\n하지만 그렇게 해서 만들어진 방어선 뒤에서는 사람들이 행복하게 살아갈 수 있어요.",
  ui_story_5080_50801000_84_dialog_content = "저 사람들의 미소 같은 게 바로 제가 지키고 싶은 목표인 거예요.",
  ui_story_5080_50801000_85_dialog_content = "전 사람들이 열심히 살아가는 걸 볼 수 있어서 기뻐요.\n저렇게 자유를 누리는 모습을 볼 수 있는 것만으로 전 충분하다고 생각해요.",
  ui_story_5080_50801000_86_dialog_content = "지키는... 의미...?",
  ui_story_5080_50801000_87_dialog_content = "그렇구나, 너희들은 삶에 대한 견해도 다른 점이 있었네.",
  ui_story_5080_50801000_88_dialog_content = "타인을 위해 사는 건가... 조금 자유롭지 않을 순 있겠지만,\n난 그것도 무척 대단한 일이라고 생각해.",
  ui_story_5080_50801000_89_dialog_content = "으음, 어떻게 상상해야 할까? 스스로 노력해서 삶을 탐구해야 하는데,\n다른 사람들과 밀접한 관계도 맺는다는 건...",
  ui_story_5080_50801000_90_dialog_content = "전 역시 사람과 사람의 연결은 끊을 수 없는 거라고 생각해요.",
  ui_story_5080_50801000_91_dialog_content = "아무리 예리아 씨가 즐거운 바보가 되고 싶지 않다고 해도,\n이젠 모두와의 관계를 끊을 수도 없잖아요?",
  ui_story_5080_50801000_92_dialog_content = "...그러게, 지금 집안은 온통 낙서투성이고, 아이들한테 줄 선물과 책이 잔뜩 쌓여 있으니까.",
  ui_story_5080_50801000_93_dialog_content = "아무리 모습을 감추고 다녀도, 숨어 있는 아이들한테 걸리거나,\n아이들이 내 차까지 멋대로 몰고 나가고 말이야.",
  ui_story_5080_50801000_94_dialog_content = "조금 부딪히긴 했지만 제타가 확실히 고쳐놨어!",
  ui_story_5080_50801000_95_dialog_content = "특별한 부품으로 잘 덧댔거든.",
  ui_story_5080_50801000_96_dialog_content = "그런데도 예리아 씨는 아직도 자기가 다른 사람과 아무 접점도 없다고 생각해요?",
  ui_story_5080_50801000_97_dialog_content = "뭐야, 아이테르 군이 내 인간관계에 그렇게 관심이 많았던 거야? 혹시 나 걱정하는 거니?",
  ui_story_5080_50801000_98_dialog_content = "저들 사이에 동화된다고 해서 내 방황이 줄어들진 않을 거야.",
  ui_story_5080_50801000_99_dialog_content = "그래! 바로 이 템포다!",
  ui_story_5080_50801000_100_dialog_content = "너희들의 열정과 마음이 느껴진다! 자! 다 같이!",
  ui_story_5080_50801000_101_dialog_content = "<color=#e8d9bb>사메야마의 지휘 하에서 레디젤 렌치 멤버들은 「죽도록」 노래를 불렀다.</color>",
  ui_story_5080_50801000_102_dialog_content = "<color=#e8d9bb>조화라고는 전혀 없는 노랫소리였지만, 모두가 최선을 다해 노래를 불렀다.\n누구도 멈출 생각을 하지 않는 그 모습에선 모종의 유대가 느껴졌다.</color>",
  ui_story_5080_50801000_103_dialog_content = "다들 개성이 너무 뚜렷해. 애초에 하나로 뭉칠 만한 사람들이 아냐.",
  ui_story_5080_50801000_104_dialog_content = "그런데 그런 녀석들이 모여서 「가족」이 됐어.",
  ui_story_5080_50801000_105_dialog_content = "노래도 노래지만 냄비 안 엎게 조심해.",
  ui_story_5080_50801000_106_dialog_content = "참, 예리아 씨, 제가 저번에 용주에 다녀 왔거든요. 거긴 「훠궈」라는 특이한 조리법이 있어요.",
  ui_story_5080_50801000_107_dialog_content = "냄비에 매운 국물을 넣고 끓이다가 온갖 재료를 넣고 건져서 먹는 거예요.",
  ui_story_5080_50801000_108_dialog_content = "근데 어떤 재료를 넣든지 국물에서 나오는 본연의 맛은 변하지 않아요.",
  ui_story_5080_50801000_109_dialog_content = "전 지금 사막에서 살고 있는 저들도 똑같다고 생각해요.",
  ui_story_5080_50801000_110_dialog_content = "정말 좋은 것 같다니까요. 이 사막은 모든 사람을 수용하고,\n저들이 자기 생명의 너비를 탐색할 수 있을 만큼 넓잖아요...",
  ui_story_5080_50801000_111_dialog_content = "그렇구나...",
  ui_story_5080_50801000_112_dialog_content = "예리아, 들리니? 저 매가 지금 노래하고 있어.",
  ui_story_5080_50801000_113_dialog_content = "그저 조류가 우는 것뿐이잖아.",
  ui_story_5080_50801000_114_dialog_content = "하하하! 저 새가 자기 여정을 위해 노래하는 건 아닐지 네가 어떻게 알아?",
  ui_story_5080_50801000_115_dialog_content = "...왜 나한테 그 전설을 말해준 거야?",
  ui_story_5080_50801000_116_dialog_content = "대단하지 않니? 레디젤, 백야성, 일루미나...\n태어난 곳도, 신분도 전혀 다른 사람들이 함께 걸어갈 수 있다니 말이야.",
  ui_story_5080_50801000_117_dialog_content = "이 위험천만한 세상에서 살아가기 위해, 고독한 사람들은 서로 정을 붙이게 됐어.",
  ui_story_5080_50801000_118_dialog_content = "누군가는 남을 지키기 위해 렌치를 들고 리더가 됐고,\n누군가는 그런 사람을 기꺼이 따르며 함께 노력하고 있어.",
  ui_story_5080_50801000_119_dialog_content = "그렇게 사막은 비로소 우리의 집이 된 거야.",
  ui_story_5080_50801000_120_dialog_content = "그저 여정 중에 같은 하늘을 스치고 지나갔을 뿐인데, 모여서 무리를 지어 오아시스를 찾고 있어.",
  ui_story_5080_50801000_121_dialog_content = "예리아, 자기 생명의 너비를 힘껏 탐색해 봐. 힘껏 날아서, 죽도록 노래하는 거야!",
  ui_story_5080_50801000_122_dialog_content = "넌 어째서 늘 방황하는 거니? 여긴 진작부터 널 위해 남겨둔 자리가 있는데──",
  ui_story_5080_50801101_1_dialog_content = "<color=#e8d9bb>태양처럼 뜨거운 기타 선율이 울려 퍼지며, 사막의 열기를 꿰뚫고 흔들리는 땅을 잠재웠다.</color>",
  ui_story_5080_50801101_2_dialog_content = "앞으로! 나아가! 내 의지는 영원히 멈추지 않아!",
  ui_story_5080_50801101_3_dialog_content = "날도 더운데 이런 곳에서 잘도 신곡 리허설을 하는군요.",
  ui_story_5080_50801101_4_dialog_content = "바바라도 질 수 없어! 타이니, 우리도 가자!",
  ui_story_5080_50801101_5_dialog_content = "「무대」는 다 고쳤어. 난 아직 할 일이 남았으니까 너 혼자 가.",
  ui_story_5080_50801101_6_dialog_content = "여보세요? 여기는 레디젤 렌치...",
  ui_story_5080_50801101_7_dialog_content = "보프, 요나가 빨리 돌아오라고 하던데 무슨 일 있어?",
  ui_story_5080_50801101_8_dialog_content = "여길 보세요~ 언제나 반짝반짝 빛나는 아이돌! 레디젤의 연인, 바바라예요!",
  ui_story_5080_50801101_9_dialog_content = "여보세요? 여기는 레디젤 렌치... 아주르 씨? 아주르 씨야?",
  ui_story_5080_50801101_10_dialog_content = "이런, 그쪽 꽤 시끌벅적한걸.",
  ui_story_5080_50801101_11_dialog_content = "포효한다! 뜨거운 태양이 포효한다!",
  ui_story_5080_50801101_12_dialog_content = "여보세요? 여기는 레디젤 렌치...",
  ui_story_5080_50801101_13_dialog_content = "여보세요? 전혀 안 들려. 뭐, 됐어. 언니가 갈 때까지 기다리고 있어.",
  ui_story_5080_50801101_14_dialog_content = "야, 마지! 지뢰는 잘 설치한 거야?",
  ui_story_5080_50801101_15_dialog_content = "너무 더워요... 아, 알겠다구요! 곧 끝나요!",
  ui_story_5080_50801101_16_dialog_content = "해가 지기 전까지 캠프 주변에 지뢰를 다 깔아야 돼!",
  ui_story_5080_50801101_17_dialog_content = "정말 폭탄 함정을 이렇게 잔뜩 만들 필요가 있는 건가요?",
  ui_story_5080_50801101_18_dialog_content = "<color=#e8d9bb>사막의 진동이 계속 이어지는 가운데, 멀리 떨어진 화산이 폭발하며 분노를 토해냈다.</color>",
  ui_story_5080_50801101_19_dialog_content = "대장이랑 다들 간 지도 한참 된 것 같은데...",
  ui_story_5080_50801101_20_dialog_content = "통신도 답도 없어...",
  ui_story_5080_50801101_21_dialog_content = "타이니, 플뢰르가 없으니까 네가 대신 트럭 좀 수리해 줘.",
  ui_story_5080_50801101_22_dialog_content = "흥, 결투 신청이야? 내가 너보다 더 강하다는 걸 아직도 인정 못 하겠어?",
  ui_story_5080_50801101_23_dialog_content = "뜬금없이 무슨 소리야?!",
  ui_story_5080_50801101_24_dialog_content = "트래블러호를 데리고 가 봐야 하는 거 아닐까?",
  ui_story_5080_50801101_25_dialog_content = "야, 보프! 방금 연락 온 거 아주르야?",
  ui_story_5080_50801101_26_dialog_content = "모르겠는데...",
  ui_story_5080_50801101_27_dialog_content = "네가 받아놓고 모르면 어떡해?",
  ui_story_5080_50801101_28_dialog_content = "돌아가서 순찰해 줘. 이따가...",
  ui_story_5080_50801101_29_dialog_content = "됐어, 연락 올 사람도 아마 아주르밖에 없을 테니까.",
  ui_story_5080_50801101_30_dialog_content = "어렵게 잡은 약속인데, 일 끝나면 꼭 끌고 가서 잔뜩 마셔야겠어.",
  ui_story_5080_50801101_31_dialog_content = "...내 말 좀 들어 달라니까...",
  ui_story_5080_50801101_32_dialog_content = "다 왔다. 여기가 분화구에서 가장 가까운 곳이다.",
  ui_story_5080_50801101_33_dialog_content = "여기서 뛰어내리면 분화구 안으로 곧장 내려갈 수 있다고──",
  ui_story_5080_50801101_34_dialog_content = "이 화산, 활동성이... 호크헌터 1호, 탐지 모드 작동!",
  ui_story_5080_50801101_35_dialog_content = "...역시, 활동이 무척 활발해.",
  ui_story_5080_50801101_36_dialog_content = "그런데 어째서 아직 분출 임계점에 도달하지 않은 거지?",
  ui_story_5080_50801101_37_dialog_content = "이건 사화산이 활동을 재개한 수준이 아니라 줄곧 에너지가 넘친 상태야.",
  ui_story_5080_50801101_38_dialog_content = "하지만 여긴 10여 년 동안 한 번도 폭발하지 않았어.",
  ui_story_5080_50801101_39_dialog_content = "이상해...",
  ui_story_5080_50801101_40_dialog_content = "어? 뭐야? 분화구 안에서 암귀가 기어 나오고 있잖아. 저게 가능한 건가?",
  ui_story_5080_50801101_41_dialog_content = "저 암귀들이야... 놈들의 용암 에너지는 여기서 얻은 모양이야.",
  ui_story_5080_50801101_42_dialog_content = "가자, 내려가서 해치우는 거야!",
  ui_story_5080_50801101_43_dialog_content = "바이스, 카렌... 같이 가! 너무 높잖아!",
  ui_story_5080_50801102_1_dialog_content = "암귀도 어쨌든 「생물」 아냐?",
  ui_story_5080_50801102_2_dialog_content = "그런데 어떻게 화산 속에서 살 수 있는 거지?\n용암이 무섭기는커녕, 용암 에너지를 이용하고 있잖아?",
  ui_story_5080_50801102_3_dialog_content = "플뢰르, 어떻게 해야 분화구를 무너트릴 수 있을지 계산해 봐.",
  ui_story_5080_50801102_4_dialog_content = "암귀들이 용암마저 무서워하지 않는다면, 놈들이 다시는 나오지 못하게 막을 방법은 이것뿐이야.",
  ui_story_5080_50801102_5_dialog_content = "안 돼, 저 아가씨 말이 맞아. 이건 활화산이야. 폭발이 오히려 화산 분출을 자극할 수도 있어.",
  ui_story_5080_50801102_6_dialog_content = "아직도 흔들리고 있어. 암귀들이 안에서 계속 기어 나오고 있을 거야...",
  ui_story_5080_50801102_7_dialog_content = "바깥 상황이 어떨진 모르겠네. 서두르는 게 좋겠어.",
  ui_story_5080_50801102_8_dialog_content = "왜 계속 활동 중인 화산이 이렇게 오랫동안 잠들어 있던 것처럼 보였던 거지?",
  ui_story_5080_50801102_9_dialog_content = "이유가 뭘까...",
  ui_story_5080_50801102_10_dialog_content = "화산이 분노한 건 지맥 에너지가 불안정한 탓일 가능성이 높아.",
  ui_story_5080_50801102_11_dialog_content = "원인을 찾을 수 있다면 위기를 해결할 수 있을지도 몰라.",
  ui_story_5080_50801102_12_dialog_content = "뭐, 아무튼 서두르자고.",
  ui_story_5080_50801102_13_dialog_content = "이렇게 계속 흔들리다간 암귀들도 놀라서 땅 위로 기어 나오겠어.",
  ui_story_5080_50801102_14_dialog_content = "레디젤 식구들은 버틸 수 있겠지만, 다른 마을 주민들이 곤란하군.",
  ui_story_5080_50801102_15_dialog_content = "확실히 그렇네. 사메야마, 뭐 좋은 생각 있어?",
  ui_story_5080_50801102_16_dialog_content = "뭐 뾰족한 수가 있겠냐. 놈들이 이 안에서 기어 나온 이상, 내가 들어가서 알아보는 수밖에.",
  ui_story_5080_50801102_17_dialog_content = "<size=45>뭐?!</size>",
  ui_story_5080_50801102_18_dialog_content = "사메야마, 정신 차려. 저건 화산이야.",
  ui_story_5080_50801102_19_dialog_content = "난 아주 멀쩡하다고. 그래서 더 가만히 있을 수가 없는 거다.",
  ui_story_5080_50801102_20_dialog_content = "허구한 날 시끄럽게 울어대니 귀찮아 죽겠다고.\n과거의 원수든, 지금의 위협이든 다 좋으니까, 이참에 끝장을 봐야겠어.",
  ui_story_5080_50801102_21_dialog_content = "당신이 왜... 그렇게 필사적으로 나서는 거지?",
  ui_story_5080_50801102_22_dialog_content = "하, 네 입에서 그런 말이 나오다니 별일이군.",
  ui_story_5080_50801102_23_dialog_content = "레디젤 렌치는 누가 뭐래도 「탈영병」들이고, 당신도 그런 조직의 일원이야.",
  ui_story_5080_50801102_24_dialog_content = "당신들은 줄곧 남들을 약탈하면서 살아온 거 아냐?\n어디든 가서 적응하고, 하루하루 되는대로 살아갔을 거잖아.",
  ui_story_5080_50801102_25_dialog_content = "그런데 왜 자기 목숨을 내놓으려고 하는 거냐고.",
  ui_story_5080_50801102_26_dialog_content = "그럼 너부터 대답해 봐라. 넌 일루미나에서 지금까지 뭘 했고, 왜 이 멀고 먼 화산까지 온 거냐.",
  ui_story_5080_50801102_27_dialog_content = "난 「호크아이 소대」의 대장이야! 대원들을 이끌고 40여 차례의 고난도 특수 작전을 수행했어.",
  ui_story_5080_50801102_28_dialog_content = "내가 아닌 다른 사람이 와봤자 더 위험해질 뿐이야.",
  ui_story_5080_50801102_29_dialog_content = "그리고 난 명예를 위해 왔어. 당신들과는 전혀 다르다고.",
  ui_story_5080_50801102_30_dialog_content = "그거 아냐? 여기 있는 플뢰르, 그리고 저 아저씨도 모두 자난성 출신이다.",
  ui_story_5080_50801102_31_dialog_content = "두 사람은 거기서 어떠한 명예도 느끼지 못했고, 오히려 숨 막히는 갑갑함만 있을 뿐이었지.\n그래서 어쩔 수 없이 사막으로 도망쳐 왔던 거다.",
  ui_story_5080_50801102_32_dialog_content = "대체 그놈의 명예가 뭐냔 말이다.",
  ui_story_5080_50801102_33_dialog_content = "명예는...",
  ui_story_5080_50801102_34_dialog_content = "일루미나 아가씨, 말해 봐. 너 정말 「희생」의 의미를 제대로 알긴 하는 거냐?",
  ui_story_5080_50801102_35_dialog_content = "...여명의 빛을 위해, 모든 오로리안의 대의를 해방시키기 위해!\n난 그 어떤 대가도, 목숨조차 아끼지 않을 거야!",
  ui_story_5080_50801102_36_dialog_content = "그 대의를 위해서라면 난 언제든지 희생할 수 있다고!",
  ui_story_5080_50801102_37_dialog_content = "......",
  ui_story_5080_50801102_38_dialog_content = "왜 그런 표정인 거지?",
  ui_story_5080_50801102_39_dialog_content = "넌 그렇게 자신을 속여왔던 거냐.",
  ui_story_5080_50801102_40_dialog_content = "뭐, 됐다. 지금 너한테 말해 봤자 소용없을 것 같으니까.",
  ui_story_5080_50801102_41_dialog_content = "로이, 저 아가씨는 아직 꿈에서 깨질 못했어.",
  ui_story_5080_50801102_42_dialog_content = "당신...!",
  ui_story_5080_50801102_43_dialog_content = "이제 그만 비켜 봐. 난 집안의 바퀴벌레 소굴을 치워야겠으니까, 괜한 참견은 접어두라고.",
  ui_story_5080_50801102_44_dialog_content = "어이, 사메야마! 누가 혼자서 치우래? 우릴 잊으면 안 되지.",
  ui_story_5080_50801102_45_dialog_content = "너희들, 위험하니까 같이 올라서지 마.",
  ui_story_5080_50801102_46_dialog_content = "그건 너도 마찬가지잖아! 이 멍청아!",
  ui_story_5080_50801102_47_dialog_content = "같이 화산으로 뛰어내리려고? 현명하지 못한 선택 같은걸.",
  ui_story_5080_50801102_48_dialog_content = "다들 준비해... 으악!",
  ui_story_5080_50801102_49_dialog_content = "지진이야, 조심해!",
  ui_story_5080_50801102_50_dialog_content = "<color=#e8d9bb>갑작스러운 지진 때문에 분화구 옆에 서 있던 일행은 화산 안으로 떨어지고 말았다.</color>",
  ui_story_5080_50801102_51_dialog_content = "오빠──!",
  ui_story_5080_50801102_52_dialog_content = "이브! 너희들! 내가 간다!!!",
  ui_story_5080_50801102_53_dialog_content = "내 눈앞에서 다시는── 그 누구도 데려가지 못해!",
  ui_story_5080_50801102_54_dialog_content = "<color=#e8d9bb>사메야마는 포탄처럼 날아들었고, 괴력을 발휘해 사람들을 안전한 곳으로 다시 집어 던졌다.</color>",
  ui_story_5080_50801102_55_dialog_content = "<color=#e8d9bb>그가 날아오는 모습이 보이자 당신은 왠지 모르게 마음이 놓였다.</color>",
  ui_story_5080_50801102_56_dialog_content = "PlayerName, 내 손 잡아!",
  ui_story_5080_50801102_57_dialog_content = "잠깐만! 사메야마! 이 밑은 용암이야! 당신은 어쩌려고!",
  ui_story_5080_50801102_58_dialog_content = "그딴 건 신경 끄고 올라가기나 해!",
  ui_story_5080_50801102_59_dialog_content = "애송이── 죽지 마라.",
  ui_story_5080_50801102_60_dialog_content = "<size=50>사메야마!!!</size>",
  ui_story_5080_50801201_1_dialog_content = "임무를 순조롭게 마쳤군. 「호크아이」가 큰 공을 세웠다!",
  ui_story_5080_50801201_2_dialog_content = "수고했다, 레이첼. 일루미나는 너희들의 희생을 기억할 거다.",
  ui_story_5080_50801201_3_dialog_content = "병사, 한 발 앞으로! 대원수님께서 친히 명예 훈장을 수여하실 것이다!",
  ui_story_5080_50801201_4_dialog_content = "구조에 최선을 다했지만... 미안하다, 레이첼. 줄 수 있는 건 이것뿐이다.\n너희들의 희생에 감사와 경의를 표한다.",
  ui_story_5080_50801201_5_dialog_content = "......!",
  ui_story_5080_50801201_6_dialog_content = "무거워...",
  ui_story_5080_50801201_7_dialog_content = "으음?",
  ui_story_5080_50801201_8_dialog_content = "저들이... 여기... 제 손 위에 있습니다... 너무 무겁습니다...",
  ui_story_5080_50801201_9_dialog_content = "제 대원들이 모두... 저 한 사람을 위해... 희생...했습니다...... 전...",
  ui_story_5080_50801201_10_dialog_content = "...병사가 혼절한다! 어서 의무병을 불러라!",
  ui_story_5080_50801201_11_dialog_content = "가슴이 아파... 다치지 않았는데... 고통이 멈추질 않아... 고모...",
  ui_story_5080_50801201_12_dialog_content = "소대장님... 최선을 다해 임무를 완수해 주셔서 감사합니다...",
  ui_story_5080_50801201_13_dialog_content = "덕분에 우리 아이가 「실패자」로 남지 않을 수 있었습니다.",
  ui_story_5080_50801201_14_dialog_content = "저들은 모두 영웅으로 편히 잠들었을 겁니다.",
  ui_story_5080_50801201_15_dialog_content = "(아니야...)",
  ui_story_5080_50801201_16_dialog_content = "괴로워, 고모... 임무를 분명히 완수했는데도... 너무 괴로워...",
  ui_story_5080_50801201_17_dialog_content = "우리 레이첼... 착하지, 울지 마...",
  ui_story_5080_50801201_18_dialog_content = "내 잘못인데, 분명히 내가 잘못한 건데 어째서 저 사람들은 나한테 고맙다고 하는 거냐고...",
  ui_story_5080_50801201_19_dialog_content = "넌 그들의 마지막 존엄을 지켜준 거야.",
  ui_story_5080_50801201_20_dialog_content = "하지만... 다들 무사히 돌아와서 가족과 함께해야 하는 건데...",
  ui_story_5080_50801201_21_dialog_content = "레이첼, 날 봐. 네가 감당할 수 있을까? 그저 대원들을 무사히 집에 보내기 위해,\n모두를 탈영병으로 전락시킬 수 있겠어?",
  ui_story_5080_50801201_22_dialog_content = "나...난... 잘 모르겠어... 정말...",
  ui_story_5080_50801201_23_dialog_content = "어떻게 된 겁니까, 레이첼. 벌써 여섯 번째 임무 실패입니다.",
  ui_story_5080_50801201_24_dialog_content = "휴식은 충분히 취했을 텐데요. 어째서 그런 겁니까?",
  ui_story_5080_50801201_25_dialog_content = "죄송합니다... 모두 제 책임입니다... 그러니 다른 대원들은 질책하지 말아 주세요...",
  ui_story_5080_50801201_26_dialog_content = "대원들은 모두 당신에 대한 불만을 토로했습니다.\n당신이 저들의 이름도, 심지어 얼굴도 기억하지 못한다고 하더군요. 대체 무슨 일입니까?",
  ui_story_5080_50801201_27_dialog_content = "정말... 죄송합니다...",
  ui_story_5080_50801201_28_dialog_content = "당분간 임무를 맡지 않는 게 좋겠습니다. 휴가를 배정해 주겠습니다.",
  ui_story_5080_50801201_29_dialog_content = "정말 죄송합니다... 군단장님...",
  ui_story_5080_50801201_30_dialog_content = "그레이윙의 이름은 「루이」, 북쪽 지역에서 태어나서 줄곧 사막에 가 보고 싶어 했어.",
  ui_story_5080_50801201_31_dialog_content = "언젠가 북방에 가서, 거기서 자라는 흰 나무로 화이트구스에게 피리를 만들어 주고 싶다고 했었지.",
  ui_story_5080_50801201_32_dialog_content = "화이트구스의 이름은 「메리」, 줄곧 악기를 배우고 싶어 했지만,\n늘 말로만 그쳤지 실제로 배우진 못했어.",
  ui_story_5080_50801201_33_dialog_content = "내 생일에 멋진 곡을 들려주겠다고 했었지만, 벌써 몇 년째 미루고 있어.",
  ui_story_5080_50801201_34_dialog_content = "참, 그리고 레드팔콘과 그린아울도, 모두...",
  ui_story_5080_50801201_35_dialog_content = "이젠 이 인식표가 되어 영원히 내 목에 걸려 있어.",
  ui_story_5080_50801201_36_dialog_content = "「네가 감당할 수 있을까? 그저 대원들을 무사히 집에 보내기 위해,\n모두를 탈영병으로 전락시킬 수 있겠어?」",
  ui_story_5080_50801201_37_dialog_content = "PlayerName!",
  ui_story_5080_50801201_38_dialog_content = "......!",
  ui_story_5080_50801201_39_dialog_content = "바이스, 여기야! 대장, 플뢰르, 제타, 다들 괜찮아?",
  ui_story_5080_50801201_40_dialog_content = "난 괜찮아.",
  ui_story_5080_50801201_41_dialog_content = "다행이야, PlayerName도 무사해.",
  ui_story_5080_50801201_42_dialog_content = "분화구가 무너진 것 같아. 다른 사람들은?",
  ui_story_5080_50801201_43_dialog_content = "우리랑 다른 층에 있는 거 같아. 후후, 이건 마왕성 바로 앞에서 흔히 펼쳐지는 전개라구!",
  ui_story_5080_50801201_44_dialog_content = "레디젤의 두목이 우릴 위해서 용암 속으로 뛰어들다니...",
  ui_story_5080_50801201_45_dialog_content = "아래로 내려가자. 사메야마를 찾아야 해.",
  ui_story_5080_50801201_46_dialog_content = "사방이 용암이네... 어쩔 수 없지, 열심히 피해서 가는 수밖에.",
  ui_story_5080_50801201_47_dialog_content = "임무가 우선이야. 불필요한 위험 구역은 피해야만 해.",
  ui_story_5080_50801201_48_dialog_content = "사메야마가 우릴 구했으니까, 이번엔 우리가 구해줄 차례야.\n따라와. 내가 감응할 수 있을 것 같으니까.",
  ui_story_5080_50801201_49_dialog_content = "아이테르! 방금 그 대사 너무 멋있는 거 아냐?! 그럼 내 분량이 줄어들잖아! 나도 갈래!",
  ui_story_5080_50801201_50_dialog_content = "대장, 나도 구하러 가고 싶어.",
  ui_story_5080_50801201_51_dialog_content = "...팔을 다쳤잖아. 아까 떨어졌을 때 다친 거야?",
  ui_story_5080_50801201_52_dialog_content = "어? 진짜네... 피가 나잖아.",
  ui_story_5080_50801201_53_dialog_content = "이거 가져가서 지혈부터 해. 네 지금 상태로는 선두에서 호위 임무를 수행할 수 없어.\n내 뒤에서 따라 와.",
  ui_story_5080_50801201_54_dialog_content = "어?",
  ui_story_5080_50801201_55_dialog_content = "내려가자, 「타깃」이 아래에 있을지도 몰라.",
  ui_story_5080_50801201_56_dialog_content = "응!",
  ui_story_5080_50801201_57_dialog_content = "온통 암귀투성이야... 놈들은 어떻게 이런 활화산에서 살 수 있는 거지?",
  ui_story_5080_50801201_58_dialog_content = "암귀도 생물이니까, 원래라면 이렇게 위험한 곳은 피하는 게 정상인데 말이야.",
  ui_story_5080_50801201_59_dialog_content = "사관학교에서 배운 거랑 전혀 달라.",
  ui_story_5080_50801201_60_dialog_content = "...일루미나는 이미 오래전부터 이런 유형의 암귀를 알고 있었어.",
  ui_story_5080_50801201_61_dialog_content = "뭐? 근데 왜 난 한 번도 못 들어본 거지?",
  ui_story_5080_50801201_62_dialog_content = "그때, 위원회에선 우리 고모가 속한 소대에 내 이번 임무와 동일한 조사 임무를 맡겼어.",
  ui_story_5080_50801201_63_dialog_content = "그 소대의 대장이 바로 「레디젤 렌치」를 세운 사람이었고.",
  ui_story_5080_50801201_64_dialog_content = "네 고모가 「프리버드」에서 복무했던 건 알고 있겠지.",
  ui_story_5080_50801201_65_dialog_content = "네 고모의 마지막 임무는 위원회가 직접 배정한 중요 임무였다.\n하지만 실패하고 돌아왔을 뿐만 아니라, 네 고모가 따르던 소대장은 훗날 일루미나를 배신했다.",
  ui_story_5080_50801201_66_dialog_content = "모두 「프리버드 소대가 목숨을 부지하려고 독단적으로 임무를 포기했다」고들 말했다.\n넌 그 일을 어떻게 생각하는지 듣고 싶군.",
  ui_story_5080_50801201_67_dialog_content = "송구합니다! 대원수님, 저는 제 고모의 실패를... 무척 부끄럽게 생각하고 있습니다.",
  ui_story_5080_50801201_68_dialog_content = "하지만 제 고모는 충성스러운 군인입니다!\n그 소대장의 독단적인 결정에 연루되었을 뿐입니다!",
  ui_story_5080_50801201_69_dialog_content = "부디 가문의 명예를 되찾을 수 있도록 기회를 주셨으면 합니다.",
  ui_story_5080_50801201_70_dialog_content = "하지만 그런 「부끄러운 일」이 벌어지지 않았다면, 네 고모는 영웅으로 눈을 감았겠지.",
  ui_story_5080_50801201_71_dialog_content = "네게는 그편이 더 받아들이기 쉬운 일인 건가?",
  ui_story_5080_50801201_72_dialog_content = "그, 그건... 저는...",
  ui_story_5080_50801201_73_dialog_content = "하하하! 그냥 물어봤을 뿐이다.",
  ui_story_5080_50801201_74_dialog_content = "이제 널 찾아온 이유를 말해주지. 네게 임무를 하나 주겠다.",
  ui_story_5080_50801201_75_dialog_content = "네 고모의 마지막 임무, 그게 바로 네가 이번에 맡을 임무의 내용이다.",
  ui_story_5080_50801201_76_dialog_content = "...네?",
  ui_story_5080_50801201_77_dialog_content = "당시 위원회는 프리버드에게 관측된 암귀를 반드시 생포하라는 지시를 내렸다.",
  ui_story_5080_50801201_78_dialog_content = "실험을 위해 살아있는 암귀가 필요했거든.",
  ui_story_5080_50801201_79_dialog_content = "난 그런 연구가 옳은지 그른지에 대해서는 회의적이다. 따라서 네게 강요할 생각은 없다.",
  ui_story_5080_50801201_80_dialog_content = "전...",
  ui_story_5080_50801201_81_dialog_content = "물론 그 암귀를 생포한다면 네 고모의 아쉬움을 풀어줄 순 있겠지.",
  ui_story_5080_50801201_82_dialog_content = "하지만 어떻게 할지는 너 스스로 결정하면 된다.",
  ui_story_5080_50801201_83_dialog_content = "그리고 네 임무를 위해 내가 특별한 대원을 선발했다.\n「바이스」라는 이름을 너도 들어본 적 있겠지.",
  ui_story_5080_50801201_84_dialog_content = "...아이테르와 함께 활동하는 그 젊은 소대장 말씀이십니까?\n하지만 이미 오랫동안 아이테르를 따라 움직였을 텐데요...",
  ui_story_5080_50801201_85_dialog_content = "그렇다면 동료가 가는 곳을 파트너인 아이테르가 안 갈 수는 없겠지.",
  ui_story_5080_50801201_86_dialog_content = "그 둘은 참 불가사의한 녀석들이지.\n그리고 너 역시 이번 임무에선 네가 찾는 답을 얻을 수 있을 거다.",
  ui_story_5080_50801201_87_dialog_content = "이건 히이로가 내게 상세하게 요청한 일이기도 하다. 넌 좋은 상관을 뒀다, 레이첼.",
  ui_story_5080_50801201_88_dialog_content = "감사합니다, 대원수님. 절 믿고 기회를 주셔서 정말 감사합니다!",
  ui_story_5080_50801201_89_dialog_content = "그럼 지금 즉시 준비하겠습니다!",
  ui_story_5080_50801201_90_dialog_content = "잠깐, 레이첼.",
  ui_story_5080_50801201_91_dialog_content = "안심하십시오. 반드시 임무를 완수하겠습니다!",
  ui_story_5080_50801201_92_dialog_content = "한 가지 묻고 싶은 게 있다.",
  ui_story_5080_50801201_93_dialog_content = "지금의 넌 아직 마음속 여명의 빛을 찾을 수 있나?",
  ui_story_5080_50801201_94_dialog_content = "...대원수님께서 걱정하시는 점이 무엇인지는 알고 있습니다.",
  ui_story_5080_50801201_95_dialog_content = "전 지휘 실수로 대원들을 사지로 몰아넣었고, 지금은 다른 대원들과\n잘 어울리지 못하고 있습니다...",
  ui_story_5080_50801201_96_dialog_content = "하지만 걱정 마십시오. 똑같은 잘못을 반복하진 않을 겁니다.",
  ui_story_5080_50801201_97_dialog_content = "그걸 말하려던 게 아니다만... 뭐, 됐다. 그만 가보도록.",
  ui_story_5080_50801201_98_dialog_content = "녀석들이라면 분명히 네 생각을 바꿔놓을 수 있을 테니 말이야.",
  ui_story_5080_50801201_99_dialog_content = "소문이 자자한 콤비고, 힘을 가진 사람들이니, 분명히 약하지 않겠죠.",
  ui_story_5080_50801201_100_dialog_content = "더는 다른 대원들과 엮이지 않고, 그 누구도 연루되지 않도록... 각별히 주의하겠습니다.",
  ui_story_5080_50801201_101_dialog_content = "고모, 좋은 소식이 있어.",
  ui_story_5080_50801201_102_dialog_content = "나, 다시 임무를 수행할 수 있게 됐어.",
  ui_story_5080_50801201_103_dialog_content = "그래? 정말 잘됐네. 그런데 괜찮겠어? 너무 무리하진 마.",
  ui_story_5080_50801201_104_dialog_content = "난 괜찮아, 고모. 그리고 이번엔 어쩌면 그때 일을 조사할 기회가 생길 것 같아.",
  ui_story_5080_50801201_105_dialog_content = "고모의 억울함을 내가 꼭 풀어줄게.",
  ui_story_5080_50801201_106_dialog_content = "그럴 거 없어, 레이첼.",
  ui_story_5080_50801201_107_dialog_content = "난 한 번도 그때 일을 후회한 적 없어. 살아남을 수 있어서 대장에겐 진심으로 감사하고 있고.",
  ui_story_5080_50801201_108_dialog_content = "대장이 아니었으면 널 다시 볼 수도 없었을 테니까.",
  ui_story_5080_50801201_109_dialog_content = "고모는 왜 아직도 그 사람 편을 드는 거야...? 그 사람은 일루미나를 떠난 사람이잖아.",
  ui_story_5080_50801201_110_dialog_content = "대장은 탈영병이 절대 아냐, 배신자는 더더욱 아니고!",
  ui_story_5080_50801201_111_dialog_content = "분명히 우리가 모르는 이유가 있을 거야. 그래도 난 대장을 믿어!",
  ui_story_5080_50801201_112_dialog_content = "그 사람 때문에 고모와 동료들이 전부 「배신자」가 됐어!\n지금까지도 돌아오지 않고 있는데, 고모는 왜 계속 그 사람을 믿는 거야?!",
  ui_story_5080_50801201_113_dialog_content = "...내 목숨, 그리고 동료들의 목숨 모두 대장이 혼자 그 「용암의 지옥」에서 꺼내줬던 거니까!",
  ui_story_5080_50801201_114_dialog_content = "대장이야말로 진짜 영웅이야!",
  ui_story_5080_50801201_115_dialog_content = "난 그저... 고모가 쓴 억울한 누명을 벗겨주고 싶었을 뿐이야...",
  ui_story_5080_50801201_116_dialog_content = "우리 가문은 아무 잘못도 없어...",
  ui_story_5080_50801201_117_dialog_content = "레이첼, 어디 가?",
  ui_story_5080_50801201_118_dialog_content = "돌아와! 레이첼! 거긴 네가 절대 가서는 안 되는 곳이야!",
  ui_story_5080_50801201_119_dialog_content = "레이첼──",
  ui_story_5080_50801201_120_dialog_content = "비록 프리버드의 임무는 실패였지만, 그래도 적지 않은 정보를 밝혀냈어.",
  ui_story_5080_50801201_121_dialog_content = "프리버드가 남긴 자료에 따르면, 당시 「그 암귀」는 지맥 에너지를 빨아들여\n생명을 유지하는 변종이었어.",
  ui_story_5080_50801201_122_dialog_content = "그리고 그런 암귀들이 가득한 이 화산은 줄곧 활동 상태였지만,\n정작 폭발 임계점엔 도달하지 않았지.",
  ui_story_5080_50801201_123_dialog_content = "아마 그건 암귀들이 화산의 에너지를 빨아들이고 있었기 때문일 거야.",
  ui_story_5080_50801201_124_dialog_content = "레디젤 사막의 화산이 불안정한 건 불안정한 지맥 에너지 때문이야.",
  ui_story_5080_50801201_125_dialog_content = "저 암귀의 활동은 지맥 에너지의 불균형 상태를 초래하지만,\n한편으론 놈들의 「먹성」이 화산의 폭발을 계속 억제했어.",
  ui_story_5080_50801201_126_dialog_content = "그렇게 보면 저 암귀들은 줄곧 땅속에서 「번식」했을 가능성이 커.",
  ui_story_5080_50801201_127_dialog_content = "그 당시 관측된 암귀 한 마리가 이제는 한 무리로 변해버린 거지.",
  ui_story_5080_50801201_128_dialog_content = "심지어 그 끔찍한 특성도 같이 이어져 내려오고 있잖아.",
  ui_story_5080_50801201_129_dialog_content = "아니지, 그럼 우리가 놈들한테 감사라도 해야 하는 거야?",
  ui_story_5080_50801201_130_dialog_content = "「고마워, 너희 덕분에 화산이 터지지 않았어」... 생각하니까 열받는데?",
  ui_story_5080_50801201_131_dialog_content = "하지만 저 암귀들만 아니었으면 지맥 에너지가 이렇게 불안정할 일도 없고,\n환경도 지금처럼 척박하게 변하진 않았을걸.",
  ui_story_5080_50801201_132_dialog_content = "운전할 때 툭하면 나는 지진도 없었을 거구!",
  ui_story_5080_50801201_133_dialog_content = "그렇게 생각하니까 궁금하네. 사막의 황폐화는 저 녀석들이랑 대체 어떤 관계가 있는 걸까?",
  ui_story_5080_50801201_134_dialog_content = "아무튼 암귀가 화산의 힘을 <color=#FFB400>흡수</color>할 수 있다니... 정말 말도 안 되는 일이잖아.",
  ui_story_5080_50801201_135_dialog_content = "만약 과거의 <color=#FFB400>그 암귀</color>가 여전히 존재한다면, 이렇게 오랫동안 살아온 녀석은\n대체 얼마나 강한 힘을 갖고 있을까?",
  ui_story_5080_50801201_136_dialog_content = "더는 살려둘 수 없어...",
  ui_story_5080_50801201_137_dialog_content = "절대로 계속 살아가게 둬선 안 돼...",
  ui_story_5080_50801201_138_dialog_content = "그럼 계속 가자! 사메야마를 찾아서 더 깊은 곳으로!",
  ui_story_5080_50801202_1_dialog_content = "으... 여긴 너무 좁잖아.",
  ui_story_5080_50801202_2_dialog_content = "게다가 바로 옆에는 용암이야. 조심해!",
  ui_story_5080_50801202_3_dialog_content = "해칠링 2호, 캔디걸! 둘 다 내 뒤로 피해!",
  ui_story_5080_50801202_4_dialog_content = "호크헌터 1호, 2호, 3호! 화력 전개!",
  ui_story_5080_50801202_5_dialog_content = "대장, 무리하지 마! 암귀들의 방어력이 너무 강해!",
  ui_story_5080_50801202_6_dialog_content = "그만 떠들고 공격에 집중해!",
  ui_story_5080_50801202_7_dialog_content = "겁먹을 거 없어! 제타의 달콤한 폭탄이 있으니까 곧 끝날 거야!",
  ui_story_5080_50801202_8_dialog_content = "크오오──!",
  ui_story_5080_50801202_9_dialog_content = "대장!",
  ui_story_5080_50801202_10_dialog_content = "별거 아냐, 뒤에서 나오지 마.",
  ui_story_5080_50801202_11_dialog_content = "놈이 계속 공격해 오고 있어!",
  ui_story_5080_50801202_12_dialog_content = "호크헌터 1호, 돌아와서 방어해!",
  ui_story_5080_50801202_13_dialog_content = "이런, 늦은 건가...",
  ui_story_5080_50801202_14_dialog_content = "용사 출동!",
  ui_story_5080_50801202_15_dialog_content = "크오오──!",
  ui_story_5080_50801202_16_dialog_content = "제타?!",
  ui_story_5080_50801202_17_dialog_content = "캔디걸!!!",
  ui_story_5080_50801202_18_dialog_content = "플뢰르! 강제 감응으로 제압했어! 지금이야!",
  ui_story_5080_50801202_19_dialog_content = "저리── 꺼져!",
  ui_story_5080_50801202_20_dialog_content = "용암에 빠트렸나?",
  ui_story_5080_50801202_21_dialog_content = "크오오오!",
  ui_story_5080_50801202_22_dialog_content = "용암에 파묻혔어... 저 암귀는 용암을 견딜 수 있는 거 아니었어...?",
  ui_story_5080_50801202_23_dialog_content = "캔디걸! 괜찮아?!",
  ui_story_5080_50801202_24_dialog_content = "헤헤~ 어때? 호크 슈터... 레디젤 렌치 사람도 사실 나쁘진 않지...?",
  ui_story_5080_50801202_25_dialog_content = "왜... 나 때문에...",
  ui_story_5080_50801202_26_dialog_content = "왜냐면 넌 제타의 「오래전 헤어진 언니」잖아...",
  ui_story_5080_50801202_27_dialog_content = "캔디걸? 캔디걸!",
  ui_story_5080_50801202_28_dialog_content = "(이런, 응급 키트가 없어. 제타의 상처를 어떻게 해야... 어라?)",
  ui_story_5080_50801202_29_dialog_content = "내가 또 잘못 지휘한 거야...? 또, 누군가가 나 때문에...",
  ui_story_5080_50801202_30_dialog_content = "난 분명히 지키려고 했는데...",
  ui_story_5080_50801202_31_dialog_content = "왜 또 이런 잘못을 저지른 거야... 내가 너무 오만했던 거야?",
  ui_story_5080_50801202_32_dialog_content = "자책할 거 없어. 아직 구할 수 있으니까! 제타를 내 등에 업혀, 당장 여기서 나가자고.",
  ui_story_5080_50801202_33_dialog_content = "제타, 정신 차려! 내가 널 여기서 꼭 데리고 나갈 테니까. 조금만 버텨!",
  ui_story_5080_50801202_34_dialog_content = "「지난 잘못을 뉘우치는 마인 엔지니어」... 제타의 여정은 여기까지인가 봐...\n앞으로는 날 잊어줘...",
  ui_story_5080_50801202_35_dialog_content = "농담은 집어치워!",
  ui_story_5080_50801202_36_dialog_content = "정신 차려, 나한테 새 공기밸브 주문한 거 잊었어?",
  ui_story_5080_50801202_37_dialog_content = "조금만 더 시간을 줘! 업그레이드된 더블 8기통 엔진에 대한 아이디어가 떠오를 것 같으니까!\n운전해 보고 싶지 않아?",
  ui_story_5080_50801202_38_dialog_content = "응?!",
  ui_story_5080_50801202_39_dialog_content = "여기서 나갈 때까지 버텨주면, 앞으로는 네 차만 개조해 주고,\n아주르 부탁은 거절할게. 어때?",
  ui_story_5080_50801202_40_dialog_content = "그리고 너 아주르의 차량 데이터를 줄곧 궁금해했었지? 내가 알아봐 줄게!",
  ui_story_5080_50801202_41_dialog_content = "같이 로이를 찾아가서 우리 팀에 들어오라고 설득하는 거야... 제타, 정신 차려.",
  ui_story_5080_50801202_42_dialog_content = "아주르를 골탕 먹이는 것도 나중에 로이랑 도와줄게. 진짜야!",
  ui_story_5080_50801202_43_dialog_content = "그, 그래! 캔디걸, 나도 도와줄게. 난 사관학교에서 기계공학을 전공했거든.",
  ui_story_5080_50801202_44_dialog_content = "그치만 내 이름도 안 불러주고...",
  ui_story_5080_50801202_45_dialog_content = "나도 차 개조하는 거 도와줄 수 있어.\n우리 일루미나의 과학 기술이 얼마나 대단한지 너도 알잖아.",
  ui_story_5080_50801202_46_dialog_content = "일루미나 스타일의 공주님 차를 몰아보고 싶어?",
  ui_story_5080_50801202_47_dialog_content = "뭐?! 좋아! 지금 보고 싶어. 설계도 있어?",
  ui_story_5080_50801202_48_dialog_content = "제타? 너... 괜찮은 거야?",
  ui_story_5080_50801202_49_dialog_content = "어, 그게... 헤헤, 왠지 등에 있는 허니 헌터가 공격을 막아준 거 같아!\n역시 제타는 타고 난 여주인공이라니까~",
  ui_story_5080_50801202_50_dialog_content = "제타 님, 완전 부활!",
  ui_story_5080_50801202_51_dialog_content = "너...",
  ui_story_5080_50801202_52_dialog_content = "이게 바로 황야의 아이, 용사 제타의 이야기라구! 난 그렇게 쉽게 쓰러지지 않아... 으윽...",
  ui_story_5080_50801202_53_dialog_content = "속이려는 게 아냐. 그냥 플뢰르 등에 한번 업혀보고 싶었을 뿐이라구.",
  ui_story_5080_50801202_54_dialog_content = "깜짝 놀랐잖아... 이런 상황에서도 장난이라니, 너 정말... 휴, 괜찮으면 됐어.",
  ui_story_5080_50801202_55_dialog_content = "(처음 눈치챘을 땐 뭐라고 말을 꺼내야 할지 막막했는데, 장난이 오래 안 가서 다행이네...)",
  ui_story_5080_50801202_56_dialog_content = "그치만 제타의 등이 확실히 아프긴 해.",
  ui_story_5080_50801202_57_dialog_content = "호크 슈터, 표정이 영 안 좋은데... 나 원망하는 건 아니지...?",
  ui_story_5080_50801202_58_dialog_content = "...어?! 너 얼굴이 새카맣잖아! 흑화된 모습이 꼭 무슨 공포 영화에서 나온 것 같다구!",
  ui_story_5080_50801202_59_dialog_content = "싫어──!",
  ui_story_5080_50801202_60_dialog_content = "으응?!",
  ui_story_5080_50801202_61_dialog_content = "제타... 무사해서... 정말 다행이야.",
  ui_story_5080_50801202_62_dialog_content = "야! 용사의 머리를 함부로 만지지 마! 그렇게 애교 부려도 안 되는 건... 어?",
  ui_story_5080_50801202_63_dialog_content = "너, 너 지금 제타 이름 불렀어?!",
  ui_story_5080_50801202_64_dialog_content = "다시는 그런 장난으로 사람 놀라게 하지 마...",
  ui_story_5080_50801202_65_dialog_content = "대장...",
  ui_story_5080_50801202_66_dialog_content = "후후, 제타는 여주인공인데, 매번 똑같은 모습만 보여줄 순 없잖아? 헤헤.",
  ui_story_5080_50801202_67_dialog_content = "좋아... 별일 없으니까, 그럼 용암 지대를 최대한 빨리 통과하자. 계속 전진!",
  ui_story_5080_50801202_68_dialog_content = "아이테르 1호, 해칠링 2호, 대오를 유지해!",
  ui_story_5080_50801202_69_dialog_content = "뭐야, 왜 또 코드명이냐구...",
  ui_story_5080_50801202_70_dialog_content = "그런 건 나중에 따지고 일단 가자.",
  ui_story_5080_50801202_71_dialog_content = "임무는 아직 끝나지 않았어. 이동해!",
  ui_story_5080_50801202_72_dialog_content = "(금방 다시 차가운 가면을 썼지만, 이젠 확실히 안 어울리거든. 레이첼...)",
  ui_story_5080_50801202_73_dialog_content = "가자, 바이스. 왠지 이번 일도 이제 거의 다 끝났다는 예감이 들거든.",
  ui_story_5080_50801202_74_dialog_content = "서둘러! 위험 지역에서 멀리 벗어나야... 으윽...",
  ui_story_5080_50801202_75_dialog_content = "왜 그래? 괜찮아?",
  ui_story_5080_50801202_76_dialog_content = "아무것도 아냐. 가, 어서!",
  ui_story_5080_50801202_77_dialog_content = "호크헌터 1호, 정찰 모드로 소대를 인솔해. 대원들은 호크헌터 1호를 따라가!",
  ui_story_5080_50801202_78_dialog_content = "(...사람들의 목숨이 아직 내 손에 달려 있어... 그러니까... 쓰러지면... 안 돼...)",
  ui_story_5080_50801301_1_dialog_content = "캬아아악──!",
  ui_story_5080_50801301_2_dialog_content = "놈들이 점점 늘어나고 있어.",
  ui_story_5080_50801301_3_dialog_content = "적의와 복수심으로 가득해.",
  ui_story_5080_50801301_4_dialog_content = "예리아, 얼른 가. 난 괜찮으니까.",
  ui_story_5080_50801301_5_dialog_content = "무슨 소리야? 눈도 불편한 널 두고 내가 어떻게 가겠어.",
  ui_story_5080_50801301_6_dialog_content = "당신 능력은... 여기서는 적합하지 않아.",
  ui_story_5080_50801301_7_dialog_content = "아무리 그래도 난 장로잖아.",
  ui_story_5080_50801301_8_dialog_content = "바닥이 가라앉고 있어... 용암에 빠지고 말 거야.",
  ui_story_5080_50801301_9_dialog_content = "도엔, 좀 더 왼쪽으로! 그리고 내 손 잡아!",
  ui_story_5080_50801301_10_dialog_content = "어서 가, 예리아.",
  ui_story_5080_50801301_11_dialog_content = "내가 잡았어. 그러니까 손 놓으면 안 돼, 도엔.",
  ui_story_5080_50801301_12_dialog_content = "암귀들이 몰려올 거야.",
  ui_story_5080_50801301_13_dialog_content = "지금 그런 거 따질 시간 없어.",
  ui_story_5080_50801301_14_dialog_content = "어째서? 예리아, 당신은 살아야지.",
  ui_story_5080_50801301_15_dialog_content = "네가 죽어도 다들 슬퍼할 거야.",
  ui_story_5080_50801301_16_dialog_content = "이브가 우는 얼굴, 상상할 수 있겠어?",
  ui_story_5080_50801301_17_dialog_content = "네 얼굴에 바짝 붙어서 매달려 울 거라고!",
  ui_story_5080_50801301_18_dialog_content = "......",
  ui_story_5080_50801301_19_dialog_content = "역시 「연줄」의 힘은 참 강하다니까. 봐, 이렇게 널 붙잡았잖아?",
  ui_story_5080_50801301_20_dialog_content = "이미 사람과 사람의 관계가 이렇게 맺어진 이상, 나도 쉽게 끊어지도록 내버려둘 순 없어.",
  ui_story_5080_50801301_21_dialog_content = "예리아... 위험해!",
  ui_story_5080_50801301_22_dialog_content = "아탈, 난 최선을 다했어...",
  ui_story_5080_50801301_23_dialog_content = "<color=#FFB400>속사!</color>",
  ui_story_5080_50801301_24_dialog_content = "따라잡았어. 제타, 폭탄으로 놈들을 막아!",
  ui_story_5080_50801301_25_dialog_content = "헤헤, 달콤한 궁극 폭탄 등장!",
  ui_story_5080_50801301_26_dialog_content = "예리아 씨, 제가 도울게요! 플뢰르, 도엔을 끌어올려줘...",
  ui_story_5080_50801301_27_dialog_content = "<color=#FFB400>얼음의 꽃!</color>",
  ui_story_5080_50801301_28_dialog_content = "자, 어서 그 「다리」를 타고 건너와!",
  ui_story_5080_50801301_29_dialog_content = "카렌? 이브까지?",
  ui_story_5080_50801301_30_dialog_content = "도엔! 내가 도와줄게!",
  ui_story_5080_50801301_31_dialog_content = "공주님, 정말 큰 도움이 됐어.",
  ui_story_5080_50801301_32_dialog_content = "천만에, 당신도 자기 인연을 지키기 위해 노력 중이잖아?",
  ui_story_5080_50801301_33_dialog_content = "따라 와. 도엔, 내 손 놓지 말고!",
  ui_story_5080_50801301_34_dialog_content = "예리아... 손이...",
  ui_story_5080_50801301_35_dialog_content = "드디어 모였네, 카렌. 너희도 괜찮은 거지?",
  ui_story_5080_50801301_36_dialog_content = "응, 하지만 여기 용암은 너무 위험해. 여기서 오래 싸울 순 없어.",
  ui_story_5080_50801301_37_dialog_content = "맹금류 아가씨, 공주님, 제타를 데리고 여기서 얼른 나가.",
  ui_story_5080_50801301_38_dialog_content = "아이테르 군, 그럼 감응 능력으로 우릴 사메야마에게 데려다줘.",
  ui_story_5080_50801301_39_dialog_content = "당신도 가려고?",
  ui_story_5080_50801301_40_dialog_content = "후후, 일이 이렇게 됐는데 버려둘 순 없잖아.",
  ui_story_5080_50801301_41_dialog_content = "제타도 갈 거야! 제타도 같이 광전사를 구할 거라구!",
  ui_story_5080_50801301_42_dialog_content = "나도 모른 척할 순 없어.",
  ui_story_5080_50801301_43_dialog_content = "너희도 하필 이럴 때 고집쟁이가 돼 버렸구나.",
  ui_story_5080_50801301_44_dialog_content = "그럼 계속 들어가 보자.",
  ui_story_5080_50801301_45_dialog_content = "대장?",
  ui_story_5080_50801301_46_dialog_content = "임무는 아직 안 끝났어. 더 많은 정보를 수집해야 해...\n겸사겸사 레디젤 우두머리를 구하는 것 정도는 괜찮겠지.",
  ui_story_5080_50801301_47_dialog_content = "「레디젤 엔지니어」, 공구 좀 빌려줘. 그리고 해칠링 2호, 네 무기 이리 줘.",
  ui_story_5080_50801301_48_dialog_content = "어? 나?",
  ui_story_5080_50801301_49_dialog_content = "됐어, 네 무기를 개조했어. 조금 어색할 수 있겠지만,\n부상을 입은 상태에선 이게 더 나을 거야.",
  ui_story_5080_50801301_50_dialog_content = "호크헌터 1호, 2호, 3호! 돌아와!",
  ui_story_5080_50801301_51_dialog_content = "...호크헌터 1호와 3호가 파손됐어. 지금부터는 호크헌터 2호가 선두에 서.",
  ui_story_5080_50801301_52_dialog_content = "준비는 끝났어. 이제 임무를 계속하자.",
  ui_story_5080_50801301_53_dialog_content = "촉감이 훨씬 좋아졌어. 활시위도 더 유연해졌고...",
  ui_story_5080_50801301_54_dialog_content = "대장은 내 전투 습관까지도 기억하고 있었어.\n저렇게 다정한 사람인데, 대체 왜 일부러 우릴 멀리하는 걸까?",
  ui_story_5080_50801301_55_dialog_content = "대장이 된 자라면 임무를 완수해야 할 뿐만 아니라 대원의 생명도 지켜야 하니까.",
  ui_story_5080_50801301_56_dialog_content = "자신을 위해 희생하지 않도록, 대원들이 자신에게 호감을 갖지 못하게 하는 게\n레이첼이 끝내 생각해 낸 방법인 거겠지.",
  ui_story_5080_50801301_57_dialog_content = "저 사람이 어떤 짐을 짊어지고 있는지 난 이해할 수 있어.",
  ui_story_5080_50801301_58_dialog_content = "사메야마──!",
  ui_story_5080_50801301_59_dialog_content = "이 멍청아── 들리냐?!",
  ui_story_5080_50801301_60_dialog_content = "사메야마?! 대답 좀 해 봐!",
  ui_story_5080_50801301_61_dialog_content = "로이, 저 아래 좀 봐! 용암 옆의 저 맨땅에 있는 거... 저거 사메야마 머리카락 아냐?!",
  ui_story_5080_50801301_62_dialog_content = "맞든 아니든 일단 가서 봐야겠어!",
  ui_story_5080_50801301_63_dialog_content = "로이! 거긴 용암이라고! 그렇게 뛰어내리면 어떡해!",
  ui_story_5080_50801301_64_dialog_content = "쳇, 됐어. 사메야마를 뛰어넘을 남자가 이럴 때 물러설 순 없지.",
  ui_story_5080_50801301_65_dialog_content = "나도 간다!",
  ui_story_5080_50801301_66_dialog_content = "으아아아아아아──",
  ui_story_5080_50801301_67_dialog_content = "사방이 온통 용암이잖아아!",
  ui_story_5080_50801301_68_dialog_content = "비켜! 다 비켜!",
  ui_story_5080_50801301_69_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5080_50801301_70_dialog_content = "하마터면 깔려 죽을 뻔했잖아...",
  ui_story_5080_50801301_71_dialog_content = "저기 봐, 사메야마야! 진짜 사메야마라고! 아직 살아 있어!",
  ui_story_5080_50801301_72_dialog_content = "사메야마, 너──",
  ui_story_5080_50801301_73_dialog_content = "온통... 암귀 시체들이잖아. 혼자서 다 해치운 거냐?",
  ui_story_5080_50801301_74_dialog_content = "높은 곳에서 추락하면서 부상이 심했을 텐데, 이렇게 잔뜩 해치우다니...",
  ui_story_5080_50801301_75_dialog_content = "여어, 왔냐... 방금 내가 이 큼지막한 놈을 끝장냈다고...",
  ui_story_5080_50801301_76_dialog_content = "사메야마?!",
  ui_story_5080_50801301_77_dialog_content = "사메야마, 정신 차려. 그놈은 이미 죽었어. 얼른 내려놓고 우리랑 가자고!",
  ui_story_5080_50801301_78_dialog_content = "어이! 사메야마?",
  ui_story_5080_50801301_79_dialog_content = "밥을 제대로 못 먹었더니... 또 배가 고프군...",
  ui_story_5080_50801301_80_dialog_content = "돌아가서 애들이랑 밥 먹고 싶다... 그래야 더 맛있는데 말이야...",
  ui_story_5080_50801301_81_dialog_content = "로이, 나 피곤해... 요 며칠 신경 쓸 일이 너무 많았나 봐...",
  ui_story_5080_50801301_82_dialog_content = "얼른 돌아가서 파티를 즐기자... 너무 오래 기다리게 만들면 안 된다고...",
  ui_story_5080_50801301_83_dialog_content = "이 자식 이거 왜 이래? 로이, 빨리 좀 봐봐! 이러다 뭔 일 나는 거 아냐?!",
  ui_story_5080_50801301_84_dialog_content = "...괜찮아. 너무 단숨에 힘을 쏟아부어서 지친 것뿐이야.",
  ui_story_5080_50801301_85_dialog_content = "어젯밤부터 사람 찾는다고 나갔다가 돌아와서도 뭐 하나 제대로 먹지도 못했으니까.\n고생이 많았지.",
  ui_story_5080_50801301_86_dialog_content = "흥, 그럼 그렇지. 이 녀석이 이렇게 약할 리가 없잖아.",
  ui_story_5080_50801301_87_dialog_content = "누가 뭐래도 넌 내가 쓰러트릴 거니까 말이야!",
  ui_story_5080_50801301_88_dialog_content = "자, 녀석을 내 등에 업혀 줘.",
  ui_story_5080_50801301_89_dialog_content = "나중에 일어났을 때 내 신세를 졌다는 걸 알면 분명히 엄청 부끄러워하겠지!",
  ui_story_5080_50801301_90_dialog_content = "그럼 부탁할게. 길은 내가 앞장설게. 얼른 돌아가서...",
  ui_story_5080_50801301_91_dialog_content = "잠깐만, 얘 렌치는 어딨지?",
  ui_story_5080_50801301_92_dialog_content = "추락하면서 어디로 굴러가 버린 건가... 찾아봐야겠어...",
  ui_story_5080_50801301_93_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5080_50801301_94_dialog_content = "방금 그거 들었어?",
  ui_story_5080_50801301_95_dialog_content = "용암 소리인가?",
  ui_story_5080_50801301_96_dialog_content = "<color=#e8d9bb>쿵── 쿵──</color>",
  ui_story_5080_50801301_97_dialog_content = "또야!",
  ui_story_5080_50801301_98_dialog_content = "...저건 발소리야. 렉커, 도망쳐!",
  ui_story_5080_50801301_99_dialog_content = "<color=#e8d9bb>쿵── 쿵── 쿵──</color>",
  ui_story_5080_50801301_100_dialog_content = "튀어!",
  ui_story_5080_50801302_1_dialog_content = "사람 살려어어어──!",
  ui_story_5080_50801302_2_dialog_content = "누구냐!",
  ui_story_5080_50801302_3_dialog_content = "누구야?",
  ui_story_5080_50801302_4_dialog_content = "오오! 일루미나 소대장이잖아! 로이! 얼른 이리 와!",
  ui_story_5080_50801302_5_dialog_content = "어떻게 된 거야?",
  ui_story_5080_50801302_6_dialog_content = "<size=45><color=#e8d9bb>쿵── 쿵── 쿵── 쿵── 쿵──</color></size>",
  ui_story_5080_50801302_7_dialog_content = "<color=#e8d9bb>크어어어──</color>",
  ui_story_5080_50801302_8_dialog_content = "암귀?! 아니... 저건 <color=#FFB400>타깃</color>이야!",
  ui_story_5080_50801302_9_dialog_content = "일루미나 아가씨, 도와줘서 고마워.",
  ui_story_5080_50801302_10_dialog_content = "화력 제압은 나한테 맡기고 어서 도망쳐. 다른 사람들은 바로 뒤에 있어!",
  ui_story_5080_50801302_11_dialog_content = "빨리 가자, 로이! 우리──",
  ui_story_5080_50801302_12_dialog_content = "조심해!",
  ui_story_5080_50801302_13_dialog_content = "크오오──",
  ui_story_5080_50801302_14_dialog_content = "교활한 놈... 총알받이가 되더라도 길은 막고 보겠다는 거냐.",
  ui_story_5080_50801302_15_dialog_content = "뭐야? 저 암귀가 길을 막아버렸어!",
  ui_story_5080_50801302_16_dialog_content = "저놈이... 아탈을 죽인 그 암귀인가...",
  ui_story_5080_50801302_17_dialog_content = "이브한테 맡겨!",
  ui_story_5080_50801302_18_dialog_content = "<color=#FFB400>토네이도!</color>",
  ui_story_5080_50801302_19_dialog_content = "<color=#e8d9bb>뇌전으로 갈라진 천장이 암귀를 덮치는 순간, 강력한 힘에 화산이 포효하며 다시 지진이 일어났다.</color>",
  ui_story_5080_50801302_20_dialog_content = "이 느낌... 큰일이야, 화산이 곧 분출할 거야!",
  ui_story_5080_50801302_21_dialog_content = "「레디젤 아가씨」, 계속 공격해!",
  ui_story_5080_50801302_22_dialog_content = "하지만 그러다간 화산이 폭발할 수도 있어!",
  ui_story_5080_50801302_23_dialog_content = "놈이 이미 깨어난 이상, 밖으로 나가게 된다면 더 많은 사람을 해치고 말 거야!",
  ui_story_5080_50801302_24_dialog_content = "분명히 맞혔는데 공격이 먹힌 느낌이 전혀 안 들어. 저 녀석, 약점이 어디 있는 거지?",
  ui_story_5080_50801302_25_dialog_content = "「호크헌터들」이 이미 확인했어. 녀석의 외피는 진짜 용암의 온도엔 미치지 않아.",
  ui_story_5080_50801302_26_dialog_content = "그리고 어떤 생물이든 먹이를 먹을 때 가장 무방비한 법이야.",
  ui_story_5080_50801302_27_dialog_content = "외피를 제거하면 놈은 다시 에너지를 흡수하려 들 거야. 그때 약점이 드러나겠지!",
  ui_story_5080_50801302_28_dialog_content = "그 당시엔 분명히 더 컸는데... 여기서 십여 년을 숨어놓고 왜 더 작아진 거지...?",
  ui_story_5080_50801302_29_dialog_content = "<color=#FFB400>죽음의 제도학!</color>",
  ui_story_5080_50801302_30_dialog_content = "<color=#FFB400>토네이도!</color>",
  ui_story_5080_50801302_31_dialog_content = "<color=#FFB400>속사!</color>",
  ui_story_5080_50801302_32_dialog_content = "<color=#FFB400>얼음의 꽃!</color>",
  ui_story_5080_50801302_33_dialog_content = "키에에엑──!",
  ui_story_5080_50801302_34_dialog_content = "먹혔어! 우리 공격이 효과가 있는 것 같아!",
  ui_story_5080_50801302_35_dialog_content = "<color=#e8d9bb>쿠르릉!</color>",
  ui_story_5080_50801302_36_dialog_content = "제길, 무너진 벽 틈으로 용암이 쏟아진다!",
  ui_story_5080_50801302_37_dialog_content = "조심해, 녀석이 용암 에너지를 흡수할 거야!",
  ui_story_5080_50801302_38_dialog_content = "렉커, 사메야마를 등에 업고 위로 달려! 이브, 너도 조심해!",
  ui_story_5080_50801302_39_dialog_content = "으아아앗! 내 로봇에 불붙었어!",
  ui_story_5080_50801302_40_dialog_content = "제타, 우리가 있어 봤자 방해만 될 뿐이야. 나랑 먼저 후퇴해!",
  ui_story_5080_50801302_41_dialog_content = "그치만 구세주 여주인공은 이런 순간에 퇴장할 순 없어!",
  ui_story_5080_50801302_42_dialog_content = "말 들어, 제타. 너도 아저씨 걱정시키고 싶진 않잖아?",
  ui_story_5080_50801302_43_dialog_content = "크에엑──",
  ui_story_5080_50801302_44_dialog_content = "암귀들이 둥지에서 쏟아져 나온다아아!",
  ui_story_5080_50801302_45_dialog_content = "아저씨까지 그렇게 말한다면... 도엔, 내가 엄호해 줄 테니까 나가자.\n가서 새로운 동료를 모아오는 거야!",
  ui_story_5080_50801302_46_dialog_content = "우리 오빠한테서 떨어져!",
  ui_story_5080_50801302_47_dialog_content = "이브, 뒤로 물러서. 예리아, 다들...",
  ui_story_5080_50801302_48_dialog_content = "내가 막을 테니까 너흰 사메야마를 데리고 철수해!",
  ui_story_5080_50801302_49_dialog_content = "예리아?",
  ui_story_5080_50801302_50_dialog_content = "저 암귀가 정말 아탈을 죽인 그놈이라면... 절대 가만둘 수 없어!",
  ui_story_5080_50801302_51_dialog_content = "잠깐만, 용암이 쏟아져 내리는데 녀석은 용암 에너지를 흡수하지 않고 있어... 왜지?",
  ui_story_5080_50801302_52_dialog_content = "심지어.... 용암을 피하고 있잖아?",
  ui_story_5080_50801302_53_dialog_content = "잠깐만, 바이스. 그쪽은 너무 위험해! 내 쪽으로 와!",
  ui_story_5080_50801302_54_dialog_content = "카렌, 녀석의 머리 위로 건너갈 다리를 만들어 줘!",
  ui_story_5080_50801302_55_dialog_content = "내가 엄호할게. 어서 가!",
  ui_story_5080_50801302_56_dialog_content = "<color=#FFB400>언령들이여!</color>",
  ui_story_5080_50801302_57_dialog_content = "크오오오──!",
  ui_story_5080_50801302_58_dialog_content = "동작이 느려졌어! 나도 도울게!",
  ui_story_5080_50801302_59_option_content = "(강제 감응!)",
  ui_story_5080_50801302_60_dialog_content = "새의 날개를 꺾어버린 죗값을... 치르게 해 주겠어!",
  ui_story_5080_50801302_61_dialog_content = "공주님, 지금이야!",
  ui_story_5080_50801302_62_dialog_content = "<color=#FFB400>얼음의 꽃!</color>",
  ui_story_5080_50801302_63_dialog_content = "용암 외피가 너무 뜨거워. 아직 부족해...",
  ui_story_5080_50801302_64_dialog_content = "그래도 효과가 있어. 지금 기세를 몰아서 계속 공격해야 해...",
  ui_story_5080_50801302_65_dialog_content = "호크헌터 1호, 호크헌터 3호, 미안해...",
  ui_story_5080_50801302_66_dialog_content = "<color=#FFB400>자폭 공격!</color>",
  ui_story_5080_50801302_67_dialog_content = "키에에엑──!",
  ui_story_5080_50801302_68_dialog_content = "(큰일이야, 용암 에너지가 너무 강해서 어떤 공격도 통하질 않아...)",
  ui_story_5080_50801302_69_dialog_content = "녀석이 내 제어를 벗어나려고 해...! 다들 조심해!",
  ui_story_5080_50801302_70_dialog_content = "(크윽... 머리가...)",
  ui_story_5080_50801302_71_dialog_content = " 동굴이 무너질 것 같아! 다들 당장 올라와!",
  ui_story_5080_50801302_72_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5080_50801302_73_dialog_content = "공간이 점점 뜨거워지고 있어, 이러다간... 크윽!",
  ui_story_5080_50801302_74_dialog_content = "공주님은 내가 받았어. 으윽... 어서 나가!",
  ui_story_5080_50801302_75_dialog_content = "이런! 카렌이랑 예리아 씨가 막혔어!",
  ui_story_5080_50801302_76_dialog_content = "조금 느리지만 길을 만들 수 있을 거야. 너희도 조심해!",
  ui_story_5080_50801302_77_dialog_content = "이럴 수가... 확실히 탐지했는데... 왜 놈의 에너지가 저렇게 커진 거지?",
  ui_story_5080_50801302_78_dialog_content = "설마 내가 잘못 판단한 건가...?",
  ui_story_5080_50801302_79_dialog_content = "싸우는 중에도 에너지를 끊임없이 채워나가고 있었던 거야...?",
  ui_story_5080_50801302_80_dialog_content = "용암이 덮칠 거야! 대장, 빨리 피해!",
  ui_story_5080_50801302_81_dialog_content = "먼저 가! 너희가 철수할 때까지 내가 엄호를 맡을 테니까!",
  ui_story_5080_50801302_82_dialog_content = "간다!",
  ui_story_5080_50801302_83_dialog_content = "<color=#FFB400>속사!</color>",
  ui_story_5080_50801302_84_dialog_content = "이쪽이라고!",
  ui_story_5080_50801302_85_dialog_content = "키에에엑──!",
  ui_story_5080_50801302_86_dialog_content = "해칠링 2호!",
  ui_story_5080_50801302_87_dialog_content = "바이스한테 손대지 마!",
  ui_story_5080_50801302_88_option_content = "(강제 감응!)",
  ui_story_5080_50801302_89_dialog_content = "해칠링 2호, 괜찮아? 정신 차려!",
  ui_story_5080_50801302_90_dialog_content = "(늘 효율을 가장 중시하던 사람이, 바이스 때문에 공격 기회를 포기했잖아...)",
  ui_story_5080_50801302_91_dialog_content = "나 참... 이런 상황에서 왜 오히려 기쁜 거냐고... 머리도 아픈데...",
  ui_story_5080_50801302_92_dialog_content = "이대로는 안 돼! 이브, 너희 먼저 가!",
  ui_story_5080_50801302_93_dialog_content = "간다!",
  ui_story_5080_50801302_94_dialog_content = "<color=#FFB400>알렌의 펀치!</color>",
  ui_story_5080_50801302_95_dialog_content = "공주님은 다리를 맡아줘!",
  ui_story_5080_50801302_96_dialog_content = "<color=#FFB400>토네이도!</color>",
  ui_story_5080_50801302_97_dialog_content = "성공이야! 이렇게 멀리서도 맞혔어!",
  ui_story_5080_50801302_98_dialog_content = "너무 뜨거워... 이 높이에선 밑에 상황이 전혀 보이질 않잖아.",
  ui_story_5080_50801302_99_dialog_content = "키에에엑──!",
  ui_story_5080_50801302_100_dialog_content = "녀석이 도망치려고 해!",
  ui_story_5080_50801302_101_dialog_content = "누구 맘대로!",
  ui_story_5080_50801302_102_dialog_content = "쫓아가지 마요, 예리아 씨! 지금 이 땅도 곧 용암에 삼켜질 거예요!",
  ui_story_5080_50801302_103_dialog_content = "...걱정 마. 길이 있으니까.",
  ui_story_5080_50801302_104_dialog_content = "언령들이 약한 벽을 찾았어, 이쪽이야.",
  ui_story_5080_50801302_105_dialog_content = "하아... 하아... 「얼음의 다리」가 세워졌어...",
  ui_story_5080_50801302_106_dialog_content = "지금 내 힘으로는 이 정도가 최선이야.",
  ui_story_5080_50801302_107_dialog_content = "해칠링은 내가 업고 갈 테니까... 다들 빨리 나가.",
  ui_story_5080_50801401_1_dialog_content = "<color=#FFB400>얼음의 꽃!</color>",
  ui_story_5080_50801401_2_dialog_content = "...어째서 부서지지 않는 거지?",
  ui_story_5080_50801401_3_dialog_content = "벽이 너무 뜨거워. 네 힘으로는 뚫기 어려울 거야.",
  ui_story_5080_50801401_4_dialog_content = "다 내 탓이야... 호크헌터 1호와 3호의 희생을 헛되게 만들었어.",
  ui_story_5080_50801401_5_dialog_content = "여긴 온도가 너무 높아서 나도 폭발물을 마음껏 챙겨올 순 없었어...",
  ui_story_5080_50801401_6_dialog_content = "시간을 좀 줘. 조금 더 정확한 값을 계산해서 폭파 작업을 준비해 볼게.",
  ui_story_5080_50801401_7_dialog_content = "로이, 보여? 다들 지금 저 길에서 발이 묶였어.",
  ui_story_5080_50801401_8_dialog_content = "이 각도에선 내 힘으로 공격할 수가 없어...",
  ui_story_5080_50801401_9_dialog_content = "안 돼, 이브. 네 힘은 범위가 너무 넓어.",
  ui_story_5080_50801401_10_dialog_content = "지금 우리 중에서 도움을 줄 수 있는 건 사메야마뿐이야. 내가 깨워볼게!",
  ui_story_5080_50801401_11_dialog_content = "로이, 건조식량 좀 다 줘봐!",
  ui_story_5080_50801401_12_dialog_content = "어? 오빠한테 뭘 하려고...?",
  ui_story_5080_50801401_13_dialog_content = "흐흐흐, 딱 보면 모르겠어? 그냥 입에다 전부 쑤셔 넣는 거지!",
  ui_story_5080_50801401_14_dialog_content = "우우우웁──",
  ui_story_5080_50801401_15_dialog_content = "그만해, 목 막혀 죽게 할 작정이냐?",
  ui_story_5080_50801401_16_dialog_content = "<size=45>당장 멈춰!</size>",
  ui_story_5080_50801401_17_dialog_content = "(바이스... 바이스... 이러지 마...)",
  ui_story_5080_50801401_18_dialog_content = "해칠링 2호, 해칠링 2호... 정신 차려!",
  ui_story_5080_50801401_19_dialog_content = "호크헌터 2호, 응급 구조 모드를 가동해. 전기 충격 2단계, 차지!",
  ui_story_5080_50801401_20_dialog_content = "<color=#FFB400>클리어!</color>",
  ui_story_5080_50801401_21_dialog_content = "으윽...",
  ui_story_5080_50801401_22_dialog_content = "무사했구나... 다행이야...",
  ui_story_5080_50801401_23_dialog_content = "해칠링 2호! 내 목소리 들려? 걱정 마, 내가 데리고 나가 줄 테니까...",
  ui_story_5080_50801401_24_dialog_content = "대장...",
  ui_story_5080_50801401_25_dialog_content = "해칠링 2호? 해칠링 2호?",
  ui_story_5080_50801401_26_dialog_content = "...이제 그만해, 레이첼!",
  ui_story_5080_50801401_27_dialog_content = "누군가의 마음을 「깨우려면」 적어도 상대의 이름 정도는 불러줘야 하는 거잖아!",
  ui_story_5080_50801401_28_dialog_content = "이름을 불러줘! 해칠링 2호 같은 게 아니라, 이름이 있잖아! 바이스, 바이스라고!",
  ui_story_5080_50801401_29_dialog_content = "아이테르 1호...",
  ui_story_5080_50801401_30_dialog_content = "난 뭐라고 부르든 상관없어... 하지만 바이스는 달라...",
  ui_story_5080_50801401_31_dialog_content = "바이스는 널 그렇게나 동경하고, 존경해서, 너랑 함께 임무를 맡게 된 걸 진심으로 기뻐했어.",
  ui_story_5080_50801401_32_dialog_content = "하지만 지금까지도 레이첼 넌 이름 한 번 불러준 적 없었잖아!",
  ui_story_5080_50801401_33_dialog_content = "......",
  ui_story_5080_50801401_34_dialog_content = "널 위해 혼자서 밤새 임무 보고서를 쓰고, 졸려 죽을 것 같아도 눈빛은 신이 나 있었어...\n그게 바로 바이스라고!",
  ui_story_5080_50801401_35_dialog_content = "자신의 이름조차 불러주지 않은 선배지만, 그런 선배와 이야기할 수 있는 것만으로도\n바이스는 진심으로 기뻐했어!",
  ui_story_5080_50801401_36_dialog_content = "저렇게나 상관들을 좋아하고, 칭찬받고 싶어 하는데... 잘못한 것도 없는데...\n고작 이름일 뿐이잖아. 넌 대체 뭘 그렇게 두려워하고 있는 거냐고...",
  ui_story_5080_50801401_37_dialog_content = "부탁이야. 적어도... 적어도 지금 이 순간만큼은 이름을 불러줘...",
  ui_story_5080_50801401_38_dialog_content = "...난 절대... 다시는 다른 사람과 불필요한 감정으로 얽혀선 안 돼.",
  ui_story_5080_50801401_39_dialog_content = "맹금류 아가씨...",
  ui_story_5080_50801401_40_dialog_content = "우린 이미 임무에서 벗어났어... 난... 더는 나 때문에 누군가 연루되는 게 싫어...",
  ui_story_5080_50801401_41_dialog_content = "...미안, 바이스는 이미 충분히 잘하고 있어. 전부 내 탓이야...",
  ui_story_5080_50801401_42_dialog_content = "더는 짐이 되고 싶지 않아... 나 때문에 누군가 죽는 게 만들고 싶지 않다고...",
  ui_story_5080_50801401_43_dialog_content = "또 새로운 관계를 맺고... 내 지휘 때문에 동료가 또 죽게 된다면... 난... 더는 견딜 수 없어...",
  ui_story_5080_50801401_44_dialog_content = "그런 게 아냐! 지금 책임을 따지자는 게 아니잖아!",
  ui_story_5080_50801401_45_dialog_content = "넌 늘 모두를 걱정하고 있었잖아. 그런데 왜 그 상냥함을 숨기려고 하는 거냐고!",
  ui_story_5080_50801401_46_dialog_content = "네가 상대에게 진심을 다했기 때문에, 상대도 목숨까지 아끼지 않고 널 지킨 거야.",
  ui_story_5080_50801401_47_dialog_content = "그게 왜 불필요한 감정이냐고...",
  ui_story_5080_50801401_48_dialog_content = "아이테르 1호, 넌 몰라...",
  ui_story_5080_50801401_49_dialog_content = "내가 왜 몰라?! 다른 사람이 나 때문에 희생되는 걸 보면서도 아무것도 할 수 없는 무기력함을...\n내가 모를 것 같아?!",
  ui_story_5080_50801401_50_dialog_content = "난 동족을 전부 잃었어. 어렵게 찾은 친구도 나 때문에...",
  ui_story_5080_50801401_51_dialog_content = "누군가를 잃는 그런 아픔, 고독한 자책감... 나도 잘 안다고, 레이첼...",
  ui_story_5080_50801401_52_dialog_content = "하지만 난 날 도와줬던 모든 사람에게 진심으로 감사해.\n그 도움 덕분에 나와 바이스, 그리고 동료들이 계속 나아갈 수 있었으니까.",
  ui_story_5080_50801401_53_dialog_content = "난 그게 절대 불필요한 감정이라고 생각하지 않아.",
  ui_story_5080_50801401_54_dialog_content = "모두를 만날 수 있어서 정말 다행이었어... 그리고 가능하다면...\n난 친구들의 이름을 부르고, 다시 이야기하고 싶어.",
  ui_story_5080_50801401_55_dialog_content = "PlayerName...",
  ui_story_5080_50801401_56_dialog_content = "그만해... 아이테르 1호...",
  ui_story_5080_50801401_57_dialog_content = "사람은 깊은 「사랑」을 품고 있기 때문에 다른 사람을 위해 희생할 수 있는 거야.",
  ui_story_5080_50801401_58_dialog_content = "널 지켰던 동료들, 그리고 바이스도... 절대 임무 같은 것 때문이 아니라고!",
  ui_story_5080_50801401_59_dialog_content = "그 사람들은 그저 널 지키고 싶었던 거야... 네가 잘 살아가는 것만으로도\n그들에겐 이미 그 무엇보다 큰 기쁨인 거야.",
  ui_story_5080_50801401_60_dialog_content = "그 프리버드의 대장처럼 말이야... 그 사람도 분명히 대원들에 대한 사랑 때문에,\n자신의 명예를 더럽히는 것도 마다하지 않고 동료들과 돌아온 거겠지.",
  ui_story_5080_50801401_61_dialog_content = "희생할 수 있는 건 그저 곁에 있는 사람을 지키고 싶어서일 뿐이야...",
  ui_story_5080_50801401_62_dialog_content = "겨우 서로를 이해할 수 있게 된 사람들한테 그거 말고 다른 이유가 있을 것 같아...?",
  ui_story_5080_50801401_63_dialog_content = "그만... 더는 듣고 싶지 않아... 난...",
  ui_story_5080_50801401_64_dialog_content = "너도 마음속으론 잘 알고 있잖아... 우릴 위해 위험을 무릅쓰고 나서는 자신을...",
  ui_story_5080_50801401_65_dialog_content = "설마 정말 그게 더 효율적이라서 그랬던 거야? 전혀 아니잖아...",
  ui_story_5080_50801401_66_dialog_content = "넌 그저 누군가가 다칠까 봐 두려운 거잖아... 그래서 모든 사람을 지키려고 최선을 다했던 거고...",
  ui_story_5080_50801401_67_dialog_content = "그런 거면... 왜 다른 사람들과의 관계를 계속 거부하는 거냐고...",
  ui_story_5080_50801401_68_dialog_content = "PlayerName... 울지 마... 더는 남은 힘도 없잖아...",
  ui_story_5080_50801401_69_dialog_content = "...이제 폭파 작업을 준비할게. 조금만 더 기다려 줘.",
  ui_story_5080_50801401_70_dialog_content = "맹금류 아가씨... 아니, 레이첼.",
  ui_story_5080_50801401_71_dialog_content = "사막에는 먼 곳으로 여행하는 새들이 종종 지나가곤 해...\n그중엔 가끔 무리에서 떨어지는 녀석들도 있지만, 언젠가는 자신의 무리로 돌아가.",
  ui_story_5080_50801401_72_dialog_content = "예전에는... 나도 이해하지 못했어. 하지만 지금은 알아.\n맹금류가 되는 길을 선택했어도, 여전히 동료를 만들 수 있다는걸...",
  ui_story_5080_50801401_73_dialog_content = "나, 난... 동료 같은 건 필요 없어...",
  ui_story_5080_50801401_74_dialog_content = "너 정말... 고집붙통이네...",
  ui_story_5080_50801401_75_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5080_50801401_76_dialog_content = "뭐야? 어디가 폭발한 거야?",
  ui_story_5080_50801401_77_dialog_content = "키에에엑──!",
  ui_story_5080_50801401_78_dialog_content = "위험해!",
  ui_story_5080_50801401_79_dialog_content = "레이첼! 내가 도와줄게!",
  ui_story_5080_50801401_80_dialog_content = "키에에엑──!",
  ui_story_5080_50801401_81_dialog_content = "이런... 놈이 바닥을 공격하고 있어.",
  ui_story_5080_50801401_82_dialog_content = "언령들아, 공주님을 올려줘!",
  ui_story_5080_50801401_83_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5080_50801401_84_dialog_content = "벽을 뚫었어! 빨리 따라와!",
  ui_story_5080_50801401_85_dialog_content = "다들 아직 아래에 있어!",
  ui_story_5080_50801401_86_dialog_content = "키에에엑──!",
  ui_story_5080_50801401_87_dialog_content = "내 동료들을... 또 해치게 내버려둘 것 같아?!",
  ui_story_5080_50801401_88_dialog_content = "PlayerName! 카렌이랑 전부 데리고 빨리 나가!",
  ui_story_5080_50801401_89_dialog_content = "레이첼... 드디어... 솔직해졌구나...",
  ui_story_5080_50801401_90_dialog_content = "어쩌면 정말로 몸은 더 솔직한 걸지도 모르겠네... 널 구하려고 공격을 막던 그 순간...",
  ui_story_5080_50801401_91_dialog_content = "더는 아닌 척할 수가 없다는 생각이 들었어.",
  ui_story_5080_50801401_92_dialog_content = "그러니까... 빨리 가.",
  ui_story_5080_50801401_93_dialog_content = "용암이 밀려올 거야. 아이테르 군, 얼른 내 손 잡아!",
  ui_story_5080_50801401_94_dialog_content = "메리... 루이... 리나... 테일즈... 다시 한번 내게 힘을 줘.",
  ui_story_5080_50801401_95_dialog_content = "친구들을 구할 수 있게!",
  ui_story_5080_50801401_96_dialog_content = "아니... 난 안 가...",
  ui_story_5080_50801401_97_dialog_content = "PlayerName?!",
  ui_story_5080_50801401_98_dialog_content = "아까 그랬잖아? 날 도와줬던 모든 사람에게 진심으로 감사한다고...\n그 인연은 무엇보다 소중한 거야...",
  ui_story_5080_50801401_99_dialog_content = "그러니까 난 어떤 동료도 포기하지 않아, 레이첼.",
  ui_story_5080_50801401_100_dialog_content = "...넌... 정말 명령을 안 듣는 병사네.",
  ui_story_5080_50801401_101_dialog_content = "하지만 기뻐, PlayerName...",
  ui_story_5080_50801401_102_dialog_content = "너희들과 같은 팀이 돼서 영광이야.",
  ui_story_5080_50801401_103_dialog_content = "같이 싸우자.",
  ui_story_5080_50801401_104_dialog_content = "카렌, 마지막 힘으로 우리가 있는 지면을 받쳐줘!",
  ui_story_5080_50801401_105_dialog_content = "예리아 씨, 언령들이 무너지는 벽을 지탱할 수 있겠죠?",
  ui_story_5080_50801401_106_dialog_content = "플뢰르, 너한테는 공격을 부탁할게.",
  ui_story_5080_50801401_107_dialog_content = "모두 함께 싸우는 거야.",
  ui_story_5080_50801402_1_dialog_content = "용암이 점점 거세게 밀려오고 있어. 이대로면 <color=#FFB400>얼음의 길</color>이... 갈라져 버릴 거야!",
  ui_story_5080_50801402_2_dialog_content = "거의 다 됐어! 녀석의 「갑옷」에 담긴 에너지가 거의 다 떨어져 가!",
  ui_story_5080_50801402_3_dialog_content = "이런! PlayerName! 레이첼!",
  ui_story_5080_50801402_4_dialog_content = "(이런... 용암 때문에 길이 끊겨서 다들 흩어져 버렸잖아...)",
  ui_story_5080_50801402_5_dialog_content = "신경 쓰지 마... 난 이제 무리인 것 같아... 너흰 플뢰르가 뚫은 구멍으로 어서 피해...",
  ui_story_5080_50801402_6_dialog_content = "무슨 멍청한 소릴 하고 있어? 좀 더 버텨, 지금 갈 테니까.",
  ui_story_5080_50801402_7_dialog_content = "하필 이런 곳이라니... 여기선 얼음다리를 다시 만들기 힘들어...",
  ui_story_5080_50801402_8_dialog_content = "<size=40>키에에엑!</size>",
  ui_story_5080_50801402_9_dialog_content = "괴물, 내가 비켜줄 것 같아? 총 한 자루만 남았다고 해도... 절대...",
  ui_story_5080_50801402_10_dialog_content = "<color=#e8d9bb>탕! 타앙!</color>",
  ui_story_5080_50801402_11_dialog_content = "<color=#e8d9bb>레이첼의 총알이 암귀의 몸을 향해 연달아 날아들었지만, 놈의 열에너지에 모두 막히고 말았다.</color>",
  ui_story_5080_50801402_12_dialog_content = "<color=#e8d9bb>철컥──</color>",
  ui_story_5080_50801402_13_dialog_content = "총알이... 떨어졌어...",
  ui_story_5080_50801402_14_dialog_content = "무기는 떨어졌지만... 주먹은 남았다고.",
  ui_story_5080_50801402_15_dialog_content = "PlayerName, 내 뒤로 피해. 한 걸음도 움직이지 마!",
  ui_story_5080_50801402_16_dialog_content = "레이첼... 어서 가... 난 틀린 것 같아...",
  ui_story_5080_50801402_17_dialog_content = "난... 절대 포기하지 않아!",
  ui_story_5080_50801402_18_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5080_50801402_19_dialog_content = "용암이 또 폭발했어. 화산이 곧... 잠깐만... 저건 뭐지?!",
  ui_story_5080_50801402_20_dialog_content = "렌치...? 사메야마의 렌치잖아?! 저게 왜 여기 있어?",
  ui_story_5080_50801402_21_dialog_content = "마침 잘됐네.",
  ui_story_5080_50801402_22_dialog_content = "그만둬, 레이첼. 그건 엄청 무겁다고! 무리하지 마!",
  ui_story_5080_50801402_23_dialog_content = "휴우, 후... 우리 돌아왔... 어어?!",
  ui_story_5080_50801402_24_dialog_content = "쟤 뭐야? 사메야마 녀석 렌치를 들었어? 너무 무리하는 거 아냐?!",
  ui_story_5080_50801402_25_dialog_content = "난... 하아... 억지로 버티는 대원이 제일 싫어...",
  ui_story_5080_50801402_26_dialog_content = "버티는 건... 내가 제일 좋아하는 거니까!",
  ui_story_5080_50801402_27_dialog_content = "키에에엑!",
  ui_story_5080_50801402_28_dialog_content = "내 대원들한테서 당장 꺼져──!",
  ui_story_5080_50801402_29_dialog_content = "크오오오!",
  ui_story_5080_50801402_30_dialog_content = "말도 안 돼... 사메야마 말고 저 렌치를 휘두르는 사람이 또 있다니...",
  ui_story_5080_50801402_31_dialog_content = "그어어... 크으으... 크어어어!",
  ui_story_5080_50801402_32_dialog_content = "아직도 안 죽었어?!",
  ui_story_5080_50801402_33_dialog_content = "그럼... 한 번 더...",
  ui_story_5080_50801402_34_dialog_content = "(안 돼... 느껴져... 레이첼은 이미 한계야... 무리라고...)",
  ui_story_5080_50801402_35_dialog_content = "절대... 절대 포기하지 않아... 받아라!",
  ui_story_5080_50801402_36_dialog_content = "크오오!",
  ui_story_5080_50801402_37_dialog_content = "얼음다리를... 조금만 더...!",
  ui_story_5080_50801402_38_dialog_content = "힘이 떨어졌어... 이러다간 둘 다...",
  ui_story_5080_50801402_39_dialog_content = "으아아아! 시끄러워 죽겠네! 쉬지도 못하게!",
  ui_story_5080_50801402_40_dialog_content = "...사메야마?!",
  ui_story_5080_50801402_41_dialog_content = "호오~ 아가씨, 기운이 넘치는데?",
  ui_story_5080_50801402_42_dialog_content = "이 렌치를 들 수 있다는 건 네게도 그만한 「힘」이 있다는 얘기지.",
  ui_story_5080_50801402_43_dialog_content = "그리고 그 「힘」을 다른 사람들을 위해 쓸 수 있다는 건,\n그 힘보다 더 빛나는 「의지」가 있다는 뜻이다.",
  ui_story_5080_50801402_44_dialog_content = "자! 마음에 품은 <color=#FFB400>대의</color>를 위해, <color=#FFB400>무한한 힘</color>을 휘둘러 보라고!",
  ui_story_5080_50801402_45_dialog_content = "<size=45>흐아아압──!</size>",
  ui_story_5080_50801402_46_dialog_content = "<color=#e8d9bb>콰아아앙!</color>",
  ui_story_5080_50801402_47_dialog_content = "(서로 다른 세계에 속한 두 사람이 지키고 싶다는 마음 때문에 렌치를 들어 올렸어...)",
  ui_story_5080_50801402_48_dialog_content = "(저 두 사람...)",
  ui_story_5080_50801402_49_dialog_content = "내 동료들한테서 손 떼!",
  ui_story_5080_50801402_50_dialog_content = "날 지나갈 수 있을 것 같아?!",
  ui_story_5080_50801402_51_dialog_content = "(처음엔 당신을 이해할 수 없었던 사람도 지금 이 순간 저 렌치를 들고 있어──)",
  ui_story_5080_50801402_52_dialog_content = "(훗... 당신들의 의지는 여기까지 이어졌어... 아탈...)",
  ui_story_5080_50801402_53_dialog_content = "(저게 바로... <color=#FFB400>레디젤 렌치</color>인 거야.)",
  ui_story_5080_50801402_54_dialog_content = "드디어 해치웠네... 용암이 밀려들 거야. 얼른 나가자.",
  ui_story_5080_50801402_55_dialog_content = "마지막 얼음다리를 만들었어, 가자.",
  ui_story_5080_50801402_56_dialog_content = "어이! 여기야, 여기!",
  ui_story_5080_50801402_57_dialog_content = "이쪽으로 와! 쇠사슬로 위쪽이랑 연결해 뒀으니까 기어 올라가면 돼!",
  ui_story_5080_50801402_58_dialog_content = "PlayerName... 우리도 가자... 으윽!",
  ui_story_5080_50801402_59_dialog_content = "어이, 괜찮냐? 온몸이 상처투성이면서 무리하더니, 이제 기운이 완전히 빠진 모양이지?",
  ui_story_5080_50801402_60_dialog_content = "어쩔 수 없지. 어때? 「레디젤 수괴」의 손, 잡을 수 있겠냐?",
  ui_story_5080_50801402_61_dialog_content = "......",
  ui_story_5080_50801402_62_dialog_content = "어이!",
  ui_story_5080_50801402_63_dialog_content = "<color=#e8d9bb>그 순간, 거대한 바위가 두 사람을 스치고 용암 속으로 떨어졌다.</color>",
  ui_story_5080_50801402_64_dialog_content = "...누가... 못 일어난대? 당신, 「일루미나 군대개미」의 손은 잡을 수 있겠어?",
  ui_story_5080_50801402_65_dialog_content = "하하하하하! 거 봐, 억지로 꾸민 모습보다 훨씬 귀엽잖아.",
  ui_story_5080_50801402_66_dialog_content = "고작 바위 따위가 날 어떻게 할 것 같냐... 그래도 상처가 났다면 이브가 또 걱정했겠지.",
  ui_story_5080_50801402_67_dialog_content = "고맙다.",
  ui_story_5080_50801402_68_dialog_content = "저기, 미안한데... 내가 잡을 테니까 아무나 그 손 좀 줄래?\n감응 능력으로 힘을 다 썼더니 기운이 아예 없어...",
  ui_story_5080_50801402_69_dialog_content = "......",
  ui_story_5080_50801402_70_dialog_content = "후훗...",
  ui_story_5080_50801402_71_dialog_content = "하하하하!",
  ui_story_5080_50801402_72_dialog_content = "거기서 그만 웃고 얼른 나오라고!",
  ui_story_5080_50801402_73_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_5080_50801402_74_dialog_content = "푸하! 드디어 나왔네! 흐음~ 이 신선한 공기, 쾌적한 기온!",
  ui_story_5080_50801402_75_dialog_content = "으앗?! 너네 어떻게 이렇게 빠른 거야?!",
  ui_story_5080_50801402_76_dialog_content = "역시 너희 먼저 가라고 하길 잘했다니까. 너희 길 찾는 능력은 정말이지...",
  ui_story_5080_50801402_77_dialog_content = "제타가 안내한 거야.",
  ui_story_5080_50801402_78_dialog_content = "뭐, 뭔데?! 난 랠리의 전설이라구! 동굴 타는 게 좀 어설퍼도 그게 뭐 어때서!",
  ui_story_5080_50801402_79_dialog_content = "하하하하하──!",
  ui_story_5080_50801402_80_dialog_content = "야! 광전사! 웃지 마!",
  ui_story_5080_50801402_81_dialog_content = "안 웃을 수가 없잖아, 제타.",
  ui_story_5080_50801402_82_dialog_content = "으앗?! 로이까지 날 놀리다니...!",
  ui_story_5080_50801402_83_dialog_content = "이거 이래서야 파티 시간에 맞출 수 있겠어? 젠장!",
  ui_story_5080_50801402_84_dialog_content = "뭘 여기서 꾸물거리고 있어? 먼저 파티를 열었을지도 모르잖아!",
  ui_story_5080_50801402_85_dialog_content = "그런 게 있었어? 그럼 제타가 얼른 데리고 돌아가 줄게!",
  ui_story_5080_50801402_86_dialog_content = "빨리 타!",
  ui_story_5080_50801402_87_dialog_content = "안녕── 요나──",
  ui_story_5080_50801402_88_dialog_content = "아주르?",
  ui_story_5080_50801402_89_dialog_content = "뭐야, 간만에 돌아왔는데 여기 왜 이렇게 조용해?",
  ui_story_5080_50801402_90_dialog_content = "잠깐만! 거긴──",
  ui_story_5080_50801402_91_dialog_content = "<color=#e8d9bb>콰앙! 콰콰쾅──!!!</color>",
  ui_story_5080_50801402_92_dialog_content = "<color=#e8d9bb>함정이 폭발하자 모든 지뢰 구역에서 연쇄 반응이 일어났고,\n순식간에 캠프 전체가 완전히 다른 모습으로 변하고 말았다.</color>",
  ui_story_5080_50801402_93_dialog_content = "거긴 지뢰 구역이라고...",
  ui_story_5080_50801402_94_dialog_content = "뭐, 뭐야?",
  ui_story_5080_50801402_95_dialog_content = "캠프가 왜 이 꼴이 된 거야? 어... 오늘 밤 파티 열 수 있겠어?",
  ui_story_5080_50801402_96_dialog_content = "으아아아악!",
  ui_story_5080_50801402_97_dialog_content = "이 멍청이들아! 대체 무슨 짓을 한 거냐아아!",
  ui_story_5080_50801402_98_dialog_content = "그냥 작은 계산 착오라구! 대장──!",
  ui_story_5080_50801402_99_dialog_content = "거기 서! 이 자식들아! 절대 가만두지 않겠어!",
  ui_story_5080_50801402_100_dialog_content = "자자, 애들은 놔두고, 일단 먹을 만한 게 있는지부터 확인하는 게 어때?",
  ui_story_5080_50801402_101_dialog_content = "흐아앙──! 훌쩍... 바바라... 바바라의 무대가──!",
  ui_story_5080_50801402_102_dialog_content = "괜찮아! 울지 마! 고칠 수 있을지 내가 봐 줄 테니까...",
  ui_story_5080_50801402_103_dialog_content = "후후, 「마녀」 너한테도 이렇게 엉망인 날이 올 줄이야!",
  ui_story_5080_50801402_104_dialog_content = "이 제타 님이 얼마나 멋진 공을 세웠는지 넌 절대 모를걸?!",
  ui_story_5080_50801402_105_dialog_content = "...하아, 됐어... 다시 볼 수 있어서 언니는 정말 기쁘니까.",
  ui_story_5080_50801402_106_dialog_content = "이게 다 뭐야...",
  ui_story_5080_50801402_107_dialog_content = "정말...",
  ui_story_5080_50801402_108_dialog_content = "어? 레이첼? 레이첼!",
  ui_story_5080_50801402_109_dialog_content = "뭐야? 어디 좀 보자...",
  ui_story_5080_50801402_110_dialog_content = "아, 괜찮아. 한 번에 긴장이 풀려서 잠깐 기절한 모양이야.",
  ui_story_5080_50801402_111_dialog_content = "얘 드론은 왜 또 고장 난 거야? 흥, 오디! 이참에 똑똑히 봐 둬, 내 정밀한 수리 실력을!",
  ui_story_5080_50801402_112_dialog_content = "네 차례가 오기나 할 것 같아?",
  ui_story_5080_50801402_113_dialog_content = "여긴... 자난성?",
  ui_story_5080_50801402_114_dialog_content = "내가 언제 돌아온 거지...",
  ui_story_5080_50801402_115_dialog_content = "대장~ 대장~",
  ui_story_5080_50801402_116_dialog_content = "너...너희들?",
  ui_story_5080_50801402_117_dialog_content = "화이트구스... 아니, 메리.. 너희...",
  ui_story_5080_50801402_118_dialog_content = "아, 정말 오랜만이네... 어?!",
  ui_story_5080_50801402_119_dialog_content = "대장, 왜... 왜 우는 거예요?",
  ui_story_5080_50801402_120_dialog_content = "미안... 정말 미안해... 줄곧 너희들한테 직접 말하고 싶었어...",
  ui_story_5080_50801402_121_dialog_content = "난 좋은 대장이 아냐... 나 때문에... 너희들이...",
  ui_story_5080_50801402_122_dialog_content = "아하하, 대장이 우는 거 보게 될 줄은 생각도 못 했어요.",
  ui_story_5080_50801402_123_dialog_content = "나도 처음 봤어... 다시는 안 봤으면 좋겠는데 말이야.",
  ui_story_5080_50801402_124_dialog_content = "살아남은 게 대장이라서 정말 다행입니다.",
  ui_story_5080_50801402_125_dialog_content = "대장을 구할 수 있어서 얼마나 기뻤는지 몰라요.",
  ui_story_5080_50801402_126_dialog_content = "게다가 지금의 대장, 전보다 더 완벽해졌는걸요. 모든 사람을 지켰잖아요.",
  ui_story_5080_50801402_127_dialog_content = "역시 대장은 최고의 대장이에요.",
  ui_story_5080_50801402_128_dialog_content = "너희들...",
  ui_story_5080_50801402_129_dialog_content = "대장을 만나서 정말 좋았어.",
  ui_story_5080_50801402_130_dialog_content = "누가 아니래~ 그 많은 소대 중에서 대장한테 뽑혀서 정말 행복했다니까.",
  ui_story_5080_50801402_131_dialog_content = "그러니까 대장도 행복해야 해.",
  ui_story_5080_50801402_132_dialog_content = "어디... 가는 거야? 돌아와! 내 말 들어...",
  ui_story_5080_50801402_133_dialog_content = "돌아가세요, 대장. 지금 대장이 붙잡아야 할 사람은 우리가 아닙니다.",
  ui_story_5080_50801402_134_dialog_content = "부디 잘 살아주세요. 많이 웃고. 그럼 더는 바랄 게 없을 겁니다!",
  ui_story_5080_50801402_135_dialog_content = "기다려! 가지 마... 제발!",
  ui_story_5080_50801402_136_dialog_content = "대장──",
  ui_story_5080_50801402_137_dialog_content = "기다려!",
  ui_story_5080_50801402_138_dialog_content = "대장──!",
  ui_story_5080_50801402_139_dialog_content = "넌...",
  ui_story_5080_50801402_140_dialog_content = "바이스?",
  ui_story_5080_50801402_141_dialog_content = "대장...?",
  ui_story_5080_50801402_142_dialog_content = "무사했구나... 정말 다행이야.",
  ui_story_5080_50801402_143_dialog_content = "잠깐만! 대장, 방금... 내 이름을 부른 거야?",
  ui_story_5080_50801402_144_dialog_content = "우와아── 대장, 대장!",
  ui_story_5080_50801402_145_dialog_content = "<color=#e8d9bb>기뻐서 울음을 터뜨리는 바이스는 레이첼을 힘껏 껴안았고,\n빳빳하게 굳은 레이첼의 반응 같은 것은 전혀 신경 쓰지 않았다.</color>",
  ui_story_5080_50801402_146_dialog_content = "(그래도... 저 진심에는 절대 반응을 안 할 수도 없겠지.)",
  ui_story_5080_50801402_147_dialog_content = "괜찮아... 이제 다 괜찮아...",
  ui_story_5080_50801402_148_dialog_content = "고마워, 바이스.",
  ui_story_5080_50801402_149_dialog_content = "고마워, 모두.",
  ui_story_5080_50801500_1_dialog_content = "우린 스스로를 지키기 위해 그 암귀를 해치웠어.\n하지만 지진은 오히려 가라앉았고, 화산은 여전히 폭발하지 않았어.",
  ui_story_5080_50801500_2_dialog_content = "그 말은... 아직도 뭔가가 화산의 에너지를 누르고 있다는 건가?",
  ui_story_5080_50801500_3_dialog_content = "나도 그저 추측일 뿐이야. 떠나기 전에 언령들이 발견한 게 있거든.",
  ui_story_5080_50801500_4_dialog_content = "너희가 암귀를 때려잡은 곳이 부서지고 나서, 그 아래에 길이 하나 있었어.",
  ui_story_5080_50801500_5_dialog_content = "화산 내핵에 또 회랑이 있었단 말이에요?",
  ui_story_5080_50801500_6_dialog_content = "하지만 지금은 용암에 뒤덮인 상태라 조사할 수 없을 거야.",
  ui_story_5080_50801500_7_dialog_content = "...로이는 이번의 그놈이 과거의 그 암귀가 아니라고 생각하더군.",
  ui_story_5080_50801500_8_dialog_content = "맞아, 이번 녀석은 지형 문제만 아니었다면 그렇게 상대하기 어렵진 않았을 테니까.\n만약 녀석이 과거의 그 암귀였다면, 아탈은 절대 죽지 않았을 거야...",
  ui_story_5080_50801500_9_dialog_content = "아무래도 진상은 더 깊은 곳에 있는 모양이네.",
  ui_story_5080_50801500_10_dialog_content = "우리의 진짜 <color=#FFB400>적</color>은... 그 안에 숨어있을 가능성이 높다.",
  ui_story_5080_50801500_11_dialog_content = "용암이 식고, 다들 회복하고 나면 같이 조사하러 가자.",
  ui_story_5080_50801500_12_dialog_content = "레디젤 렌치 사람들도 저런 활화산 아래에서 자려면 불안할 거잖아?",
  ui_story_5080_50801500_13_dialog_content = "그거야 모르지... 우린 하나같이 오늘만 사는 멍청이들인데, 그런 거 따질 겨를이 있겠어?",
  ui_story_5080_50801500_14_dialog_content = "무대 다 고쳤어... 지금까지 일하느라 힘들어 죽을 지경이라고!",
  ui_story_5080_50801500_15_dialog_content = "괜찮아, 나한테 맡겨! 내 열정으로 밤하늘을 불태워버릴 테니까──!",
  ui_story_5080_50801500_16_dialog_content = "하아? 제타?! 너, 너...",
  ui_story_5080_50801500_17_dialog_content = "너 그 화장은 뭐야?",
  ui_story_5080_50801500_18_dialog_content = "어? 제타를 성숙한 어른으로 만들어주겠다고 마녀가 해 준 건데?!",
  ui_story_5080_50801500_19_dialog_content = "설마... 이, 이 못된 마녀!",
  ui_story_5080_50801500_20_dialog_content = "가지 마! 내 백댄서 해 주기로 했잖아! 이제 곧 무대에 올라가서 그 녀석과 대결해야 한다구!",
  ui_story_5080_50801500_21_dialog_content = "렉커, 잘 봤겠죠? 다들 굶주려 있습니다.",
  ui_story_5080_50801500_22_dialog_content = "지금 재료를 가장 먼저 손질하는 사람이 바로 대혼돈을 잠재울 해결사가 되는 겁니다.\n다들 분명히 엄청~ 엄청 존경할 거라구요.",
  ui_story_5080_50801500_23_dialog_content = "오오오! 그래! 재료 손질은 이미 마스터했다고! 잘 봐!",
  ui_story_5080_50801500_24_dialog_content = "<size=28>...뭐야, 어떻게 이렇게 잘 속는 거지...</size> 렉커! 여기 야채세척기도 있는데 살 겁니까?",
  ui_story_5080_50801500_25_dialog_content = "캠프가 엉망이네. 이브도 돕고 싶어.",
  ui_story_5080_50801500_26_dialog_content = "나도 할래.",
  ui_story_5080_50801500_27_dialog_content = "비켜, 비켜! 내 공을 낚아챌 생각은 포기하라고!",
  ui_story_5080_50801500_28_dialog_content = "그냥 다 하게 내버려둬. 또 소란 안 피우게.",
  ui_story_5080_50801500_29_dialog_content = "아주르── 아주르── 어디 있어?",
  ui_story_5080_50801500_30_dialog_content = "창고를 거의 다 털어 왔어! 오늘 밤은 나랑 취할 때까지 마셔야지!",
  ui_story_5080_50801500_31_dialog_content = "정말 시끄러운 녀석들이라니까...",
  ui_story_5080_50801500_32_dialog_content = "난 말이지, 애초에 진짜 토박이도 아니고, 그냥 도중에 굴러들어 온 애송이일 뿐이었어.",
  ui_story_5080_50801500_33_dialog_content = "아스트라는 이렇게 크지만... 갈 곳 없는 이브와 날 받아준 곳은 이곳뿐이었지.",
  ui_story_5080_50801500_34_dialog_content = "갖은 고생 끝에 이제야 드디어 자기 힘으로 자급자족할 수 있게 됐고,\n가족으로서 함께 살게 된 거지.",
  ui_story_5080_50801500_35_dialog_content = "더는 사람들 눈치를 볼 필요도, 거절당하는 걸 두려워할 필요도 없게 됐다고.",
  ui_story_5080_50801500_36_dialog_content = "흐음... 그런 이야기를 네 입으로 듣는 건 처음인 것 같네.",
  ui_story_5080_50801500_37_dialog_content = "우리 같은 괴짜들이 모래알처럼 필사적으로 한데 섞여 있는 걸 봐라.\n많은 피를 흘렸다고 해도 틀린 말은 아냐. 그리고 그건 우리들이 피를 나눈 사이란 걸 증명하겠지.",
  ui_story_5080_50801500_38_dialog_content = "그래서 난 저 녀석들과 함께 하루하루를 보낼 수 있어서 즐겁다고.",
  ui_story_5080_50801500_39_dialog_content = "어떤 시련이 닥치든 함께 노력해서 멋지게 사는 것, 그게 바로 우리의 자유인 거다!",
  ui_story_5080_50801500_40_dialog_content = "그래서 난 매일 이렇게 소란을 피울 수 있게, 렌치를 들고 우릴 방해하는 놈들을 막아설 거다.",
  ui_story_5080_50801500_41_dialog_content = "사메야마... 당신은 꽤 괜찮은 리더야.",
  ui_story_5080_50801500_42_dialog_content = "그래서 부탁하고 싶은 게 있어. 비록 난 내 임무를 완수했지만, 아직은 부족하단 생각이 들어.",
  ui_story_5080_50801500_43_dialog_content = "만약 여기 아직도 위험이 남아 있다면, 나도 당신들과 함께 해결하고 싶어.",
  ui_story_5080_50801500_44_dialog_content = "게다가 당신들 전임 두목이 내 고모를 구했으니까, 나도 그 사람의 한을 풀어주고 싶어.",
  ui_story_5080_50801500_45_dialog_content = "그럼 대답해 봐라. 지금의 넌 「희생」의 의미를 깨달은 거냐?",
  ui_story_5080_50801500_46_dialog_content = "훗...",
  ui_story_5080_50801500_47_dialog_content = "응? 우린 왜 보는 건데?",
  ui_story_5080_50801500_48_dialog_content = "난 결심했어. 더는 대원들이 걱정하지 않게, 희생에 대해 가볍게 말하지 않을 거야.",
  ui_story_5080_50801500_49_dialog_content = "하지만... 우리가 여전히 위험에 빠져 있다면, 난 내 곁의 사람들을 위해 목숨을 걸고 싸울 거야.",
  ui_story_5080_50801500_50_dialog_content = "나와 손잡고 함께 걸어가는 사람들을 어떻게 해서든 지키고 싶어.",
  ui_story_5080_50801500_51_dialog_content = "일루미나의 군인인 우린 임무나 명예를 위해 싸운 게 아니야.",
  ui_story_5080_50801500_52_dialog_content = "눈앞의 모든 것을 「지키고」 싶었을 뿐이지.",
  ui_story_5080_50801500_53_dialog_content = "레이첼...",
  ui_story_5080_50801500_54_dialog_content = "자신을 태워 길을 밝히는 촛불처럼 다른 사람의 미래를 스스로 비춰주는 것,\n그게 바로 일루미나의 대의야!",
  ui_story_5080_50801500_55_dialog_content = "과거의 사람들은 다른 사람의 도움을 받았고, 또 다른 사람을 위해 희생했어.\n나 역시 예외는 아냐!",
  ui_story_5080_50801500_56_dialog_content = "앞으로도 난 지키고 싶은 마음을 위해 싸우고, 일루미나를 지키는 방패가 되겠어.",
  ui_story_5080_50801500_57_dialog_content = "하는 말은 별반 다를 게 없어 보이는데, 눈빛은 제법 그럴듯해졌잖아.",
  ui_story_5080_50801500_58_dialog_content = "지금의 넌 스스로 선택한 게 확실한 거냐?",
  ui_story_5080_50801500_59_dialog_content = "일루미나의 신조는 「하나는 우리, 우리는 하나」야.",
  ui_story_5080_50801500_60_dialog_content = "하지만 왜 싸워야 하는지, 왜 희생해야 하는지는 우리 자신의 의지로 결정할 수 있어.",
  ui_story_5080_50801500_61_dialog_content = "그 마음은 영원히 거짓이 아니야...... 아!",
  ui_story_5080_50801500_62_dialog_content = "지금의 넌 아직 마음속 여명의 빛을 찾을 수 있나?",
  ui_story_5080_50801500_63_dialog_content = "왜 그래, 레이첼 대장? 혹시 아직도 어디 아파?",
  ui_story_5080_50801500_64_dialog_content = "...아냐. 걱정하지 마, 바이스.",
  ui_story_5080_50801500_65_dialog_content = "그저... 드디어 그 질문에 어떻게 대답해야 할지 깨달은 것뿐이니까.",
  ui_story_5080_50801500_66_dialog_content = "질문...?",
  ui_story_5080_50801500_67_dialog_content = "훗... 보아하니 너도 자신이 뭘 찾고 있는지 이제 좀 깨달은 모양이군.",
  ui_story_5080_50801500_68_dialog_content = "좋아. 네가 조사에 참여하는 걸 동의하지.",
  ui_story_5080_50801500_69_dialog_content = "하지만 너도 상처가 낫기 전까진 조급하게 굴지 말라고.",
  ui_story_5080_50801500_70_dialog_content = "오늘 밤은 여기서 든든히 먹고, 잠도 푹 자둬라. 푹 쉰 뒤에 다시 이야기하자고.",
  ui_story_5080_50801500_71_dialog_content = "그래... 그런데...",
  ui_story_5080_50801500_72_dialog_content = "?",
  ui_story_5080_50801500_73_dialog_content = "비록 우리가 협력하게 된 건 맞지만, 레디젤 렌치가 또다시 악행을 벌인다면,\n내가 끝까지 추궁하겠어!",
  ui_story_5080_50801500_74_dialog_content = "그리고 그 렌치가 상징하는 의지를 너희가 더럽힌다면,\n나한테 렌치를 내놓을 각오도 하는 게 좋을 거야.",
  ui_story_5080_50801500_75_dialog_content = "으엑...",
  ui_story_5080_50801500_76_dialog_content = "자신 있으면 어디 가져가 보라고.",
  ui_story_5080_50801500_77_dialog_content = "정말이지, 너희 일루미나 놈들은 역시 제정신이 아니라니까.",
  ui_story_5080_50801500_78_dialog_content = "아하하하하!",
  ui_story_5080_50801500_79_dialog_content = "뭘 웃는 거냐.",
  ui_story_5080_50801500_80_dialog_content = "사메야마 당신이 그렇게 황당해하는 건 처음 봤거든... 하, 하하하!",
  ui_story_5080_50801500_81_dialog_content = "어휴, 정말...",
  ui_story_5080_50801500_82_dialog_content = "대장, 대장! 이거 좀 봐!",
  ui_story_5080_50801500_83_dialog_content = "캠프 잔해를 수습하다가 찾은 건데, 전임 대장이 남긴 일기 같아.",
  ui_story_5080_50801500_84_dialog_content = "아까 폭발로 터진 상자에서 찾았어... 지금까지 숨겨져 있었던 것 같아.",
  ui_story_5080_50801500_85_dialog_content = "...알았어. 아무튼 여기부터 좀 치우자고.",
  ui_story_5080_50801500_86_dialog_content = "지금은 파티 시간이다. 다른 일은 내일 다시 생각해── 가자!",
  ui_story_5080_50801500_87_dialog_content = "알았어, 알았다고! 밀지 마... 아파!",
  ui_story_5080_50801500_88_dialog_content = "이번엔 내가 웃을 차례라고! 하하하하하──",
  ui_story_5080_50801500_89_dialog_content = "맹금류 아가씨, 잠깐만.",
  ui_story_5080_50801500_90_dialog_content = "왜 그래?",
  ui_story_5080_50801500_91_dialog_content = "아탈이 내게 들려준 이야기의 마지막 부분을 네게 말해주고 싶어.",
  ui_story_5080_50801500_92_dialog_content = "그해 아탈은 동료들을 구하기 위해 임무를 포기한 뒤 일루미나를 떠났어.\n목표를 잃은 아탈은 한동안 무작정 떠돌아다녔지.",
  ui_story_5080_50801500_93_dialog_content = "그러다가 어느새 자신이 임무를 실패하도록 만든 숙적의 사막에 우연히 들어오게 됐어.",
  ui_story_5080_50801500_94_dialog_content = "아탈은 자기가 이 사막에서 태어났다고 했어. 여긴 무법천지지만 그만큼 자유롭다는 것도 알고 있었어. 여기서 살아본 적은 없었지만 말이야.",
  ui_story_5080_50801500_95_dialog_content = "그래서 이곳에 무척 와보고 싶었다고 해.\n자신을 위해 희생된 대원들이 편히 쉴 안식처를 찾아주고 싶어서 말이야...",
  ui_story_5080_50801500_96_dialog_content = "......",
  ui_story_5080_50801500_97_dialog_content = "그렇게 사막을 떠돌던 아탈은 도적 떼도 만나고, 엉겁결에 사람들을 이끌고 암귀와도 싸웠어.\n그러다가 그 전설의 렌치를 줍게 됐지.",
  ui_story_5080_50801500_98_dialog_content = "아탈은 사람들을 위해 렌치를 들고, 사막의 도적 떼를 규합해서 이 땅의 혼란을 잠재웠어.",
  ui_story_5080_50801500_99_dialog_content = "그들과 함께 오아시스에 정착하며 렌치에 얽힌 전설에 대해서도 알게 됐고 말이야.",
  ui_story_5080_50801500_100_dialog_content = "그래서 아탈은 오아시스에서 채취한 레디젤로 렌치를 붉게 칠하고,\n정식으로 「레디젤 렌치」를 세웠던 거야.",
  ui_story_5080_50801500_101_dialog_content = "아탈은 아주 잘 지냈어. 진정한 자유를 찾았을 뿐만 아니라,\n마지막 순간에는 모두를 지키기 위해 목숨을 잃었어.",
  ui_story_5080_50801500_102_dialog_content = "왜 그걸... 나한테 알려주는 거지?",
  ui_story_5080_50801500_103_dialog_content = "돌아가서 네 고모에게 알려줘.",
  ui_story_5080_50801500_104_dialog_content = "네 고모가 모시던 대장은 아무런 이유 없이 배신한 게 아니라,\n늘 다른 누군가의 자유를 위해 무기를 들었던 사람이야.",
  ui_story_5080_50801500_105_dialog_content = "그게 네 고모에게 조금의 위로라도 될 수 있기를 바랄게.",
  ui_story_5080_50801500_106_dialog_content = "고마워... 그 외엔 달리 표현할 말을 잘 모르겠지만, 고마워.",
  ui_story_5080_50801500_107_dialog_content = "노래해, 맹금류 아가씨. 설마 노랫소리가 안 들리는 거야?",
  ui_story_5080_50801500_108_dialog_content = "노랫소리...?",
  ui_story_5080_50801500_109_dialog_content = "붙타 올라라, 사랑하는 낙원, 우리의 집──♪",
  ui_story_5080_50801500_110_dialog_content = "노래를, 부르자, 내일의 세상이 만신창이가 된다고 해도──♪",
  ui_story_5080_50801500_111_dialog_content = "목소리를 높여 노래하자... 그것이 바로... 생명의 힘──♪",
  ui_story_5080_50801500_112_dialog_content = "레이첼 대장~ 여기야~! 파티가 곧 시작될 거야!",
  ui_story_5080_50801500_113_dialog_content = "훗... 갈게!",
  ui_story_5080_50801500_114_dialog_content = "...그럼 이제 슬슬...",
  ui_story_5080_50801500_115_dialog_content = "어딜 가려고? 받아.",
  ui_story_5080_50801500_116_dialog_content = "이건...",
  ui_story_5080_50801500_117_dialog_content = "선인장 전갈구이다. 맛있다고, 분명히 못 먹어봤겠지.",
  ui_story_5080_50801500_118_dialog_content = "...내가 모르는 곳에서 너희들도 많은 걸 찾으려고 노력했구나.",
  ui_story_5080_50801500_119_dialog_content = "흥, 그거야 당연하지.",
  ui_story_5080_50801500_120_dialog_content = "저기... 예리아, 간만에 집에 왔으면 다 같이 밥이나 먹자고.",
  ui_story_5080_50801500_121_dialog_content = "...아무래도 이번 파티는 피하긴 힘들 것 같네. 그렇지?",
  ui_story_5080_50801500_122_dialog_content = "두말하면 잔소리지! 빨리 와!",
  ui_story_5080_50801500_123_dialog_content = "레이첼! 여기야, 여기! 자리 맡아놨어.",
  ui_story_5080_50801500_124_dialog_content = "고기가 익으면 잽싸게 움직여야 되거든. 다들 먹을 거 앞에선 인정사정 안 봐준다니까!",
  ui_story_5080_50801500_125_dialog_content = "고마워... 너희들.",
  ui_story_5080_50801500_126_dialog_content = "뭐야? 뭐 이 정도 가지고.",
  ui_story_5080_50801500_127_dialog_content = "아니... 너희가 줄곧 날 받아줘서 고마워.",
  ui_story_5080_50801500_128_dialog_content = "악수하자, 이것도 일루미나의 예법이야.",
  ui_story_5080_50801500_129_dialog_content = "...응!",
  ui_story_5080_50801500_130_dialog_content = "이상해. 넌 세상에 흔하지 않은 아이테르인데, 왜 익숙하다는 느낌이 드는 걸까?",
  ui_story_5080_50801500_131_dialog_content = "나한테 딱히 불만도 없고... 왠지 넌 일루미나 사람에 대해 잘 알고 있는 것 같아.",
  ui_story_5080_50801500_132_dialog_content = "(어디서부터 말해야 되나? 우리의 여정... 그람 씨, 레비, 라인하르트 씨, 바튼 씨, 그리고 모두들...)",
  ui_story_5080_50801500_133_dialog_content = "PlayerName, 지금이야, 방금 말해준 대로.",
  ui_story_5080_50801500_134_dialog_content = "응!",
  ui_story_5080_50801500_135_dialog_content = "여명의 빛을 위하여! 경례!",
  ui_story_5080_50801500_136_dialog_content = "나랑 바이스를 구해줘서 고마워!",
  ui_story_5080_50801500_137_dialog_content = "그 경례는 대체 어느 부대 경례인 건데...?\n후훗, 아무래도 너흰 정말 많은 일을 함께 겪은 모양이네. 그러니까 전설의 콤비인 거고.",
  ui_story_5080_50801500_138_dialog_content = "이제 알겠어, 대원수님께서 왜 너희가 특별하다고 하셨는지...",
  ui_story_5080_50801500_139_dialog_content = "하지만 지금 너흰 내 동료야...",
  ui_story_5080_50801500_140_dialog_content = "그럼 이제 같이 파티를 즐겨보자!",
  ui_story_5080_50801500_141_dialog_content = "<color=#e8d9bb>레디젤 렌치의 노랫소리는 거칠지만, 더없이 자유롭고, 자유와 낭만이 있었다.\n그 열정은 사막을 불태웠고, 하늘 위로는 밤새 신나는 노랫소리가 울려 퍼졌다.</color>",
  ui_story_5080_50801500_142_dialog_content = "메리... 루이... 테일즈... 리나, 너희들도 들려?",
  ui_story_5080_50801500_143_dialog_content = "저들은 이곳 사막이 모든 영혼을 품어줄 수 있는 땅이라고 했어... 그러니까...",
  ui_story_5080_50801500_144_dialog_content = "분명히 너희들도 품어줄 거야.",
  ui_story_5080_50801500_145_dialog_content = "마음껏 날아가 줘... 자유의 밤 속으로.",
  ui_story_5080_50801500_146_dialog_content = "너희의 영혼이 편히 쉴 때까지."
}
return config
